    #region  CellModel Class

    /// <summary>
    /// This GridCellModel supports entering formulas in a grid cell. This support is provided
    /// through the <see cref="GridFormulaCellModel.Engine"/> member of this class. Engine is
    /// a <see cref="GridFormulaEngine"/>.
    /// </summary>
    /// <remarks>
    /// The default behavior is that any cell whose CellType is GridFormulaCellModel will
    /// be interpreted as a formula cell provided the text in the cell starts with '='. 
    /// So, for such cells you would enter formulas such as
    /// =A1+A2+A3 or =Sum(A1:A3), an an attempt would be made to parse and compute the entry.
    /// <para/>
    /// Alternatively, you can use the <see cref="GridFormulaCellModel.formulaChar"/> character
    /// to specify which cells of CellType GridFormulaCellModel are to be used as formulas.
    /// You set this formulaChar private property through the class constructor which passes
    /// this parameter. If you set this value to '\0', every cell of CellType GridFormulaCellModel
    /// will be treated as a formula.
    /// <para/>
    /// The <see cref="RefreshCells"/> method redraws all the formula cells that depend upon
    /// a particular cell. This method is called when the user changes a value that affects
    /// other formula cells.
    /// <para/>
    /// The <see cref="GetFormattedText"/> method is where the actual calculations are done,
    /// if necessary, through calls to the Engine methods. This method also conditionally
    /// parses the formula only if it has been modified since the previous parse.
    /// </remarks>
    [Serializable]
    public class GridFormulaCellModel : GridTextBoxCellModel
    {
        /// <summary>
        /// Gets <see cref="GridFormulaEngine"/> encapsulates all formula features. Use this object
        /// to add / remove library functions.
        /// </summary>
        public GridFormulaEngine Engine
        {
            get
            {
                return engine;
            }
        }

        private GridFormulaEngine engine;
        private GridModel gridModel;

        /// <summary>
        /// Set this field to a particular character such as '=' to conditionally flag a cell
        /// whose CellType is GridFormulaCellModel as holding a formula. If you do not 
        /// set this field, then all cells of CellType GridFormulaCellModel that begin with '='
        /// will be treated as a formula. You set this private field as the call constructor. 
        /// If you set this value to '\0', every cell of CellType GridFormulaCellModel
        /// will be treated as a formula.
        /// </summary>
        private char formulaChar;

        /// <overload>
        /// Initializes a new GridFormulaCellModel object.
        /// </overload>
        /// <summary>
        /// Use this constructor to force all cells of CellType GridFormulaCellModel whose
        /// text begin with '=' to be regarded as holding formulas.
        /// </summary>
        /// <param name="grid">The GridModel using this GridFormulaCellModel.</param>
        public GridFormulaCellModel(GridModel grid)
            : this(grid, '=')
        {
            this.gridModel = grid;
        }

        /// <summary>
        /// Only cells whose contents begin with formulaChar will be treated as a formula.
        /// Other cells of CellType GridFormulaCellModel will be treated as GridTextBoxCellModel.
        /// The character formulaChar is ignored for parsing and computing purposes.
        /// </summary>
        /// <param name="grid">The GridModel using this GridFormulaCellModel.</param>
        /// <param name="formulaChar">Any GridFormulaCellModel beginning with this
        /// character will be treated as a formula. If you set this value to '\0', 
        /// every cell of CellType GridFormulaCellModel
        /// will be treated as a formula.</param>
        public GridFormulaCellModel(GridModel grid, char formulaChar)
            : base(grid)
        {
#if DEBUG
            if (Switches.FormulaCell.TraceVerbose)
            {
                TraceUtil.TraceCurrentMethodInfo(formulaChar);
            }
#else
            ;
#endif
            this.gridModel = grid;
            this.formulaChar = formulaChar;
            engine = new GridFormulaEngine(grid);
            Engine.formulaChar = formulaChar;

            ////Used to compute dependent cells.
            Grid.CellsChanged += new GridCellsChangedEventHandler(GridCellsChanged);

            ////Used to adjust formula references.
            Grid.ClipboardPasted += new GridCutPasteEventHandler(GridClipboardPasted);
            Grid.ClipboardPaste += new GridCutPasteEventHandler(GridClipboardPaste);
            Grid.ColsInserted += new GridRangeInsertedEventHandler(GridColsInserted);
            Grid.ColsRemoved += new GridRangeRemovedEventHandler(GridColsRemoved);
            Grid.RowsInserted += new GridRangeInsertedEventHandler(GridRowsInserted);
            Grid.RowsRemoved += new GridRangeRemovedEventHandler(GridRowsRemoved);

            ////Handle copy to copy formulas / values according to GridFormulaCopyFlags.
            Grid.ClipboardCopy += new GridCutPasteEventHandler(GridClipboardCopy);

            ////handle d&d reference updates
            if (Grid.ActiveGridView != null)
            {
                Grid.ActiveGridView.DragDrop += new DragEventHandler(GridDragDrop);
            }
        }

        /// <summary>
        /// Initializes a new <see cref="GridFormulaCellModel"/> from a serialization stream.
        /// </summary>
        /// <param name="info">An object that holds all the data needed to serialize or deserialize this instance.</param>
        /// <param name="context">Describes the source and destination of the serialized stream specified by info. </param>
        protected GridFormulaCellModel(SerializationInfo info, StreamingContext context)
            : base(info, context)
        {
#if DEBUG
            if (Switches.Serialization.TraceVerbose)
            {
                TraceUtil.TraceCurrentMethodInfo(info.FullTypeName, info.MemberCount);
            }
#else
            ;
#endif
            this.formulaChar = (char)info.GetValue("FormulaChar", typeof(char));
        }

        /// <summary>
        /// Constructor for use with an existing GridFormulaEngine.
        /// </summary>
        /// <param name="grid">The GridModel using this GridFormulaCellModel.</param>
        /// <param name="engine">An existing GridFormulaEngine.</param>
        /// <param name="formulaChar">Any GridFormulaCellModel beginning with this
        /// character will be treated as a formula. If you set this value to '\0', 
        /// every cell of CellType GridFormulaCellModel
        /// will be treated as a formula.</param>
        /// <remarks>Use this constructor if you want to use derived GridFormulaCellModel
        ///  and GridFormulaCellRenderer classes that share a single GridFormulaEngine.
        /// </remarks>
        public GridFormulaCellModel(GridModel grid, GridFormulaEngine engine, char formulaChar)
            : this(grid, formulaChar)
        {
            ////unsubscribe to the baseclass events...
            Grid.CellsChanged -= new GridCellsChangedEventHandler(GridCellsChanged);
            Grid.ClipboardPasted -= new GridCutPasteEventHandler(GridClipboardPasted);
            Grid.ClipboardPaste -= new GridCutPasteEventHandler(GridClipboardPaste);
            Grid.ColsInserted -= new GridRangeInsertedEventHandler(GridColsInserted);
            Grid.ColsRemoved -= new GridRangeRemovedEventHandler(GridColsRemoved);
            Grid.RowsInserted -= new GridRangeInsertedEventHandler(GridRowsInserted);
            Grid.RowsRemoved -= new GridRangeRemovedEventHandler(GridRowsRemoved);
            Grid.ClipboardCopy -= new GridCutPasteEventHandler(GridClipboardCopy);
            if (Grid.ActiveGridView != null)
            {
                Grid.ActiveGridView.DragDrop -= new DragEventHandler(GridDragDrop);
            }

            this.engine = null;
            this.engine = engine;
        }

        /// <summary>
        /// Called from GridModel implementation of IDeserializationCallback.OnDeserialization.
        /// </summary>
        /// <param name="sender">The source of the event.</param>
        /// <param name="model">The <see cref="GridModel"/> that was deserialized.</param>
        protected override void OnModelDeserialization(object sender, GridModel model)
        {
            base.OnModelDeserialization(sender, model);

            ////Now we can instantiate the engine since we have a reference to the gridModel.
            engine = new GridFormulaEngine(model);
            Engine.formulaChar = this.formulaChar;
            model.CellsChanged += new GridCellsChangedEventHandler(GridCellsChanged);
            model.ClipboardPasted += new GridCutPasteEventHandler(GridClipboardPasted);
            model.ClipboardPaste += new GridCutPasteEventHandler(GridClipboardPaste);
            model.ColsInserted += new GridRangeInsertedEventHandler(GridColsInserted);
            model.ColsRemoved += new GridRangeRemovedEventHandler(GridColsRemoved);
            model.RowsInserted += new GridRangeInsertedEventHandler(GridRowsInserted);
            model.RowsRemoved += new GridRangeRemovedEventHandler(GridRowsRemoved);
            model.ClipboardCopy += new GridCutPasteEventHandler(GridClipboardCopy);
            if (model.ActiveGridView != null)
            {
                model.ActiveGridView.DragDrop += new DragEventHandler(GridDragDrop);
            }
        }

        /// <summary>
        /// Implements the ISerializable interface and returns the data needed to serialize the cell model.
        /// </summary>
        /// <param name="info">A SerializationInfo object containing the information required to serialize the cell model.</param>
        /// <param name="context">A StreamingContext object containing the source and destination of the serialized stream.</param>
        [SecurityPermissionAttribute(SecurityAction.Demand, SerializationFormatter = true)]
        [SecurityPermissionAttribute(SecurityAction.LinkDemand, SerializationFormatter = true)]
        public override void GetObjectData(SerializationInfo info, StreamingContext context)
        {
#if DEBUG
            if (Switches.Serialization.TraceVerbose)
            {
                TraceUtil.TraceCurrentMethodInfo(info.FullTypeName, info.MemberCount);
            }
#else
            ;
#endif
            info.AddValue("FormulaChar", this.formulaChar); // FormulaChar
            base.GetObjectData(info, context);
        }

        /// <summary>
        /// This method forces any formula cell dependent upon the passed-in cell in the row
        /// and column to be recomputed. This method is called by the model whenever
        /// the contents of the passed-in cell is changed. For example, the user changing a
        /// single non-formula cell may require the recomputing of several additional formula cells. 
        /// This method triggers the redrawing of these dependent cells.
        /// </summary>
        /// <param name="row">Row index of the cell that was modified by the user.</param>
        /// <param name="col">Column index of the cell that was modified by the user.</param>
        public void RefreshCells(int row, int col)
        {
            if (CalculatingSuspended)
            {
                return;
            }

            GridSheetFamilyItem family = GridFormulaEngine.GetSheetFamilyItem(this.gridModel);
#if DEBUG
            if (Switches.FormulaCell.TraceVerbose)
            {
                TraceUtil.TraceCurrentMethodInfo(row, col, this);
            }
#else
            ;
#endif
            string sheet = family.GridModelToToken != null
                        ? family.GridModelToToken[this.Grid] as string : string.Empty;
            string s = sheet + GridRangeInfo.GetAlphaLabel(col) + row.ToString();

            Engine.Refresh(s);
        }

        /// <summary>
        /// Recalculates every cell that depends upon any cell in the passed-in range.
        /// </summary>
        /// <remarks>Calls the Engine.RefreshRange.</remarks>
        /// <param name="range">GridRangeInfo object to be refreshed.</param>
        public void RefreshRange(GridRangeInfo range)
        {
            Engine.RefreshRange(range);
        }

        /// <summary>
        /// Gets or sets a value indicating whether formulas are immediately calculated as dependent cells are changed.
        /// </summary>
        /// <remarks>Use this property to suspend calculations while a series of changes 
        /// are made to dependent cells either by the user or programmatically. When the changes are 
        /// complete, set this property to false, and then call RecalculateRange to recalculate
        /// the affected range. 
        /// <para/> 
        /// The implementation delegates this property to the Engine.CalculatingSuspended property.
        /// </remarks>
        /// <example> Use this code to suspend, and then later resume, calculations.
        /// <code lang="C#">
        ///        //suspend calculations...
        ///        GridFormulaCellModel formulaModel = this.gridControl1.CellModels["FormulaCell"] as GridFormulaCellModel;
        ///        formulaModel.CalculatingSuspended = true;
        ///  <para/>       
        ///        ....
        ///        //make changes, say to, cells in the GridRangeInfo.Cells(1,1,10,20).
        ///        ....
        /// <para/>        
        ///        //later resume calculations and refresh any cells that depend on GridRangeInfo.Cells(1,1,10,20)
        ///        GridFormulaCellModel formulaModel = this.gridControl1.CellModels["FormulaCell"] as GridFormulaCellModel;
        ///        formulaModel.CalculatingSuspended = false;
        ///        formulaModel.RefreshRange(GridRangeInfo.Cells(1,1,10,20));
        ///  <para/>        
        /// </code>
        /// <code lang="VB">
        ///        'suspend calculations...
        ///        Dim formulaModel As GridFormulaCellModel = Me.gridControl1.CellModel("FormulaCell") 
        ///        formulaModel.CalculatingSuspended = True
        /// <para/>                                        
        ///        ....
        ///        'make changes, say to, cells in the GridRangeInfo.Cells(1,1,10,20).
        ///        ....
        /// <para/>        
        ///        'later resume calculations and refresh any cells that depend on GridRangeInfo.Cells(1,1,10,20)
        ///        Dim formulaModel As GridFormulaCellModel = Me.gridControl1.CellModel("FormulaCell") 
        ///        formulaModel.CalculatingSuspended = False
        ///        formulaModel.RefreshRange(GridRangeInfo.Cells(1, 1, 10, 2))
        /// <para/>        
        /// </code>
        /// </example>
        public bool CalculatingSuspended
        {
            get { return Engine.CalculatingSuspended; }
            set { Engine.CalculatingSuspended = value; }
        }

        /// <summary>
        /// Recalculates any formula cells in the specified range.
        /// </summary>
        /// <remarks>The implementation is delegated to Engine.RecalculateRange.</remarks>
        /// <param name="range">GridRangeInfo object that specifies the cells to be recalculated.</param>
        public void RecalculateRange(GridRangeInfo range)
        {
            this.Engine.RecalculateRange(range, false);
        }

        /// <summary>
        /// Recalculates any formula cells in the specified range.
        /// </summary>
        /// <remarks>The implementation is delegated to Engine.RecalculateRange.</remarks>
        /// <param name="range">GridRangeInfo object that specifies the cells to be recalculated.</param>
        /// <param name="forceCalculations">Determines whether the calculation is performed 
        /// immediately or delayed until the next time the cell is drawn.</param>
        public void RecalculateRange(GridRangeInfo range, bool forceCalculations)
        {
            this.Engine.RecalculateRange(range, forceCalculations);
        }

        ////Used to tell GetFormattedText to return formula.
        private bool copyFormulasToClipboard = false;

        ////used to track sheet where a copy took place
        private string lastCopiedSheetName = string.Empty;

        /// <summary>
        /// Specifies if the clipboard buffer came from cut operation or not.
        /// </summary>
        private bool fromClipboardCut = false;

        ////Used to copy formulas / values according to GridFormulaCopyFlags.
        private void GridClipboardCopy(object sender, GridCutPasteEventArgs e)
        {
            if (Grid.Model.CommandStack.CurrentTransactionCommand != null && Grid.Model.CommandStack.CurrentTransactionCommand.Description.Equals(SR.GetString("GRID_IDM_CUTDATA")))
            {
                fromClipboardCut = true;
                Engine.fromClipboardCut = true;
            }
            else
            {
                fromClipboardCut = false;
                Engine.fromClipboardCut = false;
            }
            ////Need to handle the copy if formula text wanted.
            if (0 != (Engine.FormulaCopyFlags & GridFormulaCopyFlags.ClipBoardFormula)
                && !this.copyFormulasToClipboard)
            {
                if (this.Grid.Model.SelectedRanges.ActiveRange.Width == 1 &&
                    this.Grid.Model.SelectedRanges.ActiveRange.Height == 1 &&
                    this.Grid.Model.ActiveGridView.CurrentCell.HasCurrentCell &&
                    this.Grid.Model.ActiveGridView.CurrentCell.IsEditing && this.Grid.Model.ActiveGridView.CurrentCell.Renderer.Control is TextBoxBase
                    )
                {
                    //just copy the selected text if any...
                    if (((TextBoxBase)this.Grid.Model.ActiveGridView.CurrentCell.Renderer.Control).SelectedText.Length > 0)
                    {
                        Clipboard.SetText(((TextBoxBase)this.Grid.Model.ActiveGridView.CurrentCell.Renderer.Control).SelectedText);
                    }
                    else
                    {
                        Clipboard.Clear();
                    }
                    e.Handled = true;
                    e.Result = true;
                }
                else
                {
                    this.copyFormulasToClipboard = true;
                    this.Grid.Model.CutPaste.Copy();
                    this.copyFormulasToClipboard = false;
                    e.Handled = true;
                    e.Result = true;
                }
            }

            if (Engine.IsSheeted)
            {
                GridSheetFamilyItem family = GridFormulaEngine.GetSheetFamilyItem(this.gridModel);
                string token = family.GridModelToToken[sender as GridModel] as string;
                lastCopiedSheetName = family.TokenToSheetName[token] as string;
            }
        }

        ////used to handle reference updating during a D&D
        private void GridDragDrop(object sender, DragEventArgs e)
        {
            if (0 != (Engine.FormulaCopyFlags & GridFormulaCopyFlags.UpdateReferencesDuringDnD))
            {
                GridControlBase g = sender as GridControlBase;
                if (g != null && g.Model.DragDropData.dndSource)
                {
                    GridModel grid = g.Model;
                    int targetRow, targetCol;
                    System.Drawing.Point pt = grid.ActiveGridView.PointToClient(Control.MousePosition);
                    if (grid.ActiveGridView.PointToRowCol(pt, out targetRow, out targetCol))
                    {
                        if (grid.SelectedRanges.ActiveRange.IsCols)
                        {
                            targetRow = grid.Model.Rows.HeaderCount + 1;
                            targetCol = grid.SelectedRanges.ActiveRange.Left;
                        }
                        else if (grid.SelectedRanges.ActiveRange.IsRows)
                        {
                            targetRow = grid.SelectedRanges.ActiveRange.Top;
                            targetCol = grid.Model.Cols.HeaderCount + 1;
                        }
                        else
                        {
                            targetRow = targetRow - grid.DragDropData.dndRowOffset;
                            targetCol = targetCol - grid.DragDropData.dndColOffset;
                        }

                        foreach (GridRangeInfo range in grid.DragDropData.dndSelList)
                        {
                            int row, col;
                            if (range.GetFirstCell(out row, out col))
                            {
                                int rowOffSet = targetRow - row;
                                int colOffSet = targetCol - col;
                                AdjustFormulasForDnD(grid, row, col, rowOffSet, colOffSet);
                                while (range.GetNextCell(ref row, ref col))
                                {
                                    AdjustFormulasForDnD(grid, row, col, rowOffSet, colOffSet);
                                }
                            }
                        }

                        grid.Refresh();
                    }
                }
            }
        }

        private const string validLeadingChars = "=(*&+-/^ ,";
        private const string validTrailingChars = ")*&+-/^ ,";

        ////adjusts reference during a D&D
        private void AdjustFormulasForDnD(GridModel grid2, int row, int col, int rowOffSet, int colOffSet)
        {
            GridSheetFamilyItem family = GridFormulaEngine.GetSheetFamilyItem(grid2);

            string gridToken = family.isSheeted ? family.GridModelToToken[grid2].ToString() : string.Empty;
            string source = string.Format("{0}{1}", GridRangeInfo.GetAlphaLabel(col), row, gridToken);
            string tokenSource = gridToken.Length > 0 ? gridToken + source : source;

            if (this.engine.DependentCells.ContainsKey(tokenSource))
            {
                string target = string.Format("{0}{1}", GridRangeInfo.GetAlphaLabel(col + colOffSet), row + rowOffSet);
                Hashtable ht = this.engine.DependentCells[tokenSource] as Hashtable;
                this.engine.DependentCells.Remove(tokenSource);
                Hashtable saveCells = new Hashtable();
                foreach (string s in ht.Keys)
                {
                    if (this.engine.DependentFormulaCells.ContainsKey(s))
                    {
                        Hashtable ht1 = (Hashtable)this.engine.DependentFormulaCells[s];
                        if (ht1 != null && ht1.ContainsKey(tokenSource))
                        {
                            ht1.Remove(tokenSource);
                        }
                    }

                    string sheet = engine.SheetToken(s);
                    GridModel grd1 = (sheet.Length == 0)
                                      ? grid2 : family.TokenToGridModel[sheet] as GridModel;
                    int r = this.engine.RowIndex(s);
                    int c = this.engine.ColIndex(s);
                    string formulaString = grd1[r, c].Text;
                    if (formulaString.Length > 0 && formulaString[0] == this.formulaChar)
                    {
                        string upperString = formulaString.ToUpper();
                        int i = -1;
                        int offset = 0;
                        if (gridToken.Length > 0)
                        {
                            ////first replace all full references
                            string sheetName = family.TokenToSheetName[gridToken].ToString();
                            string sheetSource = sheetName.ToUpper() + GridFormulaEngine.sheetToken + source;
                            string sheetTarget = sheetName.ToUpper() + GridFormulaEngine.sheetToken + target;
                            i = upperString.IndexOf(sheetSource);
                            while (i > -1)
                            {
                                bool swap = true;
                                if (i > 0)
                                {
                                    swap = validLeadingChars.IndexOf(upperString[i - 1]) > -1;
                                }

                                if (swap && i + sheetSource.Length < upperString.Length)
                                {
                                    swap = validTrailingChars.IndexOf(upperString[i + sheetSource.Length]) > -1;
                                }

                                if (swap)
                                {
                                    formulaString = formulaString.Substring(0, i + sheetName.Length + 1 + offset) + target
                                        + ((i + sheetSource.Length < formulaString.Length) ?
                                        formulaString.Substring(i + sheetSource.Length + offset) : string.Empty);
                                    offset += target.Length - source.Length;
                                }

                                i = upperString.IndexOf(sheetSource, i + 1);
                            }
                        }

                        i = upperString.IndexOf(source);
                        offset = 0;
                        while (gridToken == sheet && i > -1)
                        {
                            bool swap = true;
                            if (i > 0)
                            {
                                swap = validLeadingChars.IndexOf(upperString[i - 1]) > -1;
                            }

                            if (swap && i + source.Length < upperString.Length)
                            {
                                swap = validTrailingChars.IndexOf(upperString[i + source.Length]) > -1;
                            }

                            if (swap)
                            {
                                formulaString = formulaString.Substring(0, i + offset) + target
                                    + ((i + source.Length < formulaString.Length) ?
                                    formulaString.Substring(i + source.Length + offset) : string.Empty);
                                offset += target.Length - source.Length;
                            }

                            i = upperString.IndexOf(source, i + 1);
                        }

                        grd1[r, c].Text = formulaString;
                        grd1[r, c].FormulaTag = null;
                        ////savecell for refreshing
                        if (!saveCells.ContainsKey(GridRangeInfo.Cell(r, c)))
                        {
                            saveCells.Add(GridRangeInfo.Cell(r, c), grd1);
                        }
                    }
                }

                if (this.engine.DependentFormulaCells.ContainsKey(tokenSource))
                {
                    this.engine.DependentFormulaCells.Remove(tokenSource);
                }

                ////do the refresh
                foreach (GridRangeInfo range in saveCells.Keys)
                {
                    GridModel g = saveCells[range] as GridModel;
                    this.Engine.RecalculateRange(range, g, true, true, false);
                }

                saveCells.Clear();
            }
        }

        ////Used to update references.
        private void GridColsInserted(object sender, GridRangeInsertedEventArgs e)
        {
            this.Engine.AdjustReferencesForRangeChange(sender as GridModel, true, true, e.InsertAt, e.InsertAt + e.Count - 1, false);
        }

        /////Used to update references.
        private void GridColsRemoved(object sender, GridRangeRemovedEventArgs e)
        {
            this.Engine.AdjustReferencesForRangeChange(sender as GridModel, true, false, e.From, e.To, true);
        }

        ////Used to update references.
        private void GridRowsInserted(object sender, GridRangeInsertedEventArgs e)
        {
            this.Engine.AdjustReferencesForRangeChange(sender as GridModel, false, true, e.InsertAt, e.InsertAt + e.Count - 1, false);
        }

        ////Used to update references.
        private void GridRowsRemoved(object sender, GridRangeRemovedEventArgs e)
        {
            this.Engine.AdjustReferencesForRangeChange(sender as GridModel, false, false, e.From, e.To, true);
        }

        ////Used to end editing on CurrentCell and update pasted cells after paste.
        private void GridClipboardPasted(object sender, GridCutPasteEventArgs e)
        {
            if (Grid != null && Grid.ActiveGridView != null)
            {
                GridCurrentCell gcc = Grid.ActiveGridView.CurrentCell;
                if (gcc.HasCurrentCell && gcc.IsEditing && gcc.Renderer is GridFormulaCellRenderer)
                {
                    gcc.Renderer.ResetControlText();
                    string text = gcc.Renderer.ControlText;
                    Grid.ActiveGridView.RefreshRange(gcc.RangeInfo, true);
                }

                if (gcc.HasCurrentCell)
                {
                    //raise this event so any listeners (Like GridAwareTextBox knows the cell has changed because of the paste)
                    Grid.ActiveGridView.RaiseCurrentCellChanged();

                    if (fromClipboardCut)
                    {
                        //recalculates the pasted range
                        DataObject data = (DataObject)Clipboard.GetDataObject();
                        if (data.GetDataPresent(DataFormats.Text))
                        {
                            string s = (string)data.GetData(DataFormats.Text);
                            string[] rows = s.Split(new char[] { '\n' });
                            int numRows = rows.GetLength(0);
                            if (numRows > 0 && rows[numRows - 1].Length == 0)
                                numRows--; //remove extra empty row if present
                            int numCols = 0;
                            if (numRows > 0)
                            {
                                string[] cols = rows[0].Split(new char[] { '\t' });
                                numCols = cols.GetLength(0);
                            }
                            this.Engine.RecalculateRange(GridRangeInfo.Cells(gcc.RangeInfo.Top, gcc.RangeInfo.Left, gcc.RangeInfo.Top + numRows - 1, gcc.RangeInfo.Left + numCols - 1), true, false);
                        }
                        Clipboard.Clear();
                    }
                }

                ////TODO: **** use code below to only update new cells...
                ////Grid.ActiveGridView.Refresh();
            }

            //Refresh invisible range
            IDataObject dataObject = e.DataObject;
            if(dataObject != null)
                dataObject.GetData(typeof(string));
            
            this.isPaste = false;
            Engine.inPaste = false;
        }

        ////Used to set paste flag
        private bool isPaste = false;

        private void GridClipboardPaste(object sender, GridCutPasteEventArgs e)
        {
            if (Grid.CurrentCellInfo != null)
            {
                GridCurrentCell gcc = Grid.CurrentCellInfo.CellView.CurrentCell;
                if (gcc.HasCurrentCell && e.RangeList != null && e.RangeList.ActiveRange.Width == 1 && e.RangeList.ActiveRange.Height == 1 && !gcc.IsEditing)
                {
                    //if a single cell and not  editing, just let the grid copy the style and avoid copying the current cell text
                    e.IgnoreCurrentCell = true;
                }
            }
            this.isPaste = true;
            Engine.inPaste = true;
        }

        ////Used to redraw cells changed in SaveCellInfo.
        private void GridCellsChanged(object sender, GridCellsChangedEventArgs e)
        {
#if DEBUG
            if (Switches.FormulaCell.TraceVerbose)
            {
                TraceUtil.TraceCurrentMethodInfo(e, this);
            }
#else
            ;
#endif
           
            if (e.Range.IsCells)
            {
                if (this.gridModel != null && this.gridModel.ActiveGridView!=null && !this.gridModel.ActiveGridView.IsVisibleCell(e.Range.Top, e.Range.Left)
                    && this.Engine.DependentCells.Count > 0
                    && (this.Engine.FormulaCopyFlags & GridFormulaCopyFlags.InsDelRangeReferencesUpdated) != GridFormulaCopyFlags.None)
                {
                    GridStyleInfo style = this.gridModel[e.Range.Top, e.Range.Right];
                    this.gridModel.ActiveGridView.ScrollCellInView(e.Range.Top, e.Range.Right);
                    this.GetFormattedOrActiveTextAt(e.Range.Top, e.Range.Right, style);
                }

                int row, col;
                if (e.Range.GetFirstCell(out row, out col))
                {
                    RefreshCells(row, col);
                    while (e.Range.GetNextCell(ref row, ref col, false))
                    {
                        RefreshCells(row, col);
                    }
                }
            }
        }

        /// <summary>
        /// Triggers the parsing and computing of formulas.
        /// </summary>
        /// <remarks>
        /// Overridden to trigger the parsing and computing of formulas. The 
        /// computed value is returned for non-editing cells. The raw formula
        /// text is returned when the cell is actively being edited.
        /// </remarks>
        /// <param name="style">The <see cref="GridStyleInfo"/> object that holds cell information.</param>
        /// <param name="value">The value to format.</param>
        /// <param name="textInfo">textInfo is a hint who is calling, default is GridCellBaseTextInfo.DisplayText.</param>
        /// <returns>Either the computed value or the raw formula text.</returns>
        public override string GetFormattedText(GridStyleInfo style, object value, int textInfo)
        {
            string s = style.Text;
            Engine.GetFormulaText(ref s);

            if (this.copyFormulasToClipboard)
            {
                return s;
            }

            bool usesFormulaChar = this.formulaChar != (char)0 && s.Length > 0 && s[0] == this.formulaChar;
            if (this.formulaChar == (char)0 || usesFormulaChar)
            {
                if (usesFormulaChar)
                {
                    s = s.Substring(1); ////strip it off
                }

                if (GridUtil.IsEmpty(s.Trim()))
                {
                    return string.Empty;
                }

                GridStyleInfoIdentity id = style.Identity as GridStyleInfoIdentity;
#if DEBUG
                if (Switches.FormulaCell.TraceVerbose)
                {
                    TraceUtil.TraceCurrentMethodInfo(style.Text, style.FormulaTag, id.RowIndex, id.ColIndex, value, Grid.CurrentCellInfo, this);
                }
#else

                ;
#endif
                bool saveTag = false;
                if (style.FormulaTag == null)
                {
                    Engine.cell = GridRangeInfo.GetAlphaLabel(id.ColIndex) + id.RowIndex.ToString();
                    style.FormulaTag = new GridFormulaTag(Engine.Parse(s), null, id.RowIndex, id.ColIndex);
#if DEBUG
                    if (Switches.FormulaCell.TraceVerbose)
                    {
                        TraceUtil.TraceCurrentMethodInfo("parsing", s, style.FormulaTag, id.RowIndex, id.ColIndex, this);
                    }
#else
                    ;
#endif
                    saveTag = true;
                }

                GridFormulaTag tag = style.FormulaTag;
                if (tag != null)
                {
                    ////Check to see if parameter references need to be updated.
                    bool needAdjustment = NeedToAdjustReferences(id, tag) & !(fromClipboardCut | Engine.fromClipboardCut);
                    if (needAdjustment && (this.isPaste || Engine.inPaste) &&
                        0 != (Engine.FormulaCopyFlags & GridFormulaCopyFlags.ClipBoardReferencesAdjusted))
                    {
                        allowAdjustReferences = true;
                        AdjustReferences(id, tag, style);
                        allowAdjustReferences = false;
                        tag.Formula = Engine.Parse(style.Text);
                        saveTag = true;
                        ////this.isPaste = false;
                    }
                    else if (needAdjustment)
                    {
                        tag.ParsedRow = id.RowIndex;
                        tag.ParsedCol = id.ColIndex;
                        saveTag = true;
                        Engine.SetDirty(tag); //// tag.Text = string.Empty;
                    }
                    ////if(GridUtil.IsEmpty(tag.Text))
                    if (Engine.IsDirty(tag))
                    {
                        Engine.cell = GridRangeInfo.GetAlphaLabel(id.ColIndex) + id.RowIndex.ToString();

                        try
                        {
                            tag.Text = Engine.ComputedValue(tag.Formula);
                            if (Engine.unParsedKey.ToUpper() == style.FormulaTag.Formula)
                            {
                                tag.Text = Engine.parsedKeyValue;
                            }
                            saveTag = true;
                        }
                        catch (Exception ex)
                        {
                            ////                            TraceUtil.TraceExceptionCatched(ex);
                            ////                            if (!ExceptionManager.RaiseExceptionCatched(this, ex))
                            ////                                throw ex;
                            return ex.Message;
                        }
                    }

                    if (saveTag)
                    {
                        if (Engine.ReturnNAN)
                        {
                            if (tag.Text == "NaN")
                            {
                                tag.Text = "#Value!";
                            }
                            else if (tag.Text == "Infinity")
                            {
                                tag.Text = "#Div/0!";
                            }
                        }

                        bool b = this.Grid.IgnoreReadOnly;
                        this.Grid.IgnoreReadOnly = true;
                        this.Grid[id.RowIndex, id.ColIndex].FormulaTag = tag;
                        this.Grid.IgnoreReadOnly = b;
                    }

                    ////FIXED() func will return text and it should not be converted to value type.
                    char UNIQUESTRINGMARKER = (char)127;
                    if (tag.Text != null && tag.Text.IndexOf(UNIQUESTRINGMARKER) == 0)
                    {
                        return tag.Text.Remove(0, 1);
                    }

                    CultureInfo ci = style.GetCulture(true);

                    double d;
                    DateTime date;
                    if (tag.Text != null && double.TryParse(tag.Text, NumberStyles.Number | NumberStyles.AllowExponent, ci.NumberFormat, out d))
                    {
                        if (!GridUtil.IsEmpty(style.Format))
                        {
                            return GridCellValueConvert.FormatValue(d, typeof(double), style.Format, ci, ci.NumberFormat);
                        }

                        // The change in effect says that if there is no style.Format property and if the tag.Text is parseable as a double,
                        // then just return the value of tag.Text instead of the raw double value returned by double.ToString() which is 
                        // what the commented base class call effectively does.
                        return tag.Text;
                        //return base.GetFormattedText(style, d, textInfo);
                    }
                    else if (tag.Text != null && DateTime.TryParse(tag.Text, ci.NumberFormat, DateTimeStyles.None, out date))
                    {
                        if (!GridUtil.IsEmpty(style.Format))
                        {
                            return GridCellValueConvert.FormatValue(date, typeof(DateTime), style.Format, ci, ci.NumberFormat);
                        }

                        // The change in effect says that if there is no style.Format property and if the tag.Text is parseable as a double,
                        // then just return the value of tag.Text instead of the raw datetime value returned by DateTime.ToString() which is 
                        // what the commented base class call effectively does.
                        return tag.Text;
                    }
                    else
                    {
                        if (tag.Text == null)
                        {
                            return string.Empty;
                        }
                        if (Engine.unParsedKey.ToUpper() == style.FormulaTag.Formula)
                        {
                            tag.Text = Engine.parsedKeyValue;
                        }

                        return tag.Text;
                    }
                }
                else
                {
                    return string.Empty;
                }
            }
            else
            {
                ////do not have a formula in the cell

                ////check for possible format and try to apply it
                if (!GridUtil.IsEmpty(style.Format))
                {
                    CultureInfo ci = style.GetCulture(true);

                    decimal dec;
                    double d;
                    DateTime date;

                    if (style.CellValueType == typeof(DateTime) && DateTime.TryParse(style.Text, ci.NumberFormat, DateTimeStyles.None, out date))
                    {
                        return GridCellValueConvert.FormatValue(date, typeof(DateTime), style.Format, ci, ci.NumberFormat);
                    }
                    if (decimal.TryParse(style.Text, NumberStyles.Number | NumberStyles.AllowExponent, ci.NumberFormat, out dec))
                    {
                        return GridCellValueConvert.FormatValue(dec, typeof(decimal), style.Format, ci, ci.NumberFormat);
                    }
                    else if (double.TryParse(style.Text, NumberStyles.Number | NumberStyles.AllowExponent, ci.NumberFormat, out d))
                    {
                        return GridCellValueConvert.FormatValue(d, typeof(double), style.Format, ci, ci.NumberFormat);
                    }
                }
                ////    TraceUtil.TraceCurrentMethodInfoIf(Switches.FormulaCell.TraceVerbose, "not a formula cell", style.Text, value, base.GetFormattedText(style, value, textInfo));
                return base.GetFormattedText(style, value, textInfo);
            }
        }

        internal bool allowAdjustReferences = false;
        private void AdjustReferences(GridStyleInfoIdentity id, GridFormulaTag tag, GridStyleInfo style)
        {
            if (allowAdjustReferences)
            {
                string sheetName = string.Empty;
                if (Engine.IsSheeted)
                {
                    GridSheetFamilyItem family = GridFormulaEngine.GetSheetFamilyItem(this.gridModel);
                    string token = family.GridModelToToken[this.gridModel] as string;
                    sheetName = family.TokenToSheetName[token] as string;
                }

                style.Text = this.Engine.AdjustReferences(style.Text, id.RowIndex - tag.ParsedRow, id.ColIndex - tag.ParsedCol, lastCopiedSheetName, sheetName);
            }

            tag.ParsedRow = id.RowIndex;
            tag.ParsedCol = id.ColIndex;

            this.Grid.SuspendChangeEvents();
            bool b = this.Grid.IgnoreReadOnly;
            this.Grid.IgnoreReadOnly = true;
            this.Grid[id.RowIndex, id.ColIndex].Text = style.Text;
            Engine.SetDirty(tag); ////tag.Text = string.Empty;
            this.Grid[id.RowIndex, id.ColIndex].FormulaTag = tag;
            this.Grid.IgnoreReadOnly = b;
            this.Grid.ResumeChangeEvents();
        }

        private bool NeedToAdjustReferences(GridStyleInfoIdentity id, GridFormulaTag tag)
        {
            return (id.RowIndex != tag.ParsedRow && tag.ParsedRow != -1)
                || (id.ColIndex != tag.ParsedCol && tag.ParsedCol != -1);
        }

        /// <summary>
        /// Overridden to return a GridFormulaCellRenderer class.
        /// </summary>
        /// <param name="control">The grid control.</param>
        /// <returns>returns a GridFormulaCellRenderer object.</returns>
        public override GridCellRendererBase CreateRenderer(GridControlBase control)
        {
            return new GridFormulaCellRenderer(control, this);
        }
    }
    #endregion

    #region CellRenderer Class
    /// <summary>
    /// Implements a GridCellRender that supports formulas.
    /// </summary>
    /// <remarks>
    /// See <see cref="GridFormulaCellModel"/> for a discussion about formula engine
    /// and customization.
    /// <para/>
    /// The following table lists some characteristics about the FormulaCell cell type:
    /// <para/>
    /// <list type="table">
    ///     <listheader>
    ///         <term>Item</term>
    ///         <description>Description</description>
    ///     </listheader>
    ///     <item>
    ///         <term>CellType</term>
    ///         <description>FormulaCell</description>
    ///     </item>
    ///     <item>
    ///         <term>Renderer</term>
    ///         <description><see cref="GridFormulaCellRenderer"/></description>
    ///     </item>
    ///     <item>
    ///         <term>Model</term>
    ///         <description><see cref="GridFormulaCellModel"/></description>
    ///     </item>
    ///     <item>
    ///         <term>XP Themes Support</term>
    ///         <description>NA</description>
    ///     </item>
    ///     <item>
    ///         <term>Interactive</term>
    ///         <description>Edit with Text and Formula Input</description>
    ///     </item>
    ///     <item>
    ///         <term>Control</term>
    ///         <description><see cref="GridTextBoxControl"/></description>
    ///     </item>
    ///     <item>
    ///         <term>Floating Support</term>
    ///         <description>Both</description>
    ///     </item>
    ///     <item>
    ///         <term>Base Type</term>
    ///         <description><see cref="GridTextBoxCellRenderer"/></description>
    ///     </item>
    /// </list>
    /// <para/>
    /// <para/>
    /// The cell's behavior and appearance can be customized with the following properties of the <see cref="GridStyleInfo"/> class:
    /// <para/>
    /// <list type="table">
    ///     <listheader>
    ///         <term>PropertyName</term>
    ///         <description>Description</description>
    ///     </listheader>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.AllowEnter"/> (<see cref="System.Boolean"/>)</term>
    ///         <description>Gets / sets if pressing the &lt;Enter&gt;-Key should insert a new line into the edited text. (Default: False)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.AutoSize"/> (<see cref="System.Boolean"/>)</term>
    ///         <description>Gets / sets if the cell height should automatically increase when the edited text does not fit into the cell and <see cref="GridStyleInfo.WrapText"/> is True. If <see cref="GridStyleInfo.WrapText"/> is False, <see cref="GridStyleInfo.AutoSize"/> will affect the column width. (Default: False)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.BaseStyle"/> (<see cref="System.String"/>)</term>
    ///         <description>The base style for this style instance with default values for properties that are not initialized for this style object. (Default: String.Empty)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.Borders"/> (<see cref="GridBordersInfo"/>)</term>
    ///         <description>Top, left, bottom, and right border settings. (Default: GridBordersInfo.Default)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.CellAppearance"/> (<see cref="GridCellAppearance"/>)</term>
    ///         <description>Specifies if cell edges shall be drawn raised, sunken, or flat (default). (Default: GridCellAppearance.Flat)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.CellTipText"/> (<see cref="System.String"/>)</term>
    ///         <description>ToolTip text to be displayed when user hovers mouse over cell. (Default: String.Empty)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.CellType"/> (<see cref="System.String"/>)</term>
    ///         <description>FormulaCell (Default: Text Box)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.CellValue"/> (<see cref="System.Object"/>)</term>
    ///         <description>This property holds the cell value. Although the cell value is typically a string, it can also be any other primitive type such as int, byte, enum, or any custom type that is derived from <see cref="System.Object"/>. (Default: String.Empty)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.CellValueType"/> (<see cref="System.Type"/>)</term>
    ///         <description>Specifies the preferred <see cref="System.Type"/> for cell values. When you assign a value to the <see cref="GridStyleInfo"/> object, the value will be converted to this type. If the value cannot be converted, <see cref="GridStyleInfo.Error"/> will contain error information. (Default: NULL)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.CultureInfo"/> (<see cref="System.Globalization.CultureInfo"/>)</term>
    ///         <description>The culture information holds rules for parsing and formatting the cell's value. (Default: null)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.Enabled"/> (<see cref="System.Boolean"/>)</term>
    ///         <description>Specifies if the cell can be activated as current cell or if the cell should be skipped when moving the current cell. (Default: True)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.Error"/> (<see cref="System.String"/>)</term>
    ///         <description>Holds error information if a value could not be converted to the <see cref="System.Type"/> specified with <see cref="GridStyleInfo.CellValueType"/>. (Default: String.Empty)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.FloatCell"/> (<see cref="System.Boolean"/>)</term>
    ///         <description>Gets / sets if text can float into the boundaries of a neighboring cell. (Default: True)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.FloodCell"/> (<see cref="System.Boolean"/>)</term>
    ///         <description>Gets / sets if this cell can be flooded by a previous cell. (Default: True)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.Font"/> (<see cref="GridFontInfo"/>)</term>
    ///         <description>The font for drawing text. (Default: GridFontInfo.Default)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.Format"/> (<see cref="System.String"/>)</term>
    ///         <description>Gets / sets the format mask for formatting the cell value. You can specify numeric format strings,
    /// date format strings or enumeration format strings as discussed in the section "Format Specifiers and Format Providers" of the .NET Framework Developers Guide (see ms-help://MS.VSCC/MS.MSDNVS/cpguide/html/cpconformatspecifiersformatproviders.htm) (Default: String.Empty)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.FormulaTag"/> (<see cref="GridFormulaTag"/>)</term>
    ///         <description>A formula tag that is associated with a cell. (Default: NULL)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.HorizontalAlignment"/> (<see cref="GridHorizontalAlignment"/>)</term>
    ///         <description>Specifies horizontal alignment of text in the cell. (Default: GridHorizontalAlignment.Left)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.HotkeyPrefix"/> (<see cref="System.Drawing.Text.HotkeyPrefix"/>)</term>
    ///         <description>Specifies how hot-key prefixes should be displayed. Hot-keys are indicated in text with an '&amp;' (ampersand). When you enable a hot-key prefix, the specific characters can be displayed underlined or regular. The '&amp;' will not be displayed. (Default: HotkeyPrefix.Show)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.ImageIndex"/> (<see cref="System.Int32"/>)</term>
    ///         <description>Specifies an index for an image in the <see cref="GridStyleInfo.ImageList"/> of a <see cref="GridStyleInfo"/>
    /// instance. (Default: -1)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.ImageList"/> (<see cref="System.Windows.Forms.ImageList"/>)</term>
    ///         <description>The <see cref="GridStyleInfo.ImageList"/> that holds a collection of images. Cells can choose images with the <see cref="GridStyleInfo.ImageIndex"/> property in a <see cref="GridStyleInfo"/>
    /// instance. (Default: NULL)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.Interior"/> (<see cref="Syncfusion.Drawing.BrushInfo"/>)</term>
    ///         <description> Lets you specify a solid backcolor, gradient, or pattern style with both back and forecolor for a cell's
    ///  background. (Default: SystemColors.Window)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.MaxLength"/> (<see cref="System.Int32"/>)</term>
    ///         <description>Limits the number of characters the user can type into the cell. Note: When selecting a text from a choice list or when pasting text, the text can be longer. Additional validation is necessary on your side. (Default: 0)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.MergeCell"/> (<see cref="GridMergeCellDirection"/>)</term>
    ///         <description>Specifies merge behavior for an individual cell when merging cells feature has been enabled in a <see cref="GridModel"/> with  <see cref="GridModelOptions.MergeCellsMode"/>. (Default: GridMergeCellDirection.None)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.ReadOnly"/> (<see cref="System.Boolean"/>)</term>
    ///         <description>Specifies if cell contents can be modified by the user. You can programmatically change Read-only cells by setting <see cref="GridModel.DiscardReadOnly"/> to True. (Default: False)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.Text"/> (<see cref="System.String"/>)</term>
    ///         <description>Gets / sets the value as a string. If a <see cref="GridStyleInfo.CellValueType"/>
    /// is specified, the text will be parsed and converted to the type specified with
    /// <see cref="GridStyleInfo.CellValueType"/> using any <see cref="GridStyleInfo.CultureInfo"/>
    /// information.
    ///  (Default: String.Empty)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.TextColor"/> (<see cref="System.Drawing.Color"/>)</term>
    ///         <description>Lets you specify the color for drawing the cell text. (Default: SystemColors.WindowText)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.TextMargins"/> (<see cref="GridMarginsInfo"/>)</term>
    ///         <description>Holds text margins in pixels. When drawing a cell, this specifies the empty area between the
    /// text rectangle and the client rectangle of the cell without borders and cell buttons. (Default: GridMarginsInfo.Default)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.Trimming"/> (<see cref="System.Drawing.StringTrimming"/>)</term>
    ///         <description>Indicates how text is trimmed when it exceeds the edges of the cell text rectangle. (Default: StringTrimming.Character)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.ValidateValue"/> (<see cref="GridCellValidateValueInfo"/>)</term>
    ///         <description>Holds validation rules for cell values that are being checked before any user changes are committed to the grid cell's style object. (Default: NULL)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.VerticalAlignment"/> (<see cref="GridVerticalAlignment"/>)</term>
    ///         <description>Specifies vertical alignment of text in the cell. (Default: GridVerticalAlignment.Top)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.VerticalScrollbar"/> (<see cref="System.Boolean"/>)</term>
    ///         <description>Specifies if text box should show a vertical scrollbar when text is being edited and does not fit in cell. WrapText must be initialized to True. (Default: False)</description>
    ///     </item>
    ///     <item>
    ///         <term><see cref="GridStyleInfo.WrapText"/> (<see cref="System.Boolean"/>)</term>
    ///         <description>Specifies if text should be wrapped when it does not fit into a single line. (Default: True)</description>
    ///     </item>
    /// </list>
    /// <para/>
    /// </remarks>
    public class GridFormulaCellRenderer : GridTextBoxCellRenderer
    {
        [ThreadStaticAttribute]
        private static bool forceEditWhenActivated = true;

        /// <summary>
        /// Gets or sets a value indicating whether GridFormulaCellRenderer should honor the <see cref="GridModelOptions.ActivateCurrentCellBehavior"/>
        /// and only start editing mode as specified in that setting or if it should ignore that setting and always
        /// switch into edit mode as soon as it is activated.
        /// </summary>
        public static bool ForceEditWhenActivated
        {
            get
            {
                return forceEditWhenActivated;
            }

            set
            {
                forceEditWhenActivated = value;
            }
        }

        /// <summary>
        /// Initializes a new GridFormulaCellRenderer object for the given GridControlBase
        /// and GridCellModelBase.
        /// </summary>
        /// <param name="grid">The <see cref="GridControlBase"/> that displays this cell renderer.</param>
        /// <param name="cellModel">The <see cref="GridCellModelBase"/> that holds data for this cell renderer that should
        /// be shared among views.</param>
        /// <remarks>References to GridControlBase, 
        /// and GridCellModelBase will be saved.</remarks>
        public GridFormulaCellRenderer(GridControlBase grid, GridCellModelBase cellModel)
            : base(grid, cellModel)
        {
#if DEBUG
            if (Switches.FormulaCell.TraceVerbose)
            {
                TraceUtil.TraceCurrentMethodInfo(grid, cellModel);
            }
#else
            ;
#endif
        }

        /// <override/>
        protected override void OnActivated()
        {
            base.OnActivated();
            if (!CurrentCell.IsEditing && ForceEditWhenActivated)
            {
                // Set the cell editing so that formula is displayed but do not set focus to text box.
                CurrentCell.BeginEdit(false);
            }
        }

        /// <override/>
        protected override void InitializeControlText(object controlValue)
        {
            string text = controlValue != null ? controlValue.ToString() : string.Empty;
            GridCurrentCellInitializeControlTextEventArgs e = new GridCurrentCellInitializeControlTextEventArgs(this.RowIndex, this.ColIndex, this.StyleInfo, controlValue, text);
            if (Grid.RaiseCurrentCellInitializeControlText(e))
            {
                this.ControlText = e.ControlText;
            }
        }

        /// <override/>
        /// <summary>Called when user initiates ClipboardCopy operation. Used for a single cell only. Returns True if successful; False if failed.</summary>
        /// <returns>returns False.</returns>
        public override bool Copy()
        {
            ////Only used when you are copying a single formula cell.
            ////Not used when copying ranges.
            ////If this copied value is pasted to a FormulaCell target,
            ////you get the formula. If it gets pasted to a non-formula cell,
            ////you get the text.
            return false; ////let the grid copy the cell...
        }

        /// <override/>
        /// <summary>Called when user initiates ClipboardPaste operation. True if successful; False if failed.</summary>
        /// <returns>returns False.</returns>
        public override bool Paste()
        {
            ////Only used when you are pasting a single cell.
            ////Not used when pasting ranges.
            ////If the source was a formulacell, you get the formula.
            ////If the source was not a formulacell, you get text.
            return false; ////let the grid handle it
        }

        /// <summary>
        /// This method is called from GridCurrentCell.Validate after GridCurrentCell.Validating event has been
        /// fired. The default version checks if the active text fits any criteria as specified
        /// in the style object: It can be parsed into a cell value and meets GridCellValidateValueInfo criteria.
        /// </summary>
        /// <returns>
        /// True if the modified text is valid; False otherwise.
        /// </returns>
        /// <override/>
        protected override bool OnValidate()
        {
            GridFormulaEngine engine = ((GridFormulaCellModel)this.Model).Engine;

            string s = this.Control.Text;
            engine.GetFormulaText(ref s);

            GridSheetFamilyItem family = GridFormulaEngine.GetSheetFamilyItem(this.Grid.Model);
            string sheet = (family.GridModelToToken != null)
                        ? family.GridModelToToken[this.Grid.Model] as string
                        : string.Empty;
            int row = this.Grid.CurrentCell.RowIndex;
            int col = this.Grid.CurrentCell.ColIndex;
            string cell = sheet + GridRangeInfo.GetAlphaLabel(col) + row.ToString();

            if ((s.Length == 0) ||
                (engine.formulaChar != (char)0 && s.Length > 0 && s[0] != engine.formulaChar))
            {
                ////Remove any cell dependencies....
                Hashtable ht = (Hashtable)engine.DependentFormulaCells[cell];
                if (ht != null)
                {
                    foreach (string s1 in ht.Keys)
                    {
                        Hashtable ht1 = (Hashtable)engine.DependentCells[s1];
                        if (ht1 != null)
                        {
                            ht1.Remove(cell);
                            if (ht1.Count == 0)
                            {
                                engine.DependentCells.Remove(s1);
                            }
                        }
                    }

                    engine.DependentFormulaCells.Remove(cell);
                }

                if (this.Grid.Model[row, col].FormulaTag != null)
                {
                    ////also remove formulaTag
                    this.Grid.Model[row, col].FormulaTag = null;
                }

                return true;
            }
            else if (engine.formulaChar != (char)0 && s.Length > 0)
            {
                s = s.Substring(1);
            }

            bool save = engine.lockDependencies;
            try
            {
                ////Parse it to see if OK...
                engine.cell = cell;
                string parsedFormula;

                if (engine.DoCircularCheckInValidating)
                {
                    engine.lockDependencies = true;
                    parsedFormula = engine.Parse(s);
                    if (CircularCheckFailed(cell, parsedFormula))
                    {
                        this.Grid.CurrentCell.ErrorMessage = engine.FormulaErrorStrings[engine.circular_reference_] + cell;
                        engine.lockDependencies = save;
                        return false;
                    }

                    engine.lockDependencies = save;
                }

                parsedFormula = engine.Parse(s);
                ////remove old cell dependencies so new ones can be set up
                if (engine.DependentFormulaCells.ContainsKey(cell))
                {
                    Hashtable ht = (Hashtable)engine.DependentFormulaCells[engine.cell];
                    foreach (object key in ht.Keys)
                    {
                        Hashtable ht1 = (Hashtable)engine.DependentCells[(string)key];
                        ht1.Remove(engine.cell);
                        if (ht1.Count == 0)
                        {
                            engine.DependentCells.Remove(key);
                        }
                    }

                    engine.DependentFormulaCells.Remove(engine.cell);
                }

                string computeFormula = engine.ComputedValue(parsedFormula);

                ////Check for circular reference.
                if (engine.IsCircularReference(cell))
                {
                    Hashtable ht = (Hashtable)engine.DependentCells[cell];
                    //// && ht.ContainsKey(cell)) 
                    if (ht != null)
                    {
                        ht.Remove(cell);
                        engine.ClearFormulaDependentCells(engine.cell);
                        throw new ArgumentException(engine.FormulaErrorStrings[engine.circular_reference_] + cell);
                    }
                }
                ////Save the parsed formula to avoid parsing it a second time in GetFormattedText.
                if (engine.ReturnNAN)
                {
                    if (computeFormula == "NaN")
                    {
                        computeFormula = "#Value!";
                    }
                    else if (computeFormula == "Infinity")
                    {
                        computeFormula = "#Div/0!";
                    }
                }

                bool b = this.Grid.Model.IgnoreReadOnly;
                this.Grid.Model.IgnoreReadOnly = true;
                this.Grid.Model[row, col].FormulaTag = new GridFormulaTag(parsedFormula, computeFormula, row, col);
                this.Grid.Model.IgnoreReadOnly = b;
            }
            catch (ArgumentException ex)
            {
                this.Grid.CurrentCell.ErrorMessage = ex.Message;
                return false;
            }
            finally
            {
                if (save != engine.lockDependencies)
                {
                    engine.lockDependencies = save;
                }
            }

            return true;
        }

        internal bool CircularCheckFailed(string hostCell, string parsedFormula)
        {
            GridFormulaEngine engine = ((GridFormulaCellModel)this.Model).Engine;
            return engine.CircularCheckFailed(hostCell, parsedFormula);
        }
    }
    #endregion

    #region GridFormulaEngine Class

    /// <summary>
    /// Encapsulates the code required to parse and compute formulas. Hashtable
    /// properties maintain a Formula Library of functions as well as a list
    /// of dependent cells.
    /// <para/>
    /// You can add and remove library functions.
    /// </summary>
    public class GridFormulaEngine
    {
        ////the grid
        private GridModel grid;

        public const double machineepsilon = 5E-16;
        public const double maxrealnumber = 1E300;
        public const double minrealnumber = 1E-300;
        public double ACC = 4.0;
        public double BIGNO = 1.0e10;
        public double BIGNI = 1.0e-10;

        private static void besselmfirstcheb(double c,
   ref double b0,
   ref double b1,
   ref double b2)
        {
            b0 = c;
            b1 = 0.0;
            b2 = 0.0;
        }

        private static void besselmnextcheb(double x,
           double c,
           ref double b0,
           ref double b1,
           ref double b2)
        {
            b2 = b1;
            b1 = b0;
            b0 = x * b1 - b2 + c;
        }

        private static void besselm1firstcheb(double c,
           ref double b0,
           ref double b1,
           ref double b2)
        {
            b0 = c;
            b1 = 0.0;
            b2 = 0.0;
        }

        private static void besselm1nextcheb(double x,
           double c,
           ref double b0,
           ref double b1,
           ref double b2)
        {
            b2 = b1;
            b1 = b0;
            b0 = x * b1 - b2 + c;
        }


        /// <summary>
