        /// <summary>
        /// Recalculates any formula cells in the specified range.
        /// </summary>
        /// <param name="range">GridRangeInfo object that specifies the cells to be recalculated.</param>
        /// <param name="forceCalculations">Determines whether the calculations on non-visible
        /// cells are performed immediately or delayed until the next time the cell is drawn.
        /// For visible cells, the calculations are done immediately.</param>
        /// <param name="forceParsing">When forceParsing is False, a formula is only 
        /// re-parsed if FormulaTag is NULL, or FormulaTag.Formula is empty. Otherwise, the existing
        /// parsed formula in FormulaTag.Formula is used to perform the calculation. The value
        /// of forceParsing only affects the Engine if forceCalculations is True.</param>
        /// <remarks> This method does not do anything if <see cref="CalculatingSuspended"/> is true.
        /// </remarks>
        public void RecalculateRange(GridRangeInfo range, bool forceCalculations, bool forceParsing)
        {
            RecalculateRange(range, this.grid, forceCalculations, forceParsing);
        }

        /// <summary>
        /// Recalculates any formula cells in the specified range.
        /// </summary>
        /// <param name="range">GridRangInfo object that specifies the cells to be recalculated.</param>
        /// <param name="grd">The GridModel object where the range to be updated is located.</param>
        /// <param name="forceCalculations">Determines whether the calculations on non-visible
        /// cells are performed immediately or delayed until the next time the cell is drawn.
        /// For visible cells, the calculations are done immediately.</param>
        /// <param name="forceParsing">When forceParsing is False, a formula is only 
        /// re-parsed if FormulaTag is NULL, or FormulaTag.Formula is empty. Otherwise, the existing
        /// parsed formula in FormulaTag.Formula is used to perform the calculation. The value
        /// of forceParsing only affects the Engine if forceCalculations is True.</param>
        /// <remarks> This method does not do anything if <see cref="CalculatingSuspended"/> is True.
        /// </remarks>
        public void RecalculateRange(GridRangeInfo range, GridModel grd, bool forceCalculations, bool forceParsing)
        {
            RecalculateRange(range, grd, forceCalculations, forceParsing, true);
        }

        internal void RecalculateRange(GridRangeInfo range, GridModel grd, bool forceCalculations, bool forceParsing, bool useBeginUpdate)
        {
#if DEBUG
            if (Switches.FormulaCell.TraceVerbose)
            {
                TraceUtil.TraceCurrentMethodInfo(range, forceCalculations, forceParsing, this);
            }
#else
            ;
#endif
            if (CalculatingSuspended)
            {
                ////Don't refresh any cells.
                return;
            }

            GridModel saveGrid = this.grid;
            this.grid = grd;

            bool b = this.grid.IgnoreReadOnly;
            this.grid.IgnoreReadOnly = true;
            range = range.ExpandRange(1, 1, this.grid.RowCount, this.grid.ColCount);

            if (useBeginUpdate)
            {
                this.grid.BeginUpdate();
            }

            GridData data = this.grid.Model.Data;

            if (!isCellsprocessed)
            {
                for (int r = range.Top; r <= range.Bottom; r++)
                {
                    for (int c = range.Left; c <= range.Right; c++)
                    {
                        
                        if (data[r, c] == null && !UsesVirtualDataSource)
                        {
                            continue;
                        }

                        string cellAddress = GridRangeInfo.GetAlphaLabel(c) + r.ToString();

                        GridStyleInfo style = UsesVirtualDataSource
                            ? this.grid[r, c]
                            : new GridStyleInfo(new GridStyleInfoIdentity(this.grid.Model.VolatileData, r, c, true), data[r, c]);

                        if (style.Store != null && style.CellModel is GridFormulaCellModel)
                        {
                            string s = style.Text;
                            GetFormulaText(ref s);

                            bool usesFormulaChar = this.formulaChar != (char)0 && s.Length > 0 && s[0] == this.formulaChar;
                            if (this.formulaChar == (char)0 || usesFormulaChar)
                            {
                                if (usesFormulaChar)
                                {
                                    s = s.Substring(1); ////strip it off
                                }

                                ////Only force a parse if Formula not in Tag.
                                string formula = (style.FormulaTag != null && !forceParsing) ? style.FormulaTag.Formula : string.Empty;

                                style.FormulaTag = null;

                                if (forceCalculations)
                                {
                                    this.cell = GridRangeInfo.GetAlphaLabel(c) + r.ToString();

                                    if (formula.Length == 0 && s.Length > 0)
                                    {
                                        if (catchExceptionsInRecalculateRange)
                                        {
                                            try
                                            {
                                                formula = this.Parse(s);
                                            }
                                            catch (Exception)
                                            {
                                                formula = "#REF!";
                                            }
                                        }
                                        else
                                        {
                                            formula = this.Parse(s);
                                        }
                                    }

                                    string text = "";
                                    if (catchExceptionsInRecalculateRange)
                                    {
                                        if (formula == "#REF!")
                                        {
                                            text = "#REF!";
                                        }
                                        else
                                        {
                                            if (formula.Length > 0)
                                            {
                                                bool save = ExceptionManager.PassThroughExceptions;
                                                ExceptionManager.PassThroughExceptions = true;
                                                try
                                                {
                                                    text = this.ComputedValue(formula);
                                                }
                                                catch (Exception)
                                                {
                                                    text = "#REF!";
                                                }
                                                finally
                                                {
                                                    ExceptionManager.PassThroughExceptions = save;
                                                }
                                            }
                                        }
                                    }
                                    else
                                    {
                                        text = this.ComputedValue(formula);
                                    }
                                    style.FormulaTag = new GridFormulaTag(formula, text, r, c);
                                }

                                if (!UsesVirtualDataSource)
                                {
                                    data[r, c] = (GridStyleInfoStore)style.Store;
                                }
                            }
                        }
                        if (r == range.Bottom && c == range.Right && this.SuspendRefresh)
                            isCellsprocessed = true;
                    }
                }
            }

            this.grid.IgnoreReadOnly = b;

            if (useBeginUpdate)
            {
                this.grid.EndUpdate();
            }

            ////Now draw the range so formulas are recomputed.
            this.grid.InvalidateRange(range, GridRangeOptions.None);
            this.grid = saveGrid;
        }

        /// <summary>
        /// updates the value to perform calcuation for range of cells in RecalculateRange function
        /// </summary>
        /// <param name="sender">grid model</param>
        /// <param name="e">GridCellsChanged EventArgs</param>
        void grid_CellsChanged(object sender, GridCellsChangedEventArgs e)
        {
            isCellsprocessed = false;
        }

        private bool catchExceptionsInRecalculateRange = false;

        /// <summary>
        /// Gets or sets whether further calculations on a formula will be attempted in the RecalculateRange method if there is an exception 
        /// raised during the parsing or calculating of the formula.
        /// </summary>
        /// <remarks>
        /// The default value is false for backward compatibilty purposes. If you set this property to true, then during calls to RecalculateRange with
        /// forceCalculations = true, if an exception is raised during parsing or computing, the cell will display "#REF!". This property only has 
        /// effect if you call RecalculateRange with the forceCalculations parameter set to true.
        /// </remarks>
        public bool CatchExceptionsInRecalculateRange
        {
            get { return catchExceptionsInRecalculateRange; }
            set { catchExceptionsInRecalculateRange = value; }
        }
