        /// <summary>
        /// Rounds a number to a specified number of digits.
        /// </summary>
        /// <param name="argList">Number and number of digits.</param>
        /// <returns>Rounded number.</returns>
        public string ComputeRound(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount == 1)
            {
                return ComputeMath(argList, new MathFunc(Math.Round)).ToString();
            }

            if (argCount != 2)
            {
                return FormulaErrorStrings[this.invalid_arguments];
            }

            double x = 0;
            double digits = 0;
            double round = 0;
            string numStr = GetValueFromArg(args[0]);
            string digStr = GetValueFromArg(args[1]);

            if ((numStr.Length == 0 || double.TryParse(numStr, out x))
            && (digStr.Length == 0 || double.TryParse(digStr, out digits)))
            {
                if (digits > 0)
                {
                    round = Math.Round(x, (int)digits, MidpointRounding.AwayFromZero);
                }
                else
                {
                    double mult = Math.Pow(10, -digits);
                    round = Math.Round(x / mult) * mult;
                }
            }
            else
            {
                return FormulaErrorStrings[invalid_arguments];
            }

            return round.ToString();
        }

        /// <summary>
        /// Rounds a number to a specified number of digits.
        /// </summary>
        /// <param name="argList">Number and number of digits.</param>
        /// <returns>Rounded number.</returns>
        public string ComputeRounddown(string argList)
        {
            double x = 0;

            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount == 1)
            {
                double.TryParse(GetValueFromArg(argList), out x);
                x = x - .5 * Math.Sign(x);
                return ComputeRound(string.Format("{0}", x));
            }
            else if (argCount != 2)
            {
                return FormulaErrorStrings[this.invalid_arguments];
            }

            double digits = 0;
            double.TryParse(GetValueFromArg(args[0]), out x);
            double.TryParse(GetValueFromArg(args[1]), out digits);
            x = x - .5 * Math.Pow(10, -digits) * Math.Sign(x);
            return ComputeRound(string.Format("{0}{1}{2}", x, ParseArgumentSeparator, digits));
        }

        /// <summary>
        /// Rounds a number to a specified number of digits.
        /// </summary>
        /// <param name="argList">Number and number of digits.</param>
        /// <returns>Rounded number.</returns>
        public string ComputeRoundup(string argList)
        {
            double x = 0;

            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount == 1)
            {
                 double.TryParse(GetValueFromArg(argList), out x);
                if (x > 0)
                {
                    x += .4999999999d;
                }
                else if (x < 0)
                {
                    x -= .4999999999d;
                }

                x = Math.Round(x, 0, MidpointRounding.AwayFromZero);
                return string.Format("{0}", x);
            }
            else if (argCount != 2)
            {
                return FormulaErrorStrings[this.invalid_arguments];
            }

            double digits = 0;
             double.TryParse(GetValueFromArg(args[0]), out x);
            double.TryParse(GetValueFromArg(args[1]), out digits);
            if (digits >= 0)
            {
                if (x > 0)
                {
                    x += .4999999999d / Math.Pow(10, digits);
                }
                else if (x < 0)
                {
                    x -= .4999999999d / Math.Pow(10, digits);
                }

                x = Math.Round(x, (int)digits, MidpointRounding.AwayFromZero);
            }
            else
            {
                if (x > 0)
                {
                    x = (x / Math.Pow(10, -digits)) + .49999;
                }
                else if (x < 0)
                {
                    x = (x / Math.Pow(10, -digits)) - .49999;
                }

                x = Math.Round(x, 0, MidpointRounding.AwayFromZero) * Math.Pow(10, -digits);
            }

            return string.Format("{0}", x);
        }

