        /// <summary>
        /// Specifies if 1900 should be treated as Leap Year (Excel Compatibility)
        /// </summary>
        public static bool Treat1900AsLeapYear = true;

        private DateTime dateTime1900 = new DateTime(1900, 1, 1, 0, 0, 0);

        /// <summary>
        /// Returns the number of days since 01 Jan 1900.
        /// </summary>
        /// <param name="argList">Year, month, and day.</param>
        /// <returns>Number of days.</returns>
        public string ComputeDate(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
                return FormulaErrorStrings[this.wrong_number_arguments];
            }

            double year;
            double month;
            double day;
            int days = 0;
            for (int i = 0; i < argCount; ++i)
            {
                args[i] = GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], out year) && !double.IsInfinity(year)
                && double.TryParse(args[1], out month) && !double.IsInfinity(month)
                && double.TryParse(args[2], out day) && !double.IsInfinity(day))
            {
                if (year < 0)
                {
                    return "#NUM";
                }

                DateTime dt = new DateTime((int)year, 1, 1);
                dt = dt.AddMonths((int)month - 1).AddDays((int)day - 1);
                days = GetSerialDateFromDate(dt.Year, dt.Month, dt.Day);
            }
            else
            {
                return "#VALUE!";
            }

            DateTime date = DateTime.FromOADate(days);
            return date.ToString();
        }

        /// <summary>
        /// Returns the serial day number for the given date.
        /// </summary>
        /// <param name="y">The year of the date.</param>
        /// <param name="m">The month of the date.</param>
        /// <param name="d">The day of the date.</param>
        /// <returns>The serial day number.</returns>
        /// <remarks>The serial day number is the number of days since January 1, 1900 with the serial
        /// day number of January 1, 1900 being counted as 1. The serial day number is how Excel stores dates.
        /// It is useful for including dates in calculations.
        /// </remarks>
        public int GetSerialDateFromDate(int y, int m, int d)
        {
            int days = 0;
            if (y < 1900)
            {
                y += 1900;
            }

            days = 1 + ((TimeSpan)(new DateTime(y, m, d, 0, 0, 0) - dateTime1900)).Days;
            if (Treat1900AsLeapYear && days > 59)
            {
                days += 1;
            }

            return days;
        }

        /// <summary>
        /// Gets the date associated with a serial day number.
        /// </summary>
        /// <param name="serialDayNumber">The serial day number.</param>
        /// <returns>The date value.</returns>
        /// <remarks>The serial day number is the number of days since January 1, 1900 with the serial
        /// day number of January 1, 1900 being counted as 1. The serial day number is how Excel stores dates.
        /// It is useful for including dates in calculations.
        /// </remarks>
        public DateTime GetDateFromSerialDate(int serialDayNumber)
        {
            serialDayNumber -= 1;
            if (Treat1900AsLeapYear && serialDayNumber > 59)
            {
                serialDayNumber -= 1;
            }

            return dateTime1900.AddDays(serialDayNumber);
        }

        /// <summary>
        /// Returns the number of days since 01 Jan 1900.
        /// </summary>
        /// <param name="argList">Text containing a date.</param>
        /// <returns>Number of days.</returns>
        public string ComputeDatevalue(string argList)
        {
            argList = GetValueFromArg(argList);
            DateTime dt;
            try
            {
                dt = DateTime.Parse(argList.Replace(TIC, string.Empty));
            }
            catch
            {
                return FormulaErrorStrings[this.invalid_arguments];
            }

            int days = 1 + ((TimeSpan)(dt - dateTime1900)).Days;
            if (Treat1900AsLeapYear && days > 59)
            {
                days += 1;
            }

            return days.ToString();
        }

