        /// <summary>
        /// Converts a number to text using currency format.
        /// </summary>
        /// <param name="args">Number and the number of digits.</param>
        /// <returns>Currency format string.</returns>
        public string ComputeDollarDe(string args)
        {
            string fraction = string.Empty;
            NumberFormatInfo nfi = (NumberFormatInfo)CultureInfo.CurrentCulture.NumberFormat.Clone();
            try
            {
                string[] argsArray = args.Split(new char[] { ParseArgumentSeparator });
                string s1 = argsArray[0];
                string s2 = "2";
                if (argsArray.GetLength(0) == 2)
                {
                    s2 = argsArray[1];
                }

                s1 = this.GetValueFromArg(s1);
                s2 = this.GetValueFromArg(s2);
                string[] splitArg = s1.Split(ParseDecimalSeparator);
                double number, decimals;
                int argCount = s1.Length;
                if (argCount == 0)
                {
                    return FormulaErrorStrings[wrong_number_arguments];

                }
                if (!IsCellReference(s1) && s1.Contains(this.TIC))
                    s1 = s1.Replace(this.TIC, string.Empty);
                if (!IsCellReference(s2) && s2.Contains(this.TIC))
                    s2 = s2.Replace(this.TIC, string.Empty);
                double.TryParse(splitArg[0], NumberStyles.Any, null, out number);
                if (!double.TryParse(s2, NumberStyles.Any, null, out decimals))
                {
                    return this.ErrorStrings[1].ToString();

                }
                if (decimals < 1)
                {
                    return this.ErrorStrings[4].ToString();

                }
                else if (decimals > 0)
                {
                    string[] deci = SplitArguments(s1, ParseDecimalSeparator);
                    double decimalNumber = (deci.Length == 2) ? (double.Parse("0." + deci[1])) * 100 : 0;
                    string[] deci1 = SplitArguments((decimalNumber / decimals).ToString(), ParseDecimalSeparator);
                    fraction = int.Parse(deci[0]).ToString() + ParseDecimalSeparator.ToString() + ((deci1.Length == 2) ? deci1[1] : deci1[0]);// double.Parse((decimalNumber / decimals).ToString());
                }
                else
                {
                    return this.ErrorStrings[3].ToString();
                }
                if (double.Parse(fraction) > 0)
                {
                    string[] digitArg = fraction.ToString().Split(ParseDecimalSeparator);
                    if (digitArg.Length > 1 && digitArg[1].Length > 0)
                    {
                        int DecimalDigits = digitArg[1].Length;
                        nfi.CurrencyDecimalDigits = DecimalDigits;
                    }
                }
                else
                {
                    return this.ErrorStrings[4].ToString();
                }
            }
            catch (Exception ex)
            {

                return ex.Message;
            }
            return string.Format(nfi, "{0}", fraction);

        }

        /// <summary>
        /// Converts a number to text using currency format.
        /// </summary>
        /// <param name="args">Number and the number of digits.</param>
        /// <returns>Currency format string.</returns>
        public string ComputeDollarFr(string args)
        {
            double fraction = 0;
            NumberFormatInfo nfi = (NumberFormatInfo)CultureInfo.CurrentCulture.NumberFormat.Clone();
            try
            {


                string[] argsArray = args.Split(new char[] { ParseArgumentSeparator });
                string s1 = argsArray[0];
                string s2 = "2";
                if (argsArray.GetLength(0) == 2)
                {
                    s2 = argsArray[1];
                }
                if (argsArray.GetLength(0) >= 1 && string.IsNullOrEmpty(s1))
                {

                    return FormulaErrorStrings[wrong_number_arguments];

                }
                s1 = this.GetValueFromArg(s1);
                s2 = this.GetValueFromArg(s2);
                string[] splitArg = s1.Split(ParseDecimalSeparator);
                double number, dollar;
                double.TryParse(s1, NumberStyles.Any, null, out number);
                double.TryParse(s2, NumberStyles.Any, null, out dollar);
                if (double.IsNaN(number) || double.IsNaN(dollar))
                {

                    return this.ErrorStrings[1].ToString();


                }
                else if (dollar <= 0)
                {

                    return this.ErrorStrings[3].ToString();


                }
                // Return error if fraction is negative
                if (number < 0)
                {

                    return this.ErrorStrings[4].ToString();

                }

                // Return error if fraction is greater than or equal to 0 and less than 1
                if (number >= 0 && number < 1)
                {

                    return this.ErrorStrings[3].ToString();

                }
                fraction = (int)number;
                fraction += (number % 1) * Math.Pow(10, -Math.Ceiling(Math.Log(dollar) / Math.Log(10))) * dollar;

                string[] digitArg = fraction.ToString().Split(ParseDecimalSeparator);
                if (digitArg.Length > 1 && digitArg[1].Length > 0)
                {
                    int DecimalDigits = digitArg[1].Length;
                    nfi.CurrencyDecimalDigits = DecimalDigits;
                }

            }
            catch (Exception ex)
            {

                return ex.Message;

            }

            return string.Format(nfi, "{0}", fraction);

        }

        /// <summary>
        ///  Returns the weighted average of the present value of the cash flows
        /// </summary>
        /// <param name="args">Number and the number of digits</param>
        /// <returns>Number of years</returns>
        public string ComputeDuration(string args)
        {
            string year = string.Empty;
            try
            {

                string[] argsArray = args.Split(new char[] { ParseArgumentSeparator });
                string days = ComputeDays360(argsArray[0] + "," + argsArray[1]);
                double month = double.Parse(days) / 12;
                double n = month / 60;
                double i = double.Parse(GetValueFromArg(argsArray[3])),
                    m = 100,
                    c = double.Parse(GetValueFromArg(argsArray[2])) * 100;
                int inc = 1;
                double bondPrice = 0;
                double p = 0;
                double mD = 0;
                while (inc <= n)
                {
                    bondPrice += (Math.Pow(c, inc) / Math.Pow((1 + i), inc));
                    inc++;
                }
                n = month / 30;
                mD = (bondPrice + ((c * 100) / (Math.Pow((1 + i), n))));
                double val = (mD / (c * ((1 - (1 / (Math.Pow((1 + i), n))) / i) + (m / (Math.Pow((1 + i), n))))) + (c / 100));
                year = ((val / 2) + (c / 10)).ToString();
           }
            catch (Exception ex)
            {
                    throw ex;
            }
            return year;
        }
        /// <summary>
        /// Calculates the equivalent interest rate for the growth of an investment.
        /// </summary>
        /// <param name="args">Investment periods, present and future value of the investments.</param>
        /// <returns>Returns the equivalent interest.</returns>
        public string ComputeRRI(string args)
        {


            string[] argsArray = args.Split(new char[] { ParseArgumentSeparator });
            if (argsArray.Length != 3)
            {

                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            string s1 = this.GetValueFromArg(argsArray[0]);
            string s2 = this.GetValueFromArg(argsArray[1]);
            string s3 = this.GetValueFromArg(argsArray[2]);

            double periods;
            double present;
            double future;
            if (!double.TryParse(s1, out periods) || !double.TryParse(s2, out present) || !double.TryParse(s3, out future))
            {

                return ErrorStrings[1].ToString();
            }
            if (periods == 0 || present == 0)
            {

                return ErrorStrings[4].ToString();
            }

            double result = Math.Pow(future / present, 1 / periods) - 1;

            return result.ToString();
        }

        /// <summary>
        ///  Returns the discount rate for a security.
        /// </summary>
        /// <param name="args">Number and the number of digits</param>
        /// <returns>Rate of Discount</returns>
        public string ComputeDisc(string args)
        {
            string discount = string.Empty;
            try
            {

                string[] argsArray = args.Split(new char[] { ParseArgumentSeparator });
                string Settlementdate = argsArray[0];
                string Maturitydate = argsArray[1];
                string Price = argsArray[2];
                string Redemptionvalue = argsArray[3];
                string Basis = string.Empty;
                if (argsArray.Length > 4)
                    Basis = argsArray[4];
                else
                    Basis = "0";
                Settlementdate = this.GetValueFromArg(Settlementdate);
                Maturitydate = this.GetValueFromArg(Maturitydate);
                Price = this.GetValueFromArg(Price);
                Redemptionvalue = this.GetValueFromArg(Redemptionvalue);
                Basis = this.GetValueFromArg(Basis);
                DateTime date1, date2 = DateTime.Now;
                double settlement = 0;
                double maturity = 0;
                if (DateTime.TryParse(Settlementdate, out date1)
               && (DateTime.TryParse(Maturitydate, out date2)))
                {
                    if (settlement == 0)
                        settlement = date1.ToOADate();
                    if (maturity == 0)
                        maturity = date2.ToOADate();

                    double DSM = double.Parse(ComputeDays360(settlement + "," + maturity));
                    double disc = (((double.Parse(Redemptionvalue) - double.Parse(Price)) / double.Parse(Redemptionvalue)) * (int.Parse(Basis) / DSM));
                    discount = disc.ToString();
                }

            }
            catch (Exception ex)
            {
                    throw ex;
            }

            return discount;

        }

        /// <summary>
        ///  Returns the interest rate for a fully invested security.
        /// </summary>
        /// <param name="args">Number and the number of digits</param>
        /// <returns>Rate of interest</returns>
        public string ComputeINTRATE(string args)
        {
            string intrate = string.Empty;
            try
            {

                string[] argsArray = args.Split(new char[] { ParseArgumentSeparator });
                string Settlementdate = argsArray[0];
                string Maturitydate = argsArray[1];
                string Investment = argsArray[2];
                string Redemptionvalue = argsArray[3];
                string Basis = string.Empty;
                if (argsArray.Length > 4)
                    Basis = argsArray[4];
                else
                    Basis = "0";
                Settlementdate = this.GetValueFromArg(Settlementdate);
                Maturitydate = this.GetValueFromArg(Maturitydate);
                Investment = this.GetValueFromArg(Investment);
                Redemptionvalue = this.GetValueFromArg(Redemptionvalue);
                Basis = this.GetValueFromArg(Basis);
                DateTime date1, date2 = DateTime.Now;
                double settlement = 0;
                double maturity = 0;

                if (DateTime.TryParse(Settlementdate, out date1)
               && (DateTime.TryParse(Maturitydate, out date2)))
                {
                    if (settlement == 0)
                        settlement = date1.ToOADate();
                    if (maturity == 0)
                        maturity = date2.ToOADate();

                    double DIM = double.Parse(ComputeDays360(settlement + "," + maturity));
                    double intrrate = (((double.Parse(Redemptionvalue) - double.Parse(Investment)) / double.Parse(Investment)) * (int.Parse(Basis) / DIM));
                    intrate = intrrate.ToString();


                }
                else
                    return this.ErrorStrings[1].ToString();
            }
            catch (Exception ex)
            {                
