        /// <summary>
        /// Calculates the accrued interest of a security in the case of periodic payments.
        /// </summary>
        /// <param name="args">Number and the number of digits</param>
        /// <returns>Accrued interest</returns>
        public string ComputeACCRINT(string args)
        {
            double accrint = 0;
            try
            {

                string[] argsArray = args.Split(new char[] { ParseArgumentSeparator });
                if (argsArray.Length < 5)
                {                    
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }

                string s1 = argsArray[0];
                string s2 = argsArray[1];
                string s3 = argsArray[2];
                string s4 = argsArray[3];
                string s5 = argsArray[4];
                string s6 = argsArray[5];
                string s7 = argsArray.Length < 7 ? "0" : argsArray[6];
                string s8 = argsArray.Length < 8 ? "0" : argsArray[7];
                s1 = this.GetValueFromArg(s1);
                s2 = this.GetValueFromArg(s2);
                s3 = this.GetValueFromArg(s3);
                s4 = this.GetValueFromArg(s4);
                s5 = this.GetValueFromArg(s5);
                s6 = this.GetValueFromArg(s6);


                //issue, first, settlement, rate, par, frequency, basis, method
                double rate = 0, par = 0, factor = 0, yearfracER = 0.277777777;

                DateTime issue = new DateTime();
                DateTime settlement = new DateTime();
                DateTime firstSettlement = new DateTime();
                double issuedouble = 0, setdouble = 0, firstSetdouble = 0;
                if (!(DateTime.TryParse(s1.Replace(TIC, string.Empty), out issue) || double.TryParse(s1.Replace(TIC, string.Empty), out issuedouble)) || !(double.TryParse(s2.Replace(TIC, string.Empty), out firstSetdouble) || (DateTime.TryParse(s2.Replace(TIC, string.Empty), out firstSettlement))) || !(double.TryParse(s3.Replace(TIC, string.Empty), out setdouble) || (DateTime.TryParse(s3.Replace(TIC, string.Empty), out settlement))))
                {
                    return ErrorStrings[1].ToString();
                }
                double frequency = 0;
                double.TryParse(s6, out frequency);
                double.TryParse(s4, out rate);
                double.TryParse(s5, out par);
                if (issuedouble > 0 || setdouble > 0)
                    issue = this.GetDateFromSerialDate((int)issuedouble);
                if (setdouble > 0)
                    settlement = this.GetDateFromSerialDate((int)setdouble);
                if (firstSetdouble > 0)
                    firstSettlement = this.GetDateFromSerialDate((int)firstSetdouble);
                if (this.dateTime1900.Year > issue.Year || this.dateTime1900.Year > settlement.Year || this.dateTime1900.Year > firstSettlement.Year)
                {
                    return ErrorStrings[4].ToString();
                }
                string iss = this.TIC + this.Parse("DATE(" + issue.Year + ParseArgumentSeparator + issue.Month + ParseArgumentSeparator + issue.Day + ")") + this.TIC;
                string set = this.TIC + this.Parse("DATE(" + settlement.Year + ParseArgumentSeparator + settlement.Month + ParseArgumentSeparator + settlement.Day + ")") + this.TIC;
                switch (s7)
                {
                    case "0":
                    // US (NASD) 30/360
                    case "1":
                    // Actual/actual
                    case "2":
                    // Actual/360
                    case "3":
                    // Actual/365
                    case "4":
                        // European 30/360
                        factor = double.Parse(ComputeYearFrac(string.Format("{0},{1},{2}", iss, set, s7)));
                        break;
                    default:
                        return ErrorStrings[4].ToString();
                }
                double firstValue = par * (rate / (int)frequency);
                accrint = firstValue * factor * (int)frequency;
                accrint = ((int)frequency == 4) ? (accrint + yearfracER) : accrint;
            }
            catch (Exception ex)
            {
                return ex.Message;
            }

            return accrint.ToString();

        }  
     

        private int critbinom(int nTrials, double p, double alpha)
        {
            int checkval = nTrials;
            int half = nTrials;
            double dist = 1;
            double dist1 = 1;
            do
            {
                half = half / 2 + 1;
                if (dist >= alpha)
                {
                    dist1 = binomdist(nTrials, checkval - 1, p);
                    if (double.IsNaN(dist1))
                    {
                        return int.MaxValue;
                    }

                    if (dist1 < alpha && dist1 > 0)
                    {
                        break;
                    }

                    checkval = checkval - half;
                }
                else
                {
                    dist1 = binomdist(nTrials, checkval + 1, p);
                    if (dist1 >= alpha)
                    {
                        checkval = checkval + 1;
                        break;
                    }

                    checkval = checkval + half;
                }

                dist = binomdist(nTrials, checkval, p);
            }
            while (checkval < nTrials && checkval > 0);

            return checkval;
        }

        /// <summary>
        /// Returns the sum of the squares of the mean deviations.
        /// </summary>
        /// <param name="range">A string holding a list (separated by commas) of:
        /// cell references,
        /// formulas, or numbers.
        /// </param>
        /// <returns>Sum of the squares of the mean deviation.</returns>
        public string ComputeDevsq(string range)
        {
            double d;

            double[] x = GetDoubleArray(range);
            int n = x.GetLength(0);
            if (n <= 0)
            {
                return FormulaErrorStrings[wrong_number_arguments];
            }

            double sumx = 0;
            for (int i = 0; i < n; ++i)
            {
                sumx += x[i];
            }

            sumx = sumx / n;
            double sumx2 = 0;

            for (int i = 0; i < n; ++i)
            {
                d = x[i] - sumx;
                sumx2 += d * d;
            }

            return sumx2.ToString();
        }

        /// <summary>
        /// Returns the exponential distribution.
        /// </summary>
        /// <param name="argList">X, lambda, cumulative.</param>
        /// <returns>Returns exponential distribution.</returns>
        /// <remarks>
        /// Cumulative should be either 
        /// True if you want to return the value of the distribution function or False
        /// if you want to return the value of the density function. 
        /// </remarks>
        public string ComputeExpondist(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
                return FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double lambda;
            double cum = 0;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], out x)
                && double.TryParse(args[1], out lambda))
            {
                cum = (args[2] == "1" || args[2] == TRUEVALUESTR) ? 1 : 0;
                if (cum == 0)
                {
                    dist = lambda * Math.Exp(-lambda * x);
                }
                else
                {
                    dist = 1 - Math.Exp(-lambda * x);
                }
            }

            return dist.ToString();
        }

        /// <summary>
        /// Returns the F (Fisher) probability distribution.
        /// </summary>
        /// <param name="argList">X, degreesfreedom1, degreesfreedom2.</param>
        /// <returns>Returns the F probability distribution.</returns>
        public string ComputeFdist(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
                return FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double df1 = 0;
            double df2 = 0;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], out x)
                && double.TryParse(args[1], out df1)
                && double.TryParse(args[2], out df2))
            {
                double mult = Math.Exp(
                    gammaln((df1 + df2) / 2) -
                    gammaln(df1 / 2) -
                    gammaln(df2 / 2) +
                    (df1 / 2) * Math.Log(df1 / df2));

                dist = 1 - mult * fdist(x, (int)df1, (int)df2);
            }

            return dist.ToString();
        }

        private double fdensity(double x, int df1, int df2)
        {
            return Math.Pow(x, (df1 - 2) / 2d) / Math.Pow(1 + df1 * x / df2, (df1 + df2) / 2d);
        }

        private double fdist(double x, int df1, int df2)
        {
            int nPanels = 32;

            double leftside = 0;
            double rightside = x;

            double h = (rightside - leftside) / nPanels;
            double mult = h / 3;

            double sum1 = fdensity(leftside, df1, df2) + fdensity(rightside, df1, df2);
            double sum4 = 0;
            for (int i = 1; i < nPanels; i += 2)
            {
                sum4 += 4 * fdensity(leftside + i * h, df1, df2);
            }

            double sum2 = 0;
            for (int i = 2; i < nPanels; i += 2)
            {
                sum2 += 2 * fdensity(leftside + i * h, df1, df2);
            }

            double gd = mult * (sum1 + sum2 + sum4);
            double oldgd = gd;
            double eps = 1e-7;

            int k = 0;

            for (k = 0; k < 20; ++k)
            {
                nPanels *= 2;

                sum2 += sum4 / 2;
                sum4 = 0;
                h = (rightside - leftside) / nPanels;
                for (int i = 0; i < nPanels; ++i)
                {
                    if (i % 2 == 1)
                    {
                        double d = fdensity(leftside + h * i, df1, df2);
                        sum4 += d;
                    }
                }

                sum4 = 4 * sum4;
                mult = h / 3;
                gd = mult * (sum1 + sum2 + sum4);

                if (Math.Abs((gd - oldgd) / oldgd) < eps)
                {
                    break;
                }

                oldgd = gd;
            }

            ////Console.WriteLine(k.ToString() + "  " + gd.ToString());
            return gd;
        }

        private double finv(double p, int df1, int df2)
        {
            double mult = Math.Exp(
                gammaln((df1 + df2) / 2d) -
                gammaln(df1 / 2d) -
                gammaln(df2 / 2d) +
                (df1 / 2d) * Math.Log((double)df1 / df2));
            double guess = mult;
            ////            if( p < .05)
            ////                guess = u - 2 * s;
            ////            else if( p < .5)
            ////                guess = u;
            ////            else if( p < .95)
            ////                guess = u + 2 * s;
            ////            else
            ////                guess = u + 5 * s;

            double lastIncrement = guess / 2;
            double gi = 0;
            double eps = 1e-7;
            int k = 100;
            int tries = 3;
            int its = 0;
            while (k == 100 && tries > 0)
            {
                tries--;
                guess = guess / 2;
                lastIncrement = guess / 2;

                for (k = 0; k < 100; ++k)
                {
                    its++;
                    gi = 1 - mult * fdist(guess, df1, df2);
                    ////Console.WriteLine("{0}: guess {1}  computed {2}  target {3}", its, guess, gi, p);
                    if (Math.Abs((gi - p) / p) < eps)
                    {
                        break;
                    }
                    ////greater since looking for 1 - xxxx
                    if (gi > p)
                    {
                        guess += lastIncrement;
                    }
                    else
                    {
                        lastIncrement = lastIncrement / 2;
                        if (guess - lastIncrement < 0)
                        {
                            lastIncrement = guess / 2;
                        }

                        guess -= lastIncrement;
                    }
                }
            }

            if (k == 100)
            {
                guess = -1;
            }

            ////Console.WriteLine(its);
            return guess;
        }

        /// <summary>
        /// Returns the inverse of F distribution.
        /// </summary>
        /// <param name="argList">P, degreesfreedom1, degreesfreedom2.</param>
        /// <returns>Returns x such that F distribution at x is p.</returns>
        /// <remarks>
        /// P should be between 0 and 1.
        /// </remarks>
        public string ComputeFinv(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
                return FormulaErrorStrings[wrong_number_arguments];
            }

            double p;
            double df1;
            double df2;
            double invdist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], out p)
                && (p > 0 && p < 1)
                && double.TryParse(args[1], out df1)
                && double.TryParse(args[2], out df2))
            {
                invdist = finv(p, (int)df1, (int)df2);
            }

            if (invdist <= 0)
            {
                return FormulaErrorStrings[iterations_dont_converge];
            }

            return invdist.ToString();
        }

        /// <summary>
        /// Returns the Fisher transformation of the input variable.
        /// </summary>
        /// <param name="argList">Input variable x.</param>
        /// <returns>Fisher transformation of x.</returns>
        /// <remarks>
        /// X should be between -1 and 1.
        /// </remarks>
        public string ComputeFisher(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 1)
            {
                return FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double z = 0;

            string s = GetValueFromArg(args[0]);

            if (double.TryParse(s, out x)
                && (x > -1 && x < 1))
            {
                z = 0.5 * Math.Log((1 + x) / (1 - x));
            }

            return z.ToString();
        }

        /// <summary>
        /// Returns the inverse of Fisher transformation.
        /// </summary>
        /// <param name="argList">Input variable y.</param>
        /// <returns>The value x such that the Fisher transformation y is x.</returns>
        public string ComputeFisherinv(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 1)
            {
                return FormulaErrorStrings[wrong_number_arguments];
            }

            double y;
            double x = 0;

            string s = GetValueFromArg(args[0]);

            if (double.TryParse(s, out y))
            {
                double d = Math.Exp(2 * y);
                x = (d - 1) / (d + 1);
            }

            return x.ToString();
        }

        /// <summary>
        /// Returns a forecasted value based on two sets of points using Least Square Fit regression.
        /// </summary>
        /// <param name="range">X, rangex, rangey.</param>
        /// <returns>returns Forecasted.</returns>
        public string ComputeForecast(string range)
        {
            string[] args = range.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
                return FormulaErrorStrings[wrong_number_arguments];
            }

            double x0, d;
            string s1 = GetValueFromArg(args[0]);
            if (!double.TryParse(s1, out x0))
            {
                return FormulaErrorStrings[invalid_arguments];
            }

            double[] y = GetDoubleArray(args[1]);
            double[] x = GetDoubleArray(args[2]);
            int n = x.GetLength(0);

            if (n <= 0 || n != y.GetLength(0))
            {
                return FormulaErrorStrings[wrong_number_arguments];
            }

            double sumx = 0;
            double sumy = 0;
            for (int i = 0; i < n; ++i)
            {
                sumx += x[i];
                sumy += y[i];
            }

            sumx = sumx / n;
            sumy = sumy / n;

            double sumxy = 0;
            double sumx2 = 0;
            for (int i = 0; i < n; ++i)
            {
                d = x[i] - sumx;
                sumxy += d * (y[i] - sumy);
                sumx2 += d * d;
            }

            double b = sumxy / sumx2;
            double a = sumy - b * sumx;
            return (a + b * x0).ToString();
        }

