                    SetValueToGridColumnOrRow(cells[i], newx[i], isColumn, isColumn ? RowIndex(cell) : ColIndex(cell));
                }
            }
            return newx[0].ToString();
        }

        /// <summary>
        /// A method that sets the data value to the specified cell.
        /// </summary>
        /// <param name="cell1">The grid cell </param>
        /// <param name="value">The value.</param>
        /// <param name="isColumn">bool value is Column</param>
        /// <param name="fixedIndex">Index value</param>
        internal void SetValueToGridColumnOrRow(string cell1, object value, bool isColumn, int fixedIndex)
        {
            int i = cell1.LastIndexOf(sheetToken);
            int row, col;
            GridModel grd = grid;
            if (i > -1)
            {
                GridSheetFamilyItem family = GetSheetFamilyItem(this.grid);

                grd = (GridModel)family.TokenToGridModel[cell1.Substring(0, i + 1)];
                row = RowIndex(cell1);
                col = ColIndex(cell1);
            }
            else
            {
                row = RowIndex(cell1);
                col = ColIndex(cell1);
            }
            if (isColumn)
            {
                grd[fixedIndex, col].CellValue = value;
            }
            else
            {
                grd[row, fixedIndex].CellValue = value;
            }

        }

        /// <summary>
        /// Returns the m and b value used in exponential curve y = b * m^x.
        /// </summary>
        /// <param name="y">The set of y-values required in y = b*m^x</param>
        /// <param name="x">The set of x-values in y = b*m^x</param>
        /// <param name="m">The double value</param>
        /// <param name="b">The double value</param>
        /// <returns>returns calculated b,m value.</returns>
        internal void ComputeLogestMB(double[] y, double[] x, out double m, out double b)
        {
            m = 0;
            b = 1;


            int n = x.GetLength(0);
            double sumx = 0;
            double sumy = 0;
            for (int i = 0; i < n; ++i)
            {
                sumx += (double)x[i];
                sumy += (double)y[i];
            }

            sumx = sumx / n;
            sumy = sumy / n;

            double sumxy = 0;
            double sumx2 = 0;
            double d;
            for (int i = 0; i < n; ++i)
            {
                d = (double)x[i] - sumx;
                sumxy += d * (y[i] - sumy);
                sumx2 += d * d;
            }

            b = Math.Pow(10, sumy - sumxy / sumx2 * sumx);
            m = Math.Pow(10, sumxy / sumx2);
        }

