        /// <summary>
        /// Returns the value at a specified row and column from within a given range.
        /// </summary>
        /// <param name="arg">look_range, row, col</param>
        /// <returns>The value.</returns>
        /// <remarks>
        /// Both array and reference form of this function are supported.
        /// </remarks>
        public string ComputeIndex(string arg)
        {
            string r = string.Empty;
            string sheet = string.Empty;
            string s = string.Empty;
            bool sum = false;
            int row = -1, col = -1, top = -1, bot = -1, left = -1, right = -1;
            if (arg[arg.Length - 1] == BMARKER)
            {
                arg = GetValueFromArg(arg);
            }

            string[] args = arg.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);

            s = this.grid.Model[this.RowIndex(this.cell), this.ColIndex(this.cell)].Text;
            s = s.ToUpper();
            if (s.Contains(this.ActiveFunctionName))
            {
                if (s.IndexOf(this.ActiveFunctionName) - 2 != -1)
                {
                    string func = string.Empty;
                    for (int i = s.IndexOf(this.ActiveFunctionName) - 2; i >= 0; i--)
                    {
                        func = s[i] + func;
                        if (func.Equals("SUM"))
                        {
                            sum = true;
                            break;
                        }
                    }
                }
                else
                {
                    s = s.Replace("=" + this.ActiveFunctionName, string.Empty);
                    this.SwapInnerParens(ref s);
                }
            }


            if (s.Contains("{") && s.Contains("}"))
            {
                string innerArg = string.Empty;
                for (int j = s.IndexOf('{') + 1; j < s.IndexOf('}'); j++)
                {
                    innerArg += s[j];
                }
                string[] innerArgs = innerArg.Split(new char[] { ParseArgumentSeparator });

                int innerArgCount = innerArgs.GetLength(0);
                int cnt = 0;

                if (argCount < 2 || argCount > innerArgCount + 3 || argCount == innerArgCount)
                {
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }

                if (innerArgCount >= 1)
                {
                    cnt = argCount - innerArgCount;
                    if (cnt == 2)
                    {
                        string rcCell = innerArgs[0].ToUpper().Replace(TIC, string.Empty);
                        string[] cells = rcCell.Split(new char[] { ':' }, StringSplitOptions.RemoveEmptyEntries);

                        if (cells.Length == 2)
                        {
                            if (this.ColIndex(cells[1]) != this.ColIndex(cells[0]))
                            {
                                return this.FormulaErrorStrings[wrong_number_arguments];
                            }
                        }
                        r = innerArgs[0];
                    }
                    else
                    {
                        if (int.Parse(args[argCount - 1]) <= innerArgCount)
                            if (int.Parse(args[argCount - 1]) > 0)
                                r = innerArgs[int.Parse(args[argCount - 1]) - 1];
                            else
                                return "#VALUE!";
                        else
                            return "#REF!";
                    }
                    r = r.Replace(TIC, "");
                    int i = r.IndexOf(":");
                    ////single cell
                    if (i == -1)
                    {
                        return this.FormulaErrorStrings[invalid_arguments];
                    }

                    if (arg.IndexOf("#N/A") > -1 || arg.IndexOf("#N~A") > -1)
                    {
                        return "#N/A";
                    }

                    sheet = SheetToken(args[innerArgCount - 1].Replace(TIC, string.Empty)); ;

                    double d;
                    row = (cnt == 1) ? 1 : double.TryParse(this.GetValueFromArg(args[innerArgCount]), NumberStyles.Integer, null, out d) ? (int)d : -1;
                    col = (cnt <= 2) ? 1 : double.TryParse(this.GetValueFromArg(args[innerArgCount + 1]), NumberStyles.Integer, null, out d) ? (int)d : -1;
                    if (row <= 0 || col <= 0)
                    {
                        return "#VALUE!";
                    }

                    top = this.RowIndex(r.Substring(0, i));
                    bot = this.RowIndex(r.Substring(i + 1));
                    left = this.ColIndex(r.Substring(0, i));
                    right = this.ColIndex(r.Substring(i + 1));
                    if (row > bot - top + 1 || col > right - left + 1)
                    {
                        return "#REF!";
                    }

                    row = this.RowIndex(r.Substring(0, i)) + row - 1;
                    col = this.ColIndex(r.Substring(0, i)) + col - 1;
                }

            }
            else
            {
                if (argCount < 2 || argCount > 4)
                {
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }

                if (argCount == 2)
                {
                    string rcCell = args[0].ToUpper().Replace(TIC, string.Empty);
                    string[] cells = rcCell.Split(new char[] { ':' }, StringSplitOptions.RemoveEmptyEntries);

                    if (cells.Length == 2)
                    {
                        if (!((this.ColIndex(cells[1]) == this.ColIndex(cells[0])) || (this.RowIndex(cells[1]) == this.RowIndex(cells[0]))))
                        {
                            return this.FormulaErrorStrings[invalid_expression];
                        }
                    }
                    int val;
                    if (!int.TryParse(args[1], out val))
                        return this.FormulaErrorStrings[invalid_expression];

                }
                else if (argCount == 4)
                {
                    int val;
                    if (int.TryParse(args[argCount - 1], out val))
                    {
                        if (val <= 0)
                            return "#VALUE!";
                        else if (val > 1)
                            return "#REF!";
                        else if (sum)
                        {
                            sum = false;
                            string rcCell = args[0].ToUpper().Replace(TIC, string.Empty);
                            string[] cells = rcCell.Split(new char[] { ':' }, StringSplitOptions.RemoveEmptyEntries);
                            if (cells.Length == 2)
                            {
                                int topRow = this.RowIndex(cells[0]);
                                int result = -1;
                                string st = string.Empty;
                                string leftCol = string.Empty;
                                if (int.TryParse(args[argCount - 2], out result))
                                {
                                    leftCol = GridRangeInfo.GetAlphaLabel(result);
                                    st = leftCol + topRow + ":" + cells[1];
                                    return st;
                                }
                            }
                            sum = false;
                        }
                    }

                }
                r = args[0];
                r = r.Replace(TIC, "");
                int i = r.IndexOf(":");
                ////single cell
                if (i == -1)
                {
                    return this.FormulaErrorStrings[invalid_arguments];
                }

                if (arg.IndexOf("#N/A") > -1 || arg.IndexOf("#N~A") > -1)
                {
                    return "#N/A";
                }

                sheet = SheetToken(args[0].Replace(TIC, string.Empty)); ;

                double d;
                row = (argCount == 1) ? 1 : double.TryParse(this.GetValueFromArg(args[1]), NumberStyles.Integer, null, out d) ? (int)d : -1;
                col = (argCount <= 2) ? 1 : double.TryParse(this.GetValueFromArg(args[2]), NumberStyles.Integer, null, out d) ? (int)d : -1;
                if (row == -1 || col == -1)
                {
                    return "#REF!";
                }

                top = this.RowIndex(r.Substring(0, i));
                bot = this.RowIndex(r.Substring(i + 1));
                left = this.ColIndex(r.Substring(0, i));
                right = this.ColIndex(r.Substring(i + 1));
                if (row > bot - top + 1 || col > right - left + 1)
                {
                    return "#REF!";
                }

                row = this.RowIndex(r.Substring(0, i)) + row - 1;
                col = this.ColIndex(r.Substring(0, i)) + col - 1;
            }
            return this.GetValueFromArg(string.Format("{2}{0}{1}", GridRangeInfo.GetAlphaLabel(col), row, sheet));
        }

        /// <summary>
        /// Returns the reference specified by a text string. References are immediately evaluated to display their contents.
        /// <para>Syntax: INDIRECT(CellRefString, [IsA1Style])</para>
        /// </summary>
        /// <param name="args">Cell reference string.</param>
        /// <returns>Reference specified the argument.</returns>
        public string ComputeIndirect(string args)
        {
            if (args[args.Length - 1] == BMARKER)
            {
                args = GetValueFromArg(args);
            }

            string[] arg = args.Split(new char[] { ParseArgumentSeparator });
            if (arg.Length == 0 || arg.Length > 2)
            {
                throw new ArgumentException("No. of argument cant be less than 1 or more than 2.");
            }

            arg[0] = arg[0].ToUpper();
            PutTokensForSheets(ref arg[0]);
            string sheetToken = SheetToken(arg[0].Replace(TIC, string.Empty));

            ////Remove SheetToken
            if (!String.IsNullOrEmpty(sheetToken))
            {
                arg[0] = arg[0].Replace(sheetToken, string.Empty);
            }

            if (arg.Length == 2 && arg[1] == FALSEVALUESTR)
            {
                bool hasTIC = arg[0].StartsWith(TIC) && arg[0].EndsWith(TIC);
                string rcCell = arg[0].ToUpper().Replace(TIC, string.Empty);
                string[] cells = rcCell.Split(new char[] { ':' }, StringSplitOptions.RemoveEmptyEntries);

                string[] rc = cells[0].Split(new char[] { 'R', 'C' }, StringSplitOptions.RemoveEmptyEntries);
                if (cells.Length > 2)
                {
                    return "#REF!";
                }

                arg[0] = GridRangeInfo.GetAlphaLabel(Convert.ToInt32(rc[1])) + rc[0];

                if (cells.Length == 2)
                {
                    string st = SheetToken(cells[1]);
                    if (!String.IsNullOrEmpty(st))
                    {
                        cells[1] = cells[1].Replace(st, string.Empty);
                    }

                    rc = cells[1].Split(new char[] { 'R', 'C' }, StringSplitOptions.RemoveEmptyEntries);
                    arg[0] += ":" + GridRangeInfo.GetAlphaLabel(Convert.ToInt32(rc[1])) + rc[0];
                }

                if (hasTIC)
                {
                    arg[0] = TIC + arg[0] + TIC;
                }
            }

            string cellReference = string.Empty;
            if (arg[0].StartsWith(TIC))
            {
                ////String
                cellReference = sheetToken + arg[0].Replace(TIC, string.Empty);
            }
            else
            {
                if (IsCellReference(arg[0]))
                {
                    cellReference = GetValueFromArg(sheetToken + arg[0]);
                }
            }

            if (!IsCellReference(cellReference))
            {
                if (NamedRanges.Contains(cellReference.ToUpper()))
                {
                    cellReference = Convert.ToString(NamedRanges[cellReference.ToUpper()]);
                }
                else
                {
                    return "#REF!";
                }
            }

            if (cellReference.Contains(":"))
            {
                return cellReference;
            }

            return GetValueFromArg(cellReference);
        }

        /// <summary>
        /// In a given string, this method substitutes an occurrence of one string with another string.
        /// </summary>
        /// <param name="range">A list of 3 or 4 arguments: the original string, the search string, the 
        /// replacement string, and optionally, an integer representing the occurrence to be replaced.
        ///    </param>
        /// <returns>The modified string.</returns>
        public string ComputeSubstitute(string range)
        {
            string[] args = range.Split(new char[] { ParseArgumentSeparator });
            if (args.Length != 3 && args.Length != 4)
            {
                return FormulaErrorStrings[wrong_number_arguments];
            }

            ////strip off outside tics (if any) on the evaluated arguments
            string s1 = StripTics0(GetValueFromArg(args[0]));
            string s2 = StripTics0(GetValueFromArg(args[1]));
            string s3 = StripTics0(GetValueFromArg(args[2]));
            if (args.Length == 3)
            {
                s1 = s1.Replace(s2, s3);
            }
            else
            {
                string s4 = GetValueFromArg(args[3]);
                double d = 0;
                if (double.TryParse(s4, NumberStyles.Integer, null, out d))
                {
                    int count = (int)d;
                    int loc = -1;
                    while (count > 0 && (loc = s1.IndexOf(s2, loc + 1)) > -1)
                    {
                        count--;
                    }

                    if (count == 0)
                    {
                        s1 = s1.Substring(0, loc) + s3 + s1.Substring(loc + s2.Length);
                    }
                }
            }

            return TIC + s1 + TIC;
        }

        private string StripTics0(string s)
        {
            if (s.Length > 1 && s[0] == TIC[0] && s[s.Length - 1] == TIC[0])
            {
                s = s.Substring(1, s.Length - 2);
            }

            return s;
        }

