        /// <summary>
        /// Returns the product of the arguments in the list.
        /// </summary>
        /// <param name="range">List of arguments.</param>
        /// <returns>Product of the arguments.</returns>
        public string ComputeProduct(string range)
        {
            double prod = 1;
            double d;
            string s1;
            bool nohits = true;
            foreach (string r in range.Split(new char[] { ParseArgumentSeparator }))
            {
                if (r.IndexOf(':') > -1)
                {
                    foreach (string s in GetCellsFromArgs(r))
                    {
                        try
                        {
                            s1 = GetValueFromArg(s, true);
                        }
                        catch (Exception ex)
                        {
                            return ex.Message;
                        }

                        if (s1.Length > 0)
                        {
                             if (double.TryParse(s1, out d))
                            {
                                prod = prod * d;
                                nohits = false;
                            }
                        }
                    }
                }
                else
                {
                    if (double.TryParse(GetValueFromArg(r), out d))
                    {
                        prod = prod * d;
                        nohits = false;
                    }
                }
            }

            return nohits ? "0" : prod.ToString();
        }

        /// <summary>
        /// Returns a quoted string from a date or number.
        /// </summary>
        /// <param name="range">Value to be converted to a string.</param>
        /// <returns>Quoted string.</returns>
        public string ComputeText(string range)
        {
            string s1 = range.Split(new char[] { ParseArgumentSeparator })[0];
            string s2 = range.Split(new char[] { ParseArgumentSeparator })[1].Replace(TIC, string.Empty);
            s1 = GetValueFromArg(s1);
            double d;
            DateTime dtime = this.dateTime1900;
            if (double.TryParse(s1, NumberStyles.Any, null, out d) || DateTime.TryParse(s1.Replace(this.TIC, string.Empty), out dtime))
            {
                if (s2.Length > 0 && s2.ToUpper().IndexOfAny(new char[] { 'M', 'D', 'Y', 'S', 'T' }) > -1)
                {
                    s2 = s2.Replace('Y', 'y').Replace('D', 'd').Replace('H', 'h').Replace('S', 's').Replace('m', 'M').Replace("AM/PM", "tt");
                    char[] formatChar = s2.ToCharArray();
                    bool isH = false, isMFound = false, isFirstM = false; ;
                    int i = 0, mcount = 0;
                    int lastCharIndex = 0, totalCharforM = 0;
                    foreach (char c in formatChar)
                    {

                        if (c == 's' && formatChar[lastCharIndex] == 'M')
                        {
                            formatChar[lastCharIndex] = 'm';
                            if (formatChar[lastCharIndex - 1] == 'M')
                                formatChar[lastCharIndex - 1] = 'm';
                        }
                        if (Char.IsLetter(c))
                        {
                            lastCharIndex = i;
                            if (c == 'M')
                            {
                                mcount++;
                                totalCharforM++;
                            }
                        }
                        else if (totalCharforM > 1)
                            totalCharforM++;
                        if (c == 'M' && isH)
                        {

                            formatChar[i] = 'm';
                            isMFound = true;
                            isFirstM = (mcount == 1);
                        }
                        if (c == 'M' && totalCharforM == mcount)
                            formatChar[i] = 'm';
                        if (c == 'h')
                        {
                            isH = true;
                        }
                        else if (Char.IsLetter(c) && c != 'M' && c != 'h' && !isMFound)
                        {
                            isH = false;
                            isMFound = false;
                        }
                        i++;
                    }
                    s2 = new string(formatChar);
                    DateTime dt = DateTime.FromOADate(d);
                    if (d == 0)
                        dt = dtime;
                    s1 = dt.ToString(s2);
                }
                else
                {
                    s2 = string.Format("{{0:{0}}}", s2);
                    s1 = string.Format(s2, d);
                }
            }

            return TIC + s1 + TIC;
        }

        /// <summary>
        /// Returns a number.
        /// </summary>
        /// <param name="range">A date or number string.</param>
        /// <returns>returns a number.</returns>
        public string ComputeValue(string range)
        {
            string val = string.Empty;
            try
            {
                string[] args = range.Split(new char[] { ParseArgumentSeparator });
                int argCount = args.GetLength(0);
                if (argCount > 0)
                {
                    string s1 = args[0];
                    bool ticContains = false;
                    bool quotation = false;
                    if (s1.Contains(TIC))
                        ticContains = true;
                    if (!string.IsNullOrEmpty(s1) && !IsCellReference(s1) && ticContains)
                    {
                        s1 = s1.Replace(this.TIC, string.Empty);
                        quotation = true;
                    }
                    s1 = this.GetValueFromArg(s1);
                    if (string.IsNullOrEmpty(s1) && ticContains)
                    {
                        return this.ErrorStrings[1].ToString();
                    }
                    else if (string.IsNullOrEmpty(s1) && !ticContains)
                    {
                        return FormulaErrorStrings[invalid_arguments];
                    }
                    if (s1.StartsWith("$"))
                    {
                        s1 = s1.Replace("$", string.Empty);
                    }
                    if (s1.StartsWith("%") || s1.EndsWith("%"))
                    {
                        s1 = s1.Replace("%", string.Empty);
                        double per = 0;
                        if (double.TryParse(s1, NumberStyles.Number | NumberStyles.AllowExponent, null, out per))
                        {
                            s1 = (per / 100).ToString();
                        }
                    }
                    DateTime dt;
                    TimeSpan ts;
                    double dous = 0;
                    int inv = 0;
                    if (int.TryParse(s1, NumberStyles.Number | NumberStyles.AllowExponent, null, out inv))
                    {
                        val = inv.ToString();
                    }
                    else if (TimeSpan.TryParse(s1, out ts))
                    {
                        if (quotation)
                            val = ComputeTimevalue(ts.ToString());
                        else
                        {
                            return FormulaErrorStrings[invalid_arguments];
                        }
                    }
                    else if (DateTime.TryParse(s1, out dt))
                    {
                        val = ComputeDatevalue(dt.ToString());
                    }
                    else if (double.TryParse(s1, NumberStyles.Number | NumberStyles.AllowExponent, null, out dous))
                    {
                        val = dous.ToString();
                    }
                    else
                    {
                        return this.ErrorStrings[1].ToString();
                    }
                }
                else
                {
                    return FormulaErrorStrings[wrong_number_arguments];
                }
            }
            catch (Exception ex)
            {
                return ex.Message;
            }
            return val.ToString();
        }

        /// <summary>
        /// Returns the remainder after dividing one number by another.
        /// </summary>
        /// <param name="range">Two numbers in a list.</param>
        /// <returns>The remainder.</returns>
        public string ComputeMod(string range)
        {
            string s1 = range.Split(new char[] { ParseArgumentSeparator })[0];
            string s2 = range.Split(new char[] { ParseArgumentSeparator })[1];
            s1 = GetValueFromArg(s1);
            s2 = GetValueFromArg(s2);
            int i = int.Parse(s2);
            return (Math.Sign(i) * Math.Abs((int.Parse(s1) % i))).ToString();
        }

        /// <summary>
        /// Returns the integer value.
        /// </summary>
        /// <param name="range">Number to be truncated.</param>
        /// <returns>An integer.</returns>
        public string ComputeInt(string range)
        {
            range = GetValueFromArg(range);
            double d;
            if (double.TryParse(range, out d))
            {
                double d1 = (d < 0) ? -1 : 1;
                double d2 = (d < 0) ? 1 : 0;
                return (d1 * Math.Floor(d2 + Math.Abs(d))).ToString("F0");
            }

            return "0";
        }

        /// <summary>
        /// Truncates a number to an integer.
        /// </summary>
        /// <param name="range">Value and number of digits.</param>
        /// <returns>Truncated value.</returns>
        public string ComputeTrunc(string range)
        {
            string[] args = range.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            double digits = 0;

            if (argCount == 2)
            {
                ////ignore return value...
                double.TryParse(GetValueFromArg(args[1]), NumberStyles.Integer, null, out digits);
            }

            range = GetValueFromArg(args[0]);

            double d;
            if (double.TryParse(range, out d))
            {
                string format = digits == 0 ? "F0" : ("0." + new string('0', (int)digits));
                double normalizer = Math.Pow(10, digits);
                double d1 = (d < 0) ? -1 : 1;
                return (d1 * Math.Floor(normalizer * Math.Abs(d)) / normalizer).ToString(format);
            }

            return "0";
        }

        /// <summary>
        /// Returns the sum of the products of corresponding values.
        /// </summary>
        /// <param name="range">Two cell ranges.</param>
        /// <returns>Sum of the products.</returns>
        public string ComputeSumProduct(string range)
        {
            double sum = 0;
            int count = 0;
            double d;
            double[] vector = null;

            foreach (string r in range.Split(new char[] { ParseArgumentSeparator }))
            {
                if (r.IndexOf(':') > -1)
                {
                    int i = r.IndexOf(":");
                    int row1 = RowIndex(r.Substring(0, i));
                    int col1 = ColIndex(r.Substring(0, i));
                    int row2 = RowIndex(r.Substring(i + 1));
                    int col2 = ColIndex(r.Substring(i + 1));

                    if (vector == null)
                    {
                        count = (row2 - row1 + 1) * (col2 - col1 + 1);
                        vector = new double[count];
                        for (i = 0; i < count; ++i)
                        {
                            vector[i] = 1d;
                        }
                    }

                    int k = 0;
                    string s1;
                    foreach (string s in GetCellsFromArgs(r))
                    {
                        try
                        {
                            s1 = GetValueFromArg(s);
                        }
                        catch (Exception ex)
                        {
                            return ex.Message;
                        }

                        if (s1.Length > 0)
                        {
                            if (double.TryParse(s1, NumberStyles.Number | NumberStyles.AllowExponent, null, out d))
                            {
                                vector[k] = vector[k] * d;
                            }
                        }
                        //Fix for issue SD3204
                        else if (s1.Equals(string.Empty))
                        {
                            vector[k] = 0d; // empty needs to be considered as zero and hence zero multiplied by anything will result in zero
                        }

                        k++;
                    }
                }
                else
                {
                    break;
                }
            }

            for (int i = 0; i < count; ++i)
            {
                sum += vector[i];
            }

            return sum.ToString();
        }

