        /// <summary>
        /// Returns the Multinominal value of given range of numbers.
        /// </summary>
        /// <param name="range">Given numbers</param>
        /// <returns>Multinominal value of given range of numbers</returns>
        public string ComputeMultinomial(string range)
        {
            double d;
            string s1;
            string str = string.Empty;
            int arrayList = 0, elements = 0;
            string total = ComputeSum(range);
            string totalFact = ComputeFact(total);
            string[] ranges = range.Split(new char[] { ParseArgumentSeparator });
            if (ranges.Length > 0)
            {
                foreach (string r in ranges)
                {
                    elements++;
                    if (r.IndexOf(':') > -1)
                    {
                        --elements;
                        foreach (string s in this.GetCellsFromArgs(r))
                            elements++;
                    }
                }
            }
            string[] ranges2 = new string[elements];
            foreach (string r in ranges)
            {
                ////is a cellrange
                if (r.IndexOf(':') > -1)
                {
                    foreach (string s in this.GetCellsFromArgs(r))
                    {
                        try
                        {
                            s1 = this.GetValueFromArg(s);
                        }
                        catch (Exception ex)
                        {
                            TraceUtil.TraceExceptionCatched(ex);
                            if (!ExceptionManager.RaiseExceptionCatched(this, ex))
                            {
                                throw ex;
                            }
                            return ex.Message;
                        }
                        if (s1.Length > 0 && double.TryParse(s1, NumberStyles.Any, null, out d))
                        {
                            string fact = ComputeFact(d.ToString());
                            ranges2[arrayList] = fact;
                            arrayList++;
                        }
                    }
                }
                else
                {
                    try
                    {
                        s1 = this.GetValueFromArg(r);
                    }
                    catch (Exception ex)
                    {
                        TraceUtil.TraceExceptionCatched(ex);
                        if (!ExceptionManager.RaiseExceptionCatched(this, ex))
                        {
                            throw ex;
                        }
                        return ex.Message;
                    }
                    if (s1.Length > 0)
                    {
                        if (double.TryParse(s1, NumberStyles.Any, null, out d))
                        {
                            string fact = ComputeFact(d.ToString());
                            ranges2[arrayList] = fact;
                            arrayList++;
                        }
                    }
                }
            }
            str = ranges2[0];
            for (int i = 1; i < ranges2.Length; i++)
                str = str + "," + ranges2[i];
            string multi = ComputeProduct(str);
            double totalFactVal = double.Parse(totalFact);
            double multiValue = double.Parse(multi);
            double multinominalVal = totalFactVal / multiValue;
            return multinominalVal.ToString();
        }

        /// <summary>
        /// Rounds the given number to a specified multiple number
        /// </summary>
        /// <param name="argList">Given number, multiple value</param>
        /// <returns>Mround value of given number</returns>
        public string ComputeMround(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 2)
                return this.FormulaErrorStrings[this.invalid_arguments];
            double x = 0, digits = 0;
            double numberstr, mround;
            string round;
            string numStr = this.GetValueFromArg(args[0]);
            string digStr = this.GetValueFromArg(args[1]);
            if (digStr == "0")
                return digStr;
            if (ComputeSign(numStr) != ComputeSign(digStr))
                return "#NUM!";
            else
            {
                if ((numStr.Length == 0 || double.TryParse(numStr, NumberStyles.Any, null, out x))
                && (digStr.Length == 0 || double.TryParse(digStr, NumberStyles.Any, null, out digits)))
                {
                    numberstr = x / digits;
                    round = ComputeRoundup(numberstr.ToString());
                    double round1 = double.Parse(round);
                    mround = round1 * digits;
                }
                else
                    return this.FormulaErrorStrings[invalid_arguments];
            }
            return mround.ToString();
        }

        /// <summary>
        /// Returns the random integer number between the given two numbers.
        /// </summary>
        /// <param name="argList">StartNumber, EndNumber</param>
        /// <returns>Random number between two values</returns>
        public string ComputeRandbetween(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 2)
                return this.FormulaErrorStrings[this.invalid_arguments];
            string arg1 = this.GetValueFromArg(args[0]);
            string arg2 = this.GetValueFromArg(args[1]);
            double bottom = double.Parse(arg1);
            double top = double.Parse(arg2);
            string number1 = ComputeRound(arg1);
            string number2 = ComputeRound(arg2);
            if (bottom > top)
                return "#NUM!";
            if (this.rand == null)
                this.rand = new Random();
            return this.rand.Next(int.Parse(number1), int.Parse(number2)).ToString();
        }
        /// <summary>
        /// Return the square root of product of given number with PI.
        /// </summary>
        /// <param name="args">number to find Sqrtpi.</param>
        /// <returns>Return Sqrtpi value of giveen number</returns>
        public string ComputeSqrtpi(string args)
        {
            double pi = 3.14159;
            double sqrtValue;
            string s1;
            string sqrtpi = string.Empty;
            string[] numList = args.Split(new char[] { ParseArgumentSeparator });
            if (numList.GetLength(0) > 1)
                return this.FormulaErrorStrings[this.invalid_arguments];
            if (args.Length > 0 && !char.IsLetter(args[0]) && args.IndexOfAny(new char[] { ParseArgumentSeparator, ':' }) == -1)
            {
                if (double.Parse(args) >= 0)
                {
                    sqrtValue = double.Parse(args) * pi;
                    sqrtpi = ComputeSqrt(sqrtValue.ToString());
                }
                else
                    return "#NUM!";
            }
            else if (args.Length > 0 && (args[0] == BMARKER || args[0] == 'u' || args[0] == 'n' || args.IndexOfAny(this.tokens) > -1))
            {
                ////parsed formula
                args = args.Replace('{', '(');
                args = args.Replace('}', ')');
                try
                {
                    s1 = this.ComputedValue(args);
                }
                catch (Exception ex)
                {
                    TraceUtil.TraceExceptionCatched(ex);
                    if (!ExceptionManager.RaiseExceptionCatched(this, ex))
                    {
                        throw ex;
                    }
                    return ex.Message;
                }
                if (double.Parse(s1) >= 0)
                {
                    sqrtValue = double.Parse(args) * pi;
                    sqrtpi = ComputeSqrt(sqrtValue.ToString());
                }
                else
                    return "#NUM!";
            }
            else
            {
                foreach (string s in this.GetCellsFromArgs(args))
                {
                    try
                    {
                        s1 = this.GetValueFromArg(s);
                    }
                    catch (Exception ex)
                    {
                        TraceUtil.TraceExceptionCatched(ex);
                        if (!ExceptionManager.RaiseExceptionCatched(this, ex))
                        {
                            throw ex;
                        }
                        return ex.Message;
                    }
                    if (s1.Length > 0)
                    {
                        if (double.Parse(s1) >= 0)
                        {
                            sqrtValue = double.Parse(s1) * pi;
                            sqrtpi = ComputeSqrt(sqrtValue.ToString());
                            break; ////Skip out after first value.
                        }
                        else
                            return "#NUM!";
                    }
                }
            }
            return sqrtpi;
        }

        /// <summary>
