        /// <summary>
        /// Returns the Double Factorial value for given number
        /// </summary>
        /// <param name="args">number to find FactDouble</param>
        /// <returns>FactDouble of given number </returns>
        public string ComputeFactdouble(string args)
        {
            double number;
            double fact = 1;
            string[] numList = args.Split(new char[] { ParseArgumentSeparator });
            if (numList.GetLength(0) > 1)
                return this.FormulaErrorStrings[this.invalid_arguments];
            if (double.TryParse(this.GetValueFromArg(args), NumberStyles.Any, null, out number)
                && number >= 0)
            {
                int x = (int)number;
                int n = x;
                if (x > 3)
                {
                    while (n > 0)
                    {
                        fact = fact * n;
                        n = n - 2;
                    }
                }
                else
                    fact = ((x == 0) ? 1 : x);
            }
            else
            {
                return this.FormulaErrorStrings[invalid_arguments];
            }
            return fact.ToString();
        }

        /// <summary>
        /// Returns the largest integer divides the numbers without any reminders.
        /// </summary>
        /// <param name="range">number1,number2,...</param>
        /// <returns>GCD value of given numbers.</returns>
        public string ComputeGcd(string range)
        {
            int arrayList = 0;
            int reminder, elements = 0;
            double number;
            string[] ranges = range.Split(new char[] { ParseArgumentSeparator });
            if (ranges.Length > 0)
            {
                foreach (string r in ranges)
                {
                    elements++;
                    if (r.IndexOf(':') > -1)
                    {
                        --elements;
                        foreach (string s in this.GetCellsFromArgs(r))
                        {
                            elements++;
                        }
                    }
                }
            }
            int[] ranges2 = new int[elements];
            foreach (string r in ranges)
            {
                ////is a cellrange
                if (r.IndexOf(':') > -1)
                {
                    foreach (string s in this.GetCellsFromArgs(r))
                    {
                        if (double.TryParse(this.GetValueFromArg(s), NumberStyles.Any, null, out number) || s.Length > 0 && (int)number > 0)
                        {
                            ranges2[arrayList] = (int)number;
                            arrayList++;
                        }
                        else
                            return "#VALUE!";
                    }
                }
                else
                {
                    if (double.TryParse(this.GetValueFromArg(r), NumberStyles.Any, null, out number) || r.Length > 0 && (int)number > 0)
                    {

                        ranges2[arrayList] = (int)number;
                        arrayList++;
                    }
                    else
                        return "#VALUE!";
                }
            }
            if (ranges2.Length == 1)
                return ranges2[0].ToString();
            for (int i = 0; i < ranges2.Length - 1; i++)
            {
                while (ranges2[1] != 0)
                {
                    reminder = ranges2[0] % ranges2[1];
                    ranges2[0] = ranges2[1];
                    ranges2[1] = reminder;
                }
                if (ranges2.Length > 2 && i < ranges2.Length - 2)
                    ranges2[1] = ranges2[i + 2];
            }
            return ranges2[0].ToString();
        }

        /// <summary>
        /// Returns the smallest positive integer that is a multiple of all given values.
        /// </summary>
        /// <param name="range">Number1,Number2,...</param>
        /// <returns>LCM value of given numbers</returns>
        public string ComputeLcm(string range)
        {
            int arrayList = 0, elements = 0;
            double number;
            string gcd, str = string.Empty;
            string[] ranges = range.Split(new char[] { ParseArgumentSeparator });
            if (ranges.Length > 0)
            {
                foreach (string r in ranges)
                {
                    elements++;
                    if (r.IndexOf(':') > -1)
                    {
                        --elements;
                        foreach (string s in this.GetCellsFromArgs(r))
                        {
                            elements++;
                        }
                    }
                }
            }
            int[] ranges2 = new int[elements];
            foreach (string r in ranges)
            {
                ////is a cellrange
                if (r.IndexOf(':') > -1)
                {
                    foreach (string s in this.GetCellsFromArgs(r))
                    {
                        if (double.TryParse(this.GetValueFromArg(s), NumberStyles.Any, null, out number) || s.Length > 0 && (int)number > 0)
                        {
                            ranges2[arrayList] = (int)number;
                            arrayList++;
                        }
                        else
                            return "#VALUE!";
                    }
                }
                else
                {
                    if (double.TryParse(this.GetValueFromArg(r), NumberStyles.Any, null, out number) || r.Length > 0 && (int)number > 0)
                    {
                        ranges2[arrayList] = (int)number;
                        arrayList++;
                    }
                    else
                        return "#VALUE!";
                }
            }
            if (ranges2.Length == 1)
                return ranges2[0].ToString();
            int multi = ranges2[0] * ranges2[1];
            str = ranges2[0].ToString() + "," + ranges2[1].ToString();
            gcd = ComputeGcd(str);
            int lcm = multi / int.Parse(gcd);
            for (int i = 2; i < ranges2.Length; i++)
            {
                multi = lcm * ranges2[i];
                str = lcm.ToString() + "," + ranges2[i].ToString();
                gcd = ComputeGcd(str);
                lcm = multi / int.Parse(gcd);
            }
            return lcm.ToString();
        }

        /// <summary>
