        /// <summary>
        /// Returns a value you specify if a formula evaluates to an error
        /// otherwise, returns the result of the formula.
        /// </summary>
        /// <param name="args">String to be tested.</param>
        public string ComputeIfError(string args)
        {
            string[] argsArray = args.Split(new char[] { ParseArgumentSeparator });
            if (argsArray.Length != 2)
                return FormulaErrorStrings[wrong_number_arguments];
            string range = argsArray[0];
            if (range.StartsWith(TIC.ToString()))
                return GetValueFromArg(argsArray[0]);
            try
            {
                if (range[0] == BMARKER)
                {
                    range = range.Replace(BMARKER, ' ');
                    range = range.Trim();
                    if (range.StartsWith("NAN")
                || range.StartsWith("-NAN")
                || range.StartsWith("INFINITY")
                || range.StartsWith("-INFINITY")
                || range.StartsWith("#")
                || range.StartsWith("n#")
                )
                        return GetValueFromArg(argsArray[1]);
                }

                range = argsArray[0];

                range = GetValueFromArg(range).ToUpper().Replace(TIC, "");
            }
            catch
            {
                range = range.ToUpper();
            }
            if (range.StartsWith("NAN")
                || range.StartsWith("-NAN")
                || range.StartsWith("INFINITY")
                || range.StartsWith("-INFINITY")
                || range.StartsWith("#")
                || range.StartsWith("n#")
                )
                return GetValueFromArg(argsArray[1]);
            else
                return GetValueFromArg(argsArray[0]);
        }

        /// <summary>
        /// Returns the string or text referred by the given value.
        /// </summary>
        /// <param name="args">value to find the refrred text - Required </param>
        /// <returns>Referred Text</returns>
        public string ComputeT(string args)
        {
            int elements = 0;
            string[] arg = SplitArguments(args, ParseArgumentSeparator);
            if (arg.Length > 0)
            {
                foreach (string r in arg)
                {
                    elements++;
                    if (r.IndexOf(':') > -1)
                    {
                        --elements;
                        foreach (string s1 in this.GetCellsFromArgs(r))
                        {
                            elements++;
                        }
                    }
                }
            }
            int argCount = arg.GetLength(0);
            if (elements > 1)
                return this.FormulaErrorStrings[wrong_number_arguments];
            string s = GetValueFromArg(args);
            string pattern = @"[a-zA-Z0-9!#$%&'()*+,/:;<=>?@\^_`{|}~-]";
            if (ComputeIsNumber(args) == "TRUE" || ComputeIsLogical(args) == "TRUE")
                return string.Empty;
            else if (Regex.IsMatch(s, pattern))
            {
                s = s.Replace(this.TIC, "");
                return s;
            }
            else
                return string.Empty;
        }
        /// <summary>
        /// Determines whether the value is even or not.
        /// </summary>
        /// <param name="args">Value to be tested.</param>
        /// <returns>True, if the value is even, false otherwise.</returns>
        public string ComputeIsEven(string args)
        {
            string cellReference = string.Empty;
            double val = 0.0;
            string[] arg = SplitArguments(args, ParseArgumentSeparator);
            int argCount = arg.GetLength(0);
            if (argCount != 1)
                return this.FormulaErrorStrings[requires_a_single_argument];
            if (!args.Equals(string.Empty))
            {
                if (args.IndexOfAny(new char[] { ParseArgumentSeparator, ':' }) != -1)
                {
                    return "#VALUE!";
                }

                this.PutTokensForSheets(ref args);
                cellReference = this.GetValueFromArg(args);
                if (double.TryParse(cellReference, NumberStyles.Any, null, out val))
                {
                    int result = (int)val;
                    if (result != 0 && result % 2 == 0)
                    {
                        return this.TRUEVALUESTR;
                    }
                    return this.FALSEVALUESTR;
                }
            }
            return this.TRUEVALUESTR;
        }

        /// <summary>
