                    }
                    return this.FALSEVALUESTR;
                }
            }
            return this.TRUEVALUESTR;
        }

        /// <summary>
        /// Returns a number converted from the provided value.
        /// </summary>
        /// <param name="args">Value to be converted.</param>
        /// <returns>A number in string format or an error string.</returns>
        public string ComputeN(string args)
        {
            string cellReference = string.Empty;
            double val = 0.0;
            DateTime date;
            string[] arg = SplitArguments(args, ParseArgumentSeparator);
            int argCount = arg.GetLength(0);
            if (argCount != 1)
                return this.FormulaErrorStrings[requires_a_single_argument];
            cellReference = this.GetValueFromArg(args);
            if (double.TryParse(cellReference, NumberStyles.Any, null, out val))
            {
                return val.ToString();
            }
            else if (DateTime.TryParse(cellReference, out date))
            {
                val = double.Parse(ComputeDatevalue(args));
            }
            else if (cellReference.Equals(this.TRUEVALUESTR))
            {
                val = 1;
            }
            else if (cellReference.Equals(this.FALSEVALUESTR))
            {
                val = 0;
            }
            return val.ToString();
        }

        

