        ///<summary>
        /// Returns a number corresponding to the predefined error values(#NULL!, #VALUE!, #REF!, #NAME?, #NUM!, #N/A, "#GETTING_DATA). Returns #N/A if not or any value enclosed within double quotes.
        ///</summary>
        public string ComputeErrorType(string args)
        {
            string cellReference = string.Empty;
            string[] arg = SplitArguments(args, ParseArgumentSeparator);
            int argCount = arg.GetLength(0);
            if (argCount != 1)
                return this.FormulaErrorStrings[requires_a_single_argument];
            if (this.IsCellReference(args))
            {
                cellReference = this.GetValueFromArg(args);
            }
            else
            {
                cellReference = args;
            }
            if (cellReference.Length > 1
                           && cellReference[0] == this.TIC[0]
                           && cellReference[cellReference.Length - 1] == this.TIC[0])
            {
                return "#N/A";
            }
            if (cellReference.Equals("#NULL!"))
                return "1";
            else if (cellReference.Equals("#DIV/0!"))
                return "2";
            else if (cellReference.Equals("#VALUE!"))
                return "3";
            else if (cellReference.Equals("#REF!"))
                return "4";
            else if (cellReference.Equals("#NAME?"))
                return "5";
            else if (cellReference.Equals("#NUM!"))
                return "6";
            else if (cellReference.Equals("#N/A"))
                return "7";
            else if (cellReference.Equals("#GETTING_DATA"))
                return "8";
            return "#N/A";
        }

        /// <summary>
        /// this function used to obtain the address of a cell in a worksheet, given specified row and column numbers
        /// </summary>
        /// <param name="argList">The argList contain the row and column postion and type of reference</param>
        /// <returns>Address of the given row and column</returns>
        public string ComputeAddress(string argList)
        {
            string[] args = SplitArguments(argList, ParseArgumentSeparator);
            int argCount = args.GetLength(0);
            string ans = string.Empty;
            long row = long.Parse(args[0]);
            long col = long.Parse(args[1]);
            string absNum = args[2];
            long temp = col;
            while (temp > 26)
            {
                long rem = temp % 26;
                temp = temp / 26;
                ans = ans + charTable[rem];
            }
            ans = ans + charTable[temp];
            char[] arr = ans.ToCharArray();
            Array.Reverse(arr);
            string ans1 = new string(arr);
            ans = '$' + ans1 + '$' + args[0];
            if (argCount > 2)
            {
                switch (args[2])
                {
                    case "":
                        break;
                    case "1":
                        break;
                    case "2":
                        ans = ans1 + '$' + args[0];
                        break;
                    case "3":
                        ans = '$' + ans1 + args[0];
                        break;
                    case "4":
                        ans = ans1 + args[0];
                        break;
                }
            }
            if (argCount > 3 && (args[3] == "FALSE" || args[3] == "0"))
            {
                switch (args[2])
                {
                    case "":
                        ans = "R" + row + "C" + col;
                        break;
                    case "1":
                        ans = "R" + row + "C" + col;
                        break;
                    case "2":
                        ans = "R" + row + "C[" + col + "]";
                        break;
                    case "3":
                        ans = "R[" + row + "]C" + col;
                        break;
                    case "4":
                        ans = "R[" + row + "]C[" + col + "]";
                        break;
                }
            }
            if ((argCount > 4 && args[4] == string.Empty))
            {
                args[4] = args[4].Replace(this.TIC, string.Empty);
                ans = args[4] + "!" + ans;
            }
            return ans;
        }

