                        {
                            return "#N/A";
                        }
                    }
                }
            }
            if (!cellValue.Contains(lookUp))
            {
                string temp = cellValue[1];
                int valCount = 0;
                for (int x = 1; x < cellValue.Count; x++)
                {
                    if ((cellValue[x].CompareTo(temp) == 1 && lookUp.CompareTo(cellValue[x]) == 1 && temp.CompareTo(lookUp) == 1) || lookUp.CompareTo(cellValue[x]) == 1)// || temp.CompareTo(cellValue[x]) ==1)// && temp.CompareTo(cellValue[x]) == 1 && cellValue[x].CompareTo(temp) !=1)
                    {
                        temp = cellValue[x];
                        valCount++;
                    }
                    else if (valCount != 0)
                        break;
                }
                if (valCount == 0)
                {
                    return "#N/A";
                }
                lookUp = temp;
            }
            int no = 0;
            int index = 0;
            if (s.Length == 3 && s[2].IndexOf(':') > -1)
            {
                for (int y = 0; y < cellValue.Count; y++)
                {
                    if (cellValue[y] == lookUp)
                    {
                        index = cellValue.IndexOf(lookUp);
                        no++;
                    }
                    else if (no != 0)
                        break;
                }

                finalResult = resultValue[index + no - 1];
            }
            else
            {
                for (int y = 0; y < cellValue.Count; y++)
                {
                    if (cellValue[y] == lookUp)
                    {
                        index = cellValue.IndexOf(lookUp);
                        no++;
                    }
                    else if (no != 0)
                        break;
                }
                finalResult = resultValue[index + no - 1];
            }
            return finalResult;

        }

        /// <summary>
        /// Returns the number of the starting position of the first string from the second string.
        /// </summary>
        /// <param name="argList">first strring, second string and starting position</param>
        /// <returns>index of the string</returns>
        public string ComputeSearch(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            int index;
            int startNum = 1;
            if (argCount != 2 && argCount != 3)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string firstStr = this.StripTics0(GetValueFromArg(args[0]));
            string secondStr = this.StripTics0(GetValueFromArg(args[1]));
            index = secondStr.IndexOf(firstStr) + 1;
            if (argCount == 3)
            {
                if (int.TryParse(GetValueFromArg(args[2]), out startNum))
                {
                    try
                    {
                        index = secondStr.IndexOf(firstStr, startNum) + 1;
                    }
                    catch
                    {
                        return "#VALUE!";
                    }
                }
            }
            if (index.Equals(0))
            {
                return "#VALUE!";
            }
            return index.ToString();
        }

        /// <summary>
        /// Returns the exclusive OR of all values treated as logical values listed in the argument.
        /// </summary>
        /// <param name="range">A string holding a list (separated by commas) of
        /// cell references,
        /// formulas, or numbers. Each item in the list is considered True if it is nonzero
        /// and False if it is zero.</param>
        /// <returns>A string holding the exclusive OR of all values listed in the argument.</returns>
        public string ComputeXor(string range)
        {
            bool sum = false;
            string s1;
            double d;

            string[] ranges = range.Split(new char[] { ParseArgumentSeparator });
            foreach (string r in ranges)
            {
                if (r.IndexOf(':') > -1 && this.IsCellReference(r))
                {
                    foreach (string s in this.GetCellsFromArgs(r))
                    {
                        try
                        {
                            s1 = this.GetValueFromArg(s);
                        }
                        catch (Exception ex)
                        {
                            return ex.Message;
                        }

                        sum ^= (s1 == this.TRUEVALUESTR) ^
                               (double.TryParse(s1, NumberStyles.Any, null, out d) && d != 0d);
                    }
                }
                else
                {
                    try
                    {
                        s1 = this.GetValueFromArg(r);
                    }
                    catch (Exception ex)
                    {
                        return ex.Message;
                    }

                    sum ^= (s1 == this.TRUEVALUESTR) ^
                               (double.TryParse(s1, NumberStyles.Any, null, out d) && d != 0d);
                }
            }
            return sum ? this.TRUEVALUESTR : FALSEVALUESTR;
        }

        /// <summary>
        /// Returns a value you specify if a formula evaluates to #N/A
        /// otherwise, returns the result of the formula.
        /// </summary>
        /// <param name="range">String to be tested.</param>
        /// <returns>Returns the computed value.</returns>
        public string ComputeIfNA(string range)
        {
            string[] args = range.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            string arg1 = string.Empty;
            double result;

            if (argCount != 2)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            if (this.ComputeIsNA(args[0]).Equals(bool.TrueString.ToUpper()))
            {
                if (!args[1].Contains(this.TIC) && !this.IsCellReference(args[1]) && !double.TryParse(args[1], out result) && !this.NamedRanges.ContainsKey(args[1]))
                {
                    return "#NUM!";
                }
                arg1 = this.GetValueFromArg(args[1]);
            }
            else
            {
                if (!args[0].Contains(this.TIC) && !this.IsCellReference(args[0]) && !double.TryParse(args[0], out result) && !this.NamedRanges.ContainsKey(args[0]))
                {
                    return "#NUM!";  
                }
                arg1 = this.GetValueFromArg(args[0]);
            }
            if (arg1.StartsWith(this.TIC) && arg1.EndsWith(this.TIC))
            {
                arg1 = arg1.Substring(1, arg1.Length - 2);
            }
            return arg1;
        }

        /// <summary>
        /// Retuns the text removing the first 32 nonprintable characters(ranging from 0 to 31) in 7-bit ASCII code.
        /// </summary>
        /// <param name="arg">Text or range holding text including nonprintable characters</param>
        /// <returns>Text without nonprintable characters(first 32)</returns>
        public string ComputeClean(string arg)
        {
            string[] args = arg.Split(new char[] { ParseArgumentSeparator });
            double result;
            if (args.Length != 1)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            if (!arg.Contains(this.TIC) && !this.IsCellReference(arg) && !double.TryParse(arg, out result) && !this.NamedRanges.ContainsKey(arg))
            {
                return "#NUM!";  // returns "#NAME?"
            }
            string cleanedArg = this.GetValueFromArg(arg);
            for (int i = 0; i <= 31; i++)
            {
                string nonPrintChar = this.ComputeChar(i.ToString());
                if (cleanedArg.Contains(nonPrintChar))
                    cleanedArg = cleanedArg.Replace(nonPrintChar, string.Empty);
            }
            if (cleanedArg.StartsWith(this.TIC) && cleanedArg.EndsWith(this.TIC))
            {
                cleanedArg = cleanedArg.Substring(1, cleanedArg.Length - 2);
            }
            return cleanedArg;
        }
        /// <summary>
        /// Returns the character whose number code is specified in the argument.
        /// </summary>
        /// <param name="arg">The number used to retrieve the character.</param>
        /// <returns>The character string.</returns>
        public string ComputeChar(string arg)
        {
            string s = this.GetValueFromArg(arg);
            int i;
            if (int.TryParse(s, out i) && i > 0 && i < 256)
            {
                return ((char)i).ToString();
            }
            return "#VALUE!";
        }
        /// <summary>
        /// Checks whether the value is a reference or not.
        /// </summary>
        /// <param name="args">value or reference</param>
        /// <returns>TRUE or FALSE</returns>
        public string ComputeIsRef(string args)
        {
            string[] arg = args.Split(new char[] { ParseArgumentSeparator });
            if (arg.Length != 1)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            return ((this.NamedRanges.ContainsKey(args) || this.IsCellReference(args)) && !args.StartsWith(this.TIC) && !args.EndsWith(this.TIC)).ToString();
        }

        /// <summary>
        /// Returns the average of all the cells in a range which is statisfy the given single criteria
        /// </summary>
        /// <param name="argList">range of cells, criteria, average_range</param>
        /// <returns>returns the average value of the cells.</returns>
        public string ComputeAverageIF(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            double cellCount = 0;
            if (argCount != 2 && argCount != 3)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            string criteriaRange = args[0];
            string criteria = args[1]; ////.Replace(TIC, string.Empty);
            if (criteria.Length < 1)
            {
                return "0";
            }

            char op = TOKEN_equal;
            if (criteria[0] != this.TIC[0] && "=><".IndexOf(criteria[0]) == -1)
            {
                ////cell reference
                criteria = this.GetValueFromArg(criteria);
            }

            int offset = (criteria.Length > 0 && criteria[0] == this.TIC[0]) ? 1 : 0;
            double compare = double.MinValue;
            if (criteria.Substring(offset).StartsWith(">="))
            {
                criteria = criteria.Substring(offset + 2, criteria.Length - 2 - 2 * offset);
                op = TOKEN_greatereq;
            }
            else if (criteria.Substring(offset).StartsWith("<="))
            {
                criteria = criteria.Substring(offset + 2, criteria.Length - 2 - 2 * offset);
                op = TOKEN_lesseq;
            }
            else if (criteria.Substring(offset).StartsWith("<>"))
            {
                criteria = criteria.Substring(offset + 2, criteria.Length - 2 - 2 * offset);
                op = TOKEN_noequal;
            }
            else if (criteria.Substring(offset).StartsWith("<"))
            {
                criteria = criteria.Substring(offset + 1, criteria.Length - 1 - 2 * offset);
                op = TOKEN_less;
            }
            else if (criteria.Substring(offset).StartsWith(">"))
            {
                criteria = criteria.Substring(offset + 1, criteria.Length - 1 - 2 * offset);
                op = TOKEN_greater;
            }
            else if (criteria.Substring(offset).StartsWith("="))
            {
                criteria = criteria.Substring(offset + 1, criteria.Length - 1 - 2 * offset);
            }

            criteria = criteria.Replace(this.TIC, string.Empty);
            bool numer = double.TryParse(criteria, out compare);

            string sumRange = (argCount == 2) ? criteriaRange : args[2];

            string[] s1 = this.GetCellsFromArgs(criteriaRange);
            string[] s2 = this.GetCellsFromArgs(sumRange);
            if (s1[0].Equals("#NUM!") || s2[0].Equals("#NUM!"))
            {
                return "#NUM!";
            }

            int count = s1.GetLength(0);

            if (count > s2.GetLength(0))
            {
                int i = sumRange.IndexOf(':');
                if (i > -1)
                {
                    int startRow = this.RowIndex(sumRange.Substring(0, i));
                    int row = this.RowIndex(sumRange.Substring(i + 1));
                    if (!(!startRow.Equals(-1) || row.Equals(-1)).Equals((startRow.Equals(-1) || !row.Equals(-1))))
                    {
                        return "#NUM!";
                    }
                    int startCol = this.ColIndex(sumRange.Substring(0, i));
                    int col = this.ColIndex(sumRange.Substring(i + 1));
                    if (startRow != row)
                    {
                        row += count - s2.GetLength(0);
                    }
                    else if (startCol != col)
                    {
                        col += count - s2.GetLength(0);
                    }
                    s2 = this.GetCellsFromArgs(sumRange);
                }
            }

            double sum = 0;

            double d;
            string s;
            switch (op)
            {
                case TOKEN_equal:
                    {
                        if (criteria.Contains("*"))
                        {
                            int index1 = criteria.IndexOf("*");
                            criteria = criteria.Substring(0, index1);
                            for (int index = 0; index < count; ++index)
                            {
                                s = this.GetValueFromArg(s1[index]); //// +criteria;

                                if (s.Replace(this.TIC, string.Empty).Substring(0, index1) == criteria)
                                {
                                    s = s2[index];
                                    s = this.GetValueFromArg(s);
                                    if (double.TryParse(s, NumberStyles.Any, null, out d))
                                    {
                                        sum += d;
                                        cellCount++;
                                    }
                                }
                            }
                        }
                        else
                            for (int index = 0; index < count; ++index)
                            {
                                s = this.GetValueFromArg(s1[index]); //// +criteria;

                                if (s.Replace(this.TIC, string.Empty) == criteria)
                                {
                                    s = s2[index];
                                    s = this.GetValueFromArg(s);
                                    if (double.TryParse(s, NumberStyles.Any, null, out d))
                                    {
                                        sum += d;
                                        cellCount++;
                                    }
                                }
                            }
                    }
                    break;
                case TOKEN_noequal:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;

                            if (s.Replace(this.TIC, string.Empty) != criteria)
                            {
                                s = s2[index];
                                s = this.GetValueFromArg(s);
                                if (double.TryParse(s, NumberStyles.Any, null, out d))
                                {
                                    sum += d;
                                    cellCount++;
                                }
                            }
                        }
                    }
                    break;
                case TOKEN_greatereq:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;
                            if (double.TryParse(s, out d))
                            {
                                if (d >= compare)
                                {
                                    s = s2[index];
                                    s = this.GetValueFromArg(s);
                                    if (double.TryParse(s, out d))
                                    {
                                        sum += d;
                                        cellCount++;
                                    }
                                }
                            }
                        }
                    }

                    break;
                case TOKEN_greater:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;
                            if (double.TryParse(s, out d))
                            {
                                if (d > compare)
                                {
                                    s = s2[index];
                                    s = this.GetValueFromArg(s);
                                    if (double.TryParse(s, NumberStyles.Any, null, out d))
                                    {
                                        sum += d;
                                        cellCount++;
                                    }
                                }
                            }
                        }
                    }

                    break;
                case TOKEN_less:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;
                            if (double.TryParse(s, out d))
                            {
                                if (d < compare)
                                {
                                    s = s2[index];
                                    s = this.GetValueFromArg(s);
                                    if (double.TryParse(s, NumberStyles.Any, null, out d))
                                    {
                                        sum += d;
                                        cellCount++;
                                    }
                                }
                            }
                        }
                    }

                    break;
                case TOKEN_lesseq:
                    {
                        for (int index = 0; index < count; ++index)
                        {
                            s = this.GetValueFromArg(s1[index]); //// +criteria;
                            if (double.TryParse(s, out d))
                            {
                                if (d <= compare)
                                {
                                    s = s2[index];
                                    s = this.GetValueFromArg(s);
                                    if (double.TryParse(s, NumberStyles.Any, null, out d))
                                    {
                                        sum += d;
                                        cellCount++;
                                    }
                                }
                            }
                        }
                    }

                    break;
                default:
                    break;
            }
            double average = sum / cellCount;
            return average.ToString();
        }
