                            }
                        }

                        break;
                    default:
                        break;
                }
            }
            double average = sum / cellCount;
            return average.ToString();
        }
        /// <summary>
        /// Returns the sum value of all cells that meet multiple criteria.
        /// </summary>
        /// <param name="argList">range of cells, criteria1, average_range1,...</param>
        /// <returns>returns the sum value of all cells.</returns>
        public string ComputeSumIFS(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            List<string> criteriaRange = new List<string>();
            List<string> criterias = new List<string>();
            for (int i = 1; i < argCount; i++)
            {
                criteriaRange.Add(args[i]);
                i++;
                criterias.Add(args[i]);
            }
            if (argCount < 3 && criteriaRange.Count == criterias.Count)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string sumRange = args[0];
            double sum = 0;
            string[] sumRangeCells = this.GetCellsFromArgs(args[0]);
            string[] s2 = this.GetCellsFromArgs(sumRange);
            bool isLastcriteria = false;
            for (int v = 0; v < criterias.Count; v++)
            {
                char op = TOKEN_equal;
                string criteria = criterias[v];
                if (criteria[0] != this.TIC[0] && "=><".IndexOf(criteria[0]) == -1)
                {
                    ////cell reference
                    criteria = this.GetValueFromArg(criteria);
                }
                if (v == criteriaRange.Count)
                {
                    isLastcriteria = true;
                }
                int offset = (criteria.Length > 0 && criteria[0] == this.TIC[0]) ? 1 : 0;
                double compare = double.MinValue;
                if (criteria.Substring(offset).StartsWith(">="))
                {
                    criteria = criteria.Substring(offset + 2, criteria.Length - 2 - 2 * offset);
                    op = TOKEN_greatereq;
                }
                else if (criteria.Substring(offset).StartsWith("<="))
                {
                    criteria = criteria.Substring(offset + 2, criteria.Length - 2 - 2 * offset);
                    op = TOKEN_lesseq;
                }
                else if (criteria.Substring(offset).StartsWith("<>"))
                {
                    criteria = criteria.Substring(offset + 2, criteria.Length - 2 - 2 * offset);
                    op = TOKEN_noequal;
                }
                else if (criteria.Substring(offset).StartsWith("<"))
                {
                    criteria = criteria.Substring(offset + 1, criteria.Length - 1 - 2 * offset);
                    op = TOKEN_less;
                }
                else if (criteria.Substring(offset).StartsWith(">"))
                {
                    criteria = criteria.Substring(offset + 1, criteria.Length - 1 - 2 * offset);
                    op = TOKEN_greater;
                }
                else if (criteria.Substring(offset).StartsWith("="))
                {
                    criteria = criteria.Substring(offset + 1, criteria.Length - 1 - 2 * offset);
                }

                criteria = criteria.Replace(this.TIC, string.Empty);
                bool numer = double.TryParse(criteria, out compare);


                string[] s1 = this.GetCellsFromArgs(criteriaRange[v]);
                if (s1[0].Equals("#NUM!") || s2[0].Equals("#NUM!"))
                {
                    return "#NUM!";
                }
                int count = s1.GetLength(0);
                if (count > s2.GetLength(0))
                {
                    int i = sumRange.IndexOf(':');
                    if (i > -1)
                    {
                        int startRow = this.RowIndex(sumRange.Substring(0, i));
                        int row = this.RowIndex(sumRange.Substring(i + 1));
                        if (!(!startRow.Equals(-1) || row.Equals(-1)).Equals((startRow.Equals(-1) || !row.Equals(-1))))
                        {
                            return "#NUM!";
                        }
                        int startCol = this.ColIndex(sumRange.Substring(0, i));
                        int col = this.ColIndex(sumRange.Substring(i + 1));
                        if (startRow != row)
                        {
                            row += count - s2.GetLength(0);
                        }
                        else if (startCol != col)
                        {
                            col += count - s2.GetLength(0);
                        }
                        s2 = this.GetCellsFromArgs(sumRange);
                    }
                }
                double d;
                string s;
                switch (op)
                {
                    case TOKEN_equal:
                        {
                            if (criteria.Contains("*"))
                            {
                                int index1 = criteria.IndexOf("*");
                                criteria = criteria.Substring(0, index1);
                                for (int index = 0; index < count; ++index)
                                {
                                    s = this.GetValueFromArg(s1[index]); //// +criteria;

                                    if (s.Replace(this.TIC, string.Empty).Substring(0, index1) == criteria)
                                    {
                                        if (s2[index] != null)
                                        {
                                            s = s2[index];
                                            s = this.GetValueFromArg(s);
                                            if (double.TryParse(s, NumberStyles.Any, null, out d) && isLastcriteria)
                                            {
                                                sum += d;
                                            }
                                        }
                                    }
                                    else
                                        s2[index] = null;
                                }
                            }
                            else
                                for (int index = 0; index < count; ++index)
                                {
                                    s = this.GetValueFromArg(s1[index]); //// +criteria;

                                    if (s.Replace(this.TIC, string.Empty) == criteria)
                                    {
                                        if (s2[index] != null)
                                        {
                                            s = s2[index];
                                            s = this.GetValueFromArg(s);
                                            if (double.TryParse(s, NumberStyles.Any, null, out d) && isLastcriteria)
                                            {
                                                sum += d;
                                            }
                                        }
                                        else
                                            s2[index] = null;
                                    }
                                }
                        }
                        break;
                    case TOKEN_noequal:
                        {
                            for (int index = 0; index < count; ++index)
                            {
                                s = this.GetValueFromArg(s1[index]); //// +criteria;

                                if (s.Replace(this.TIC, string.Empty) != criteria)
                                {
                                    if (s2[index] != null)
                                    {
                                        s = s2[index];
                                        s = this.GetValueFromArg(s);
                                        if (double.TryParse(s, NumberStyles.Any, null, out d) && isLastcriteria)
                                        {
                                            sum += d;
                                        }
                                    }
                                }
                                else
                                    s2[index] = null;
                            }
                        }
                        break;
                    case TOKEN_greatereq:
                        {
                            for (int index = 0; index < count; ++index)
                            {
                                s = this.GetValueFromArg(s1[index]); //// +criteria;
                                if (double.TryParse(s, out d))
                                {
                                    if (d >= compare)
                                    {
                                        if (s2[index] != null)
                                        {
                                            s = s2[index];
                                            s = this.GetValueFromArg(s);
                                            if (double.TryParse(s, out d) && isLastcriteria)
                                            {
                                                sum += d;
                                            }
                                        }
                                    }
                                    else
                                        s2[index] = null;
                                }
                            }
                        }

                        break;
                    case TOKEN_greater:
                        {
                            for (int index = 0; index < count; ++index)
                            {
                                s = this.GetValueFromArg(s1[index]); //// +criteria;
                                if (double.TryParse(s, out d))
                                {
                                    if (d > compare)
                                    {
                                        if (s2[index] != null)
                                        {
                                            s = s2[index];
                                            s = this.GetValueFromArg(s);
                                            if (double.TryParse(s, NumberStyles.Any, null, out d) && isLastcriteria)
                                            {
                                                sum += d;
                                            }
                                        }
                                    }
                                    else
                                        s2[index] = null;
                                }
                            }
                        }

                        break;
                    case TOKEN_less:
                        {
                            for (int index = 0; index < count; ++index)
                            {
                                s = this.GetValueFromArg(s1[index]); //// +criteria;
                                if (double.TryParse(s, out d))
                                {
                                    if (d < compare)
                                    {
                                        if (s2[index] != null)
                                        {
                                            s = s2[index];
                                            s = this.GetValueFromArg(s);
                                            if (double.TryParse(s, NumberStyles.Any, null, out d) && isLastcriteria)
                                            {
                                                sum += d;
                                            }
                                        }
                                    }
                                    else
                                        s2[index] = null;
                                }
                            }
                        }

                        break;
                    case TOKEN_lesseq:
                        {
                            for (int index = 0; index < count; ++index)
                            {
                                s = this.GetValueFromArg(s1[index]); //// +criteria;
                                if (double.TryParse(s, out d))
                                {
                                    if (d <= compare)
                                    {
                                        if (s2[index] != null)
                                        {
                                            s = s2[index];
                                            s = this.GetValueFromArg(s);
                                            if (double.TryParse(s, NumberStyles.Any, null, out d) && isLastcriteria)
                                            {
                                                sum += d;
                                            }
                                        }
                                        else
                                            s2[index] = null;
                                    }
                                }
                            }
                        }

                        break;
                    default:
                        break;
                }
            }
            return sum.ToString();
        }
        /// <summary>
        /// Returns the total number of working days between the two dates.
        /// </summary>
        /// <param name="argList"> start date, end date, number of holidays.</param>
        /// <returns>number of working days.</returns>
        public string ComputeNetworkDays(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            string adjustRange, s1;
            DateTime date;
            List<DateTime> holidays = new List<DateTime>();

            if (argCount != 2 && argCount != 3)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            string startDate = this.GetValueFromArg(args[0]).Replace(this.TIC, "");
            string endDate = this.GetValueFromArg(args[1]).Replace(this.TIC, "");
            DateTime startDateTime;
            DateTime endDateTime;
            if (!(DateTime.TryParse(startDate, out startDateTime) && DateTime.TryParse(endDate, out endDateTime)))
            {
                return "#NUM!";
            }
            if (argCount == 3)
            {
                adjustRange = args[2];
                ////is a cellrange
                if (adjustRange.IndexOf(':') > -1)
                {
                    foreach (string s in this.GetCellsFromArgs(adjustRange))
                    {
                        try
                        {
                            s1 = this.GetValueFromArg(s).Replace(this.TIC, string.Empty);
                        }
                        catch (Exception)
                        {
                            return "#VALUE!";
                        }

                        if (s1 != string.Empty)
                        {
                            if (DateTime.TryParse(s1, out date) && !holidays.Contains(date) && date.CompareTo(startDateTime) != -1 && date.CompareTo(endDateTime) != 1 && (int)date.DayOfWeek != 0 && (int)date.DayOfWeek != 6)
                            {
                                holidays.Add(date);
                            }
                        }
                    }
                }
                else
                {
                    try
                    {
                        s1 = this.GetValueFromArg(adjustRange).Replace(this.TIC, string.Empty);
                    }
                    catch (Exception)
                    {
                        return "#VALUE!";
                    }

                    if (s1.Length > 0)
                    {
                        if (DateTime.TryParse(s1, out date) && !holidays.Contains(date) && date.CompareTo(startDateTime) != -1 && date.CompareTo(endDateTime) != 1 && (int)date.DayOfWeek != 0 && (int)date.DayOfWeek != 6)
                        {
                            holidays.Add(date);
                        }
                    }
                }
            }

            int numberOfWorkingDays = 0;

            int noofDays = int.Parse(this.ComputeDatevalue(endDate)) - int.Parse(this.ComputeDatevalue(startDate));

            int startWeekDay = (int)startDateTime.DayOfWeek;
            int endWeekDay = (int)endDateTime.DayOfWeek;
            int excesStartDays = startWeekDay - 1;
            int excesEndDays = 7 - endWeekDay;
            noofDays = noofDays + excesStartDays + excesEndDays;

            int noofholidays = (noofDays / 7) * 2;

            numberOfWorkingDays = noofDays - excesStartDays - excesEndDays - noofholidays + 1 - holidays.Count;
            return numberOfWorkingDays.ToString();
        }

        /// <summary>
        /// Replace the part of the text with a new text from orginal text
        /// </summary>
        /// <param name="argList">Text,Start index, Number of char to replace, new text </param>
        /// <returns>replaced string</returns>
        public string ComputeReplace(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            int startIndex = 0, noOfChar = 0;
            if (argCount != 4)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string firstText = this.StripTics0(GetValueFromArg(args[0]));
            string newText = this.StripTics0(GetValueFromArg(args[3]));
            string resultText = string.Empty;
            if (int.TryParse(GetValueFromArg(args[1]), out startIndex) && int.TryParse(GetValueFromArg(args[2]), out noOfChar))
            {
                try
                {
                    string replaceText = string.Empty;
                    if (string.IsNullOrEmpty(firstText))
                    {
                        return newText;
                    }
                    if (firstText.Length <= startIndex && startIndex > noOfChar)
                    {
                        resultText = firstText + newText;
                    }
                    else if (firstText.Length <= startIndex)
                    {
                        replaceText = firstText;
                        resultText = firstText.Replace(replaceText, newText);
                    }
                    else
                    {
                        if (noOfChar == firstText.Length)
                            return newText;
                        replaceText = firstText.Substring(startIndex, noOfChar);
                        resultText = firstText.Replace(replaceText, newText);
                    }
                }
                catch (Exception)
                {
                    return this.ErrorStrings[1].ToString();
                }
            }
            if(string.IsNullOrEmpty(firstText) || string.IsNullOrEmpty(args[1]))
                return this.ErrorStrings[1].ToString();
            return resultText;
        }

