        /// <summary>
        /// Returns the number of repeated text
        /// </summary>
        /// <param name="argList">text, repeated count</param>
        /// <returns>text</returns>
        public string ComputeRept(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string text = this.StripTics0(GetValueFromArg(args[0]));
            double repeatTime = 1;
            string value = GetValueFromArg(args[1].Replace(this.TIC, string.Empty));
            if (string.IsNullOrEmpty(text) || string.IsNullOrEmpty(value) || value.Equals("invalid expression") || this.ErrorStrings.Contains(value))
            {
                return string.Empty;
            }
            if (!double.TryParse(value, out repeatTime))
            {
                return this.ErrorStrings[5].ToString();
            }
            StringBuilder outputString = new StringBuilder();
            for (int i = 0; i < repeatTime; i++)
            {
                outputString.Append(text);
            }
            return outputString.ToString();
        }

