        /// <summary>
        /// Returns the interger value for the datatype of given text
        /// </summary>
        /// <param name="argList">text</param>
        /// <returns>integer value</returns>
        public string ComputeType(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            int result = 0;

            if (argCount != 1)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string text = GetValueFromArg(args[0]);
            if (string.IsNullOrEmpty(text))
            {
                return this.ErrorStrings[1].ToString();
            }
            else if (argList.IndexOf(ParseArgumentSeparator) > -1)
            {
                result = 64;
            }
            else if (ComputeIsNumber(text) == TRUEVALUESTR)
            {
                result = 1;
            }
            else if (ComputeIsLogical(text) == TRUEVALUESTR)
            {
                result = 4;
            }
            else if (text.Equals("invalid expression") || this.ErrorStrings.Contains(text))
            {
                result = 16;
            }
            else if (ComputeIsText(text) == TRUEVALUESTR)
            {
                result = 2;
            }
            return result.ToString();
        }

