        public string ComputeSearchB(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            int index;
            int startNum = 1;
            if (argCount != 2 && argCount != 3)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            CultureInfo ci = CultureInfo.CurrentCulture;
            string firstStr = this.StripTics0(GetValueFromArg(args[0]));
            string secondStr = this.StripTics0(GetValueFromArg(args[1]));
            index = secondStr.IndexOf(firstStr) + 1;
            if (argCount == 3)
            {
                if (int.TryParse(GetValueFromArg(args[2]), out startNum))
                {
                    try
                    {
                        index = secondStr.IndexOf(firstStr, startNum) + 1;
                    }
                    catch
