            }
            if (!this.IsCellReference(cellReference) && !this.NamedRanges.ContainsKey(cellReference) && sheetFamiliesList.Contains(cellReference))
            {
                return this.ErrorStrings[0].ToString();
            }
            GridSheetFamilyItem family = GetSheetFamilyItem(this.grid);
            string sheet1 = family.SheetNameToGridModel[cellReference].ToString(); // this.SheetToken(cell);
            int sheetNumber = 0;
            if (string.IsNullOrEmpty(sheet1) && !family.SheetNameToGridModel.Contains(cellReference) && !cellReference.Contains(sheetToken.ToString()))
            {
                sheetNumber = sheetFamilyID + 1;
            }
            else if (sheet1.Length > 0)
            {
                sheetNumber = int.Parse(sheet1.Replace(sheetToken.ToString(), string.Empty)) + 1;
            }
            else
            {
                try
                {
                    foreach (DictionaryEntry griddata in family.TokenToSheetName)
                    {
                        if (family.SheetNameToGridModel[cellReference].Equals(griddata.Value))
                        {
                            sheetNumber = sheetFamilyID + 1;
                            break;
                        }
                    }
                }
                catch (Exception)
                {
                    return this.ErrorStrings[2].ToString();
                }
            }
            return sheetNumber.ToString();
        }

