        /// </summary>
        /// <param name="arg">Contains one argument - reference</param>
        /// <returns>number of columns.</returns>
        public string ComputeMdeterm(string arg)
        {
            if (!this.IsCellReference(arg) && !this.NamedRanges.ContainsKey(arg) && !arg.Contains(";"))
            {
                return this.FormulaErrorStrings[invalid_arguments];
            }
            string[] args = arg.Split(new char[] { ParseArgumentSeparator });
            if (args.Length != 1)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            if (!this.IsCellReference(arg) && !this.NamedRanges.ContainsKey(arg) && !arg.Contains(";"))
            {
                return this.ErrorStrings[1].ToString();
            }
            double det = 0;
            if (arg.IndexOf(':') > -1)
            {
                string[] cells = this.GetCellsFromArgs(arg);
                int i, j, rows, cols;
                int incr = 0;
                rows = int.Parse(this.ComputeRows(arg));
                cols = int.Parse(this.ComputeColumns(arg));
                if (rows != cols)
                {
                    return this.ErrorStrings[1].ToString();
                }
                int n = rows;
                double[,] a = new double[rows, cols];
                for (i = 0; i < n; i++)
                {
                    for (j = 0; j < n; j++)
                    {
                        a[i, j] = double.Parse(this.GetValueFromArg(cells[incr]));
                        incr++;
                    }
                }

                det = this.determinant(a, rows);
            }
            else if (arg.IndexOf(';') > -1)
            {
                string[] arrayArg = SplitArguments(arg.Replace(this.TIC, ""), ';');
                int col = arrayArg[0].Split(new char[] { ParseArgumentSeparator }).Length;
                if (arrayArg.Length != col)
                {
                    return this.ErrorStrings[1].ToString();
                }
                double[,] matrix = new double[arrayArg.Length, col];
                int length1 = col, length2 = 0;
                for (int i = 0; i < arrayArg.Length; i++)
                {
                    string[] arrayValue = arrayArg[i].Split(new char[] { ParseArgumentSeparator });
                    length2 = arrayValue.Length;
                    if (length1 != length2)
                    {
                        return this.FormulaErrorStrings[wrong_number_arguments];
                    }
                    for (int v = 0; v < length1; v++)
                    {
                        matrix[i, v] = double.Parse(this.GetValueFromArg(arrayValue[v]));
                    }
                }

                det = this.determinant(matrix, arrayArg.Length);
            }
            return det.ToString();
        }

        /// <summary>
        /// Used to find the determinant internally for matrix function
        /// </summary>
        /// <param name="a">double array</param>
        /// <param name="n">number</param>
        /// <returns>double value</returns>
        private double determinant(double[,] a, int n)
        {
            double res = 0;
            if (n == 1)
                res = a[0, 0];
            // Trivial 2x2 matrix
            else if (n == 2)
                res = a[0, 0] * a[1, 1] - a[1, 0] * a[0, 1];
            // NxN matrix
            else
            {
                res = 0;
                for (int j1 = 0; j1 < n; j1++)
                {
                    double[,] m = generateSubArray(a, n, j1);
                    res += Math.Pow(-1.0, 1.0 + j1 + 1.0) * a[0, j1] * determinant(m, n - 1);
                }
            }
            return res;
        }

        /// <summary>
        /// A method to get submatrix for matrix function used internally.
        /// </summary>
        /// <param name="a">double Array -  Matrix</param>
        /// <param name="N">Matix rows</param>
        /// <param name="j1">Columns</param>
        /// <returns>Matrix</returns>
        private double[,] generateSubArray(double[,] a, int N, int j1)
        {
            double[,] m = new double[N - 1, 3];
            //for (int k=0; k<N-1; k++)
            //        m[k] = new double[N-1];

            for (int i = 1; i < N; i++)
            {
                int j2 = 0;
                for (int j = 0; j < N; j++)
                {
                    if (j == j1)
                        continue;
                    m[i - 1, j2] = a[i, j];
                    j2++;
                }
            }
            return m;
        }

        /// <summary>
        /// Returns the number of columns of the passed in cell reference.
        /// </summary>
        /// <param name="arg">Contains one argument - reference</param>
        /// <returns>number of columns.</returns>
        public string ComputeMmult(string arg)
        {
            string[] args = arg.Split(new char[] { ParseArgumentSeparator });
            if (args.Length != 2)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            if (!this.IsCellReference(args[0]) && !this.IsCellReference(args[1]))
            {
                return this.FormulaErrorStrings[invalid_arguments];
            }

            string[] cellA = this.GetCellsFromArgs(args[0]);
            string[] cellB = this.GetCellsFromArgs(args[1]);
            int i, j, k, rowsA, colsA, rowsB, colsB;
            int incr = 0;
            rowsA = int.Parse(this.ComputeRows(args[0]));
            colsA = int.Parse(this.ComputeColumns(args[0]));
            rowsB = int.Parse(this.ComputeRows(args[1]));
            colsB = int.Parse(this.ComputeColumns(args[1]));
            if (rowsA != rowsB && colsA != colsB)
            {
                return this.ErrorStrings[0].ToString();
            }
            int n = rowsA - 1;
            double[,] a = new double[rowsA, colsA];
            double[,] b = new double[rowsA, colsA];
            double[,] c = new double[rowsA, colsA];
            for (i = 0; i <= n; i++)
            {
                for (j = 0; j <= n; j++)
                {
                    a[i, j] = double.Parse(this.GetValueFromArg(cellA[incr]));
                    incr++;
                }
            }
            incr = 0;
            for (i = 0; i <= n; i++)
            {
                for (j = 0; j <= n; j++)
                {
                    b[i, j] = double.Parse(this.GetValueFromArg(cellB[incr]));
                    incr++;
                }
            }
            for (i = 0; i <= n; i++)
            {
                for (j = 0; j <= n; j++)
                {
                    for (k = 0; k <= n; k++)
                    {
                        c[i, j] += a[i, k] * b[k, j];
                    }
                }
            }
            return c[0, 0].ToString();
        }

