        /// <summary>
        /// Retrun the inverse matrix as ref
        /// </summary>
        /// <param name="A">double array</param>
        /// <param name="invA">inverse array</param>
        /// <returns>inverse matrix</returns>
        internal Boolean InvertMatrix(double[,] A, out double[,] invA)
        {
            Boolean bNotIllConditioned = true;
            if (A.GetLength(0) != A.GetLength(1))
            {
                invA = A; // Have to assign something to invA before returning
                return false;
            }
            int dimension = A.GetLength(0);
            double[,] working = (double[,])A.Clone();
            double[,] inverse = new double[dimension, dimension];
            for (int loop = 0; loop < dimension; loop++) inverse[loop, loop] = 1.0;
            for (int loop = 0; loop < dimension; loop++) // for each row
            {
                int currentRow = loop;
                double biggestSoFar = 0.0; int biggestRow = currentRow;
                for (int x = currentRow; x < dimension; x++)
                {
                    double sizeOfThis = working[x, currentRow];
                    if (sizeOfThis > biggestSoFar)
                    {
                        biggestSoFar = sizeOfThis;
                        biggestRow = x;
                    }
                }
                if (biggestRow != currentRow)
                {
                    double temp;
                    for (int lop = currentRow; lop < dimension; lop++)
                    {
                        temp = working[currentRow, lop];
                        working[currentRow, lop] = working[biggestRow, lop];
                        working[biggestRow, lop] = temp;
                    }
                    for (int lop = 0; lop < dimension; lop++)
                    {
                        temp = inverse[currentRow, lop];
                        inverse[currentRow, lop] = inverse[biggestRow, lop];
                        inverse[biggestRow, lop] = temp;
                    }
                }
                for (int lop = currentRow + 1; lop < dimension; lop++)
                {
                    // Matrix might be ill-conditioned.  I should check:
                    if (working[currentRow, currentRow] == 0)
                    {
                        bNotIllConditioned = false;
                        working[currentRow, currentRow] = 1e-60;
                    }
                    double factor = working[lop, currentRow] / working[currentRow, currentRow];

                    if (factor != 0.0)
                    {
                        for (int lp = currentRow; lp < dimension; lp++)
                            working[lop, lp] -= factor * working[currentRow, lp];
                        for (int lp = 0; lp < dimension; lp++)
                            inverse[lop, lp] -= factor * inverse[currentRow, lp];
                    }
                }
            }
            for (int loop = dimension - 1; loop >= 0; loop--) // for each row
            {
                int currentRow = loop;
                if (working[currentRow, currentRow] == 0)
                {
                    bNotIllConditioned = false;
                    working[currentRow, currentRow] = 1e-60;
                }
                for (int lop = currentRow - 1; lop >= 0; lop--)
                {
                    double factor = working[lop, currentRow] / working[currentRow, currentRow];
                    working[lop, currentRow] = 0.0;
                    if (factor != 0.0)
                    {
                        for (int lp = 0; lp < dimension; lp++)
                        {
                            inverse[lop, lp] -= factor * inverse[currentRow, lp];
                        }
                    }
                }
            }
            for (int loop = 0; loop < dimension; loop++)
            {
                double scale = working[loop, loop];
                for (int lop = 0; lop < dimension; lop++) inverse[loop, lop] /= scale;
            }
            invA = inverse;
            return bNotIllConditioned;
        }

        /// Returns the number of columns of the passed in cell reference.
        /// </summary>
        /// <param name="arg">Contains one argument - reference</param>
        /// <returns>number of columns.</returns>
        public string ComputeMUnit(string arg)
        {
            string[] args = arg.Split(new char[] { ParseArgumentSeparator });
            if (args.Length != 1)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            int dim = int.Parse(GetValueFromArg(args[0].Replace(this.TIC, "")));
            double[,] a = new double[dim, dim];
            for (int i = 0; i < dim; i++)
            {
                for (int j = 0; j < dim; j++)
                {
                    if (i == j)
                        a[i, j] = 1;
                    else
                        a[i, j] = 0;
                }
            }
            return a[0, 0].ToString();
        }

        public string ComputeBase(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount < 2 || argCount > 3)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            int number = 0, radix = 0, length = 1;
            try
            {
                number = int.Parse(this.GetValueFromArg(args[0]).Replace(this.TIC, ""));
                radix = int.Parse(this.GetValueFromArg(args[1]).Replace(this.TIC, ""));
                length = (argCount == 3) ? int.Parse(this.GetValueFromArg(args[2]).Replace(this.TIC, "")) : 1;
            }
            catch (Exception)
            {
                return this.ErrorStrings[1].ToString();
            }
            const int BitsInLong = 64;
            const string Digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";

            if (radix < 2 || radix > Digits.Length)
            {
                return this.ErrorStrings[1].ToString();
            }

            if (number == 0)
                return "0";

            int index = BitsInLong - 1;
            long currentNumber = Math.Abs(number);
            char[] charArray = new char[BitsInLong];

            while (currentNumber != 0)
            {
                int remainder = (int)(currentNumber % radix);
                charArray[index--] = Digits[remainder];
                currentNumber = currentNumber / radix;
            }

            string result = new String(charArray, index + 1, BitsInLong - index - 1);
            StringBuilder outputString = new StringBuilder();
            for (int i = 0; i < length - result.Length; i++)
            {
                outputString.Append("0");
            }
            result = outputString.ToString() + result;
            if (number < 0)
            {
                result = "-" + result;
            }
            return result.ToString();
        }

        /// <summary>
        /// Returns the decimal number of the given text to the given base.
        /// </summary>
        /// <param name="argList">text,base</param>
        /// <returns>Decimal number.</returns>
        public string ComputeDecimal(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount > 3)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            const string Base64 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz+/";
            if (!this.GetValueFromArg(args[0]).Contains(this.TIC) && !this.IsCellReference(args[0]))
            {
                return this.ErrorStrings[1].ToString();
            }
            string strValue; int radix = 0;
            try
            {
                strValue = this.GetValueFromArg(args[0]).Replace(this.TIC, "");
                radix = int.Parse(this.GetValueFromArg(args[1]).Replace(this.TIC, ""));
            }
            catch (Exception )
            {
                return this.ErrorStrings[1].ToString();
            }
            int result;
            if (radix < 2 || radix > Base64.Length)
            {
                return this.ErrorStrings[4].ToString();
            }
            strValue = strValue.Trim();
            if (radix <= 36)
                strValue = strValue.ToUpper();
            int pos = 0;
            result = 0;
            // Use lookup table to parse string
            while (pos < strValue.Length && !Char.IsWhiteSpace(strValue[pos]))
            {
                string digit = strValue.Substring(pos, 1);
                int i = Base64.IndexOf(digit);
                if (i >= 0 && i < radix)
                {
                    result *= radix;
                    result += i;
                    pos++;
                }
                else
                {
                    return this.ErrorStrings[4].ToString();
                }
            }
            return result.ToString();
        }

        public string ComputeIntrat(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            List<DateTime> holidays = new List<DateTime>();

            if (argCount > 5)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            string startDate = this.GetValueFromArg(args[0]).Replace(this.TIC, "");
            string endDate = this.GetValueFromArg(args[1]).Replace(this.TIC, "");
            string basis = (argCount == 5) ? this.GetValueFromArg(args[4]).Replace(this.TIC, "") : "0";
            DateTime startDateTime;
            DateTime endDateTime;
            int basisValue;
            double investment, redemption;
            string invest = this.GetValueFromArg(args[2]).Replace(this.TIC, "");
            string redem = this.GetValueFromArg(args[3]).Replace(this.TIC, "");
            if (!(DateTime.TryParse(startDate, out startDateTime) && DateTime.TryParse(endDate, out endDateTime) && int.TryParse(basis, out basisValue) && double.TryParse(invest, out investment) && double.TryParse(redem, out redemption)))
            {
                return this.ErrorStrings[1].ToString();
            }
            double dim = double.Parse(this.ComputeDatevalue(endDate)) - double.Parse(this.ComputeDatevalue(startDate));
            if ((basisValue > 4 && basisValue < 0) && dim < 1)
            {
                return this.ErrorStrings[4].ToString();
            }

            double intrate = (redemption - investment) / (investment * dim);

            switch (basisValue)
            {
                case 0:
                    intrate = intrate * 360;
                    break;
                case 1:
                    intrate = intrate * 366;
                    break;
                case 2:
                    intrate = intrate * 360;
                    break;
                case 3:
                    intrate = intrate * 365;
                    break;
                case 4:
                    intrate = intrate * 360;
                    break;
                default:
                    {
                        return this.ErrorStrings[4].ToString();
                    }
            }
            return intrate.ToString();
        }

        public string ComputeSeriessum(string arg)
        {
            string[] args = arg.Split(new char[] { ParseArgumentSeparator });
            if (args.Length != 4)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            double xValue = 0, nValue = 0, mValue = 0, coeff = 0, result = 0;
            string[] arrayArg;
            if (args[3].IndexOf(';') > -1)
            {
                arrayArg = SplitArguments(args[3].Replace(this.TIC, ""), ';');
            }
            else
            {
                arrayArg = GetCellsFromArgs(args[3].Replace(this.TIC, ""));
            }
            if (!(double.TryParse(GetValueFromArg(args[0].Replace(this.TIC, "")), out xValue) && double.TryParse(GetValueFromArg(args[1].Replace(this.TIC, "")), out nValue) && double.TryParse(GetValueFromArg(args[2].Replace(this.TIC, "")), out mValue)))
            {
                return this.ErrorStrings[1].ToString();
            }
            for (int i = 0; i < arrayArg.Length; i++)
            {
                if (double.TryParse(GetValueFromArg(arrayArg[i].Replace(this.TIC, "")), out coeff))
                {
                    result = result + (coeff * Math.Pow(xValue, (nValue + (i * mValue))));
                }
                else
                {
                    return this.ErrorStrings[1].ToString();
                }
            }
            return result.ToString();
        }

        /// <summary>
        /// Returns the Arabic value of Raman numeric
        /// </summary>
        /// <param name="arg"></param>
        /// <returns></returns>
        public string ComputeArabic(string arg)
        {
            string[] args = arg.Split(new char[] { ParseArgumentSeparator });
            if (args.Length != 1)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string text = GetValueFromArg(args[0]).Replace(this.TIC, "").ToUpper();
            if (!GetValueFromArg(args[0]).Contains(this.TIC) && string.IsNullOrEmpty(text))
            {
                return this.ErrorStrings[5].ToString();
            }
            int i = 0;
            string ch = null;
            long result = 0;
            long new_value = 0;
            long old_value = 0;
            old_value = 1000;
            for (i = 1; i <= text.Length; i++)
            {
                // See what the next character is worth.
                ch = text.Substring(i - 1, 1);
                switch (ch)
                {
                    case "I":
                        new_value = 1;
                        break;
                    case "V":
                        new_value = 5;
                        break;
                    case "X":
                        new_value = 10;
                        break;
                    case "L":
                        new_value = 50;
                        break;
                    case "C":
                        new_value = 100;
                        break;
                    case "D":
                        new_value = 500;
                        break;
                    case "M":
                        new_value = 1000;
                        break;
                    default:
                        {
                            return this.ErrorStrings[1].ToString();
                        }
                }
                // See if this character is bigger
                // than the previous one.
                if (new_value > old_value)
                {
                    // The new value > the previous one.
                    // Add this value to the result
                    // and subtract the previous one twice.
                    result = result + new_value - 2 * old_value;
                }
                else
                {
                    // The new value <= the previous one.
                    // Add it to the result.
                    result = result + new_value;
                }
                old_value = new_value;
            }
            return result.ToString();
        }

        /// <summary>
        /// Returns the RoundUp of the given number to the given significance
        /// </summary>
        /// <param name="args">Number, significance, mode</param>
        /// <returns>RoundUp number</returns>
        public string ComputeCeilingMath(string args)
        {
            string[] range = args.Split(new char[] { ParseArgumentSeparator });
            int argCount = range.GetLength(0);
            if (argCount > 3 && argCount < 1)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string number = this.GetValueFromArg(range[0]).Replace(this.TIC, "");
            string sign = (argCount > 1) ? this.GetValueFromArg(range[1]).Replace(this.TIC, "") : "1";
            string mode = (argCount == 3) ? this.GetValueFromArg(range[2]).Replace(this.TIC, "") : "1";
            double d1, d2 = 0, d3 = 0, result;
            if (GetValueFromArg(range[0]).Contains(this.TIC) && string.IsNullOrEmpty(number))
            {

                return "0";
            }
            if (!(double.TryParse(number, out d1) && double.TryParse(sign, out d2) && double.TryParse(mode, out d3)))
            {
                return "#VALUE!";
            }
            if (d1 < 0 && d3 < 0)
            {
                d2 = -1;
            }
            result = double.Parse(ComputeCeiling(d1.ToString() + ParseArgumentSeparator + d2.ToString()));
            return result.ToString();
        }

        public static bool TryParse(string s, int radix, string digits, out int result)
        {
            // Validate radix
            if (radix < 2 || radix > digits.Length)
                throw new ArgumentException();

            // Normalize input
            s = s.Trim();

            // If selected radix does not utilize both upper and lower case letters,
            // then convert to upper case so that parsing is not case sensitive
            if (radix <= 36)
                s = s.ToUpper();
            int pos = 0;
            result = 0;

            // Use lookup table to parse string
            while (pos < s.Length && !Char.IsWhiteSpace(s[pos]))
            {
                string digit = s.Substring(pos, 1);
                int i = digits.IndexOf(digit);
                if (i >= 0 && i < radix)
                {
                    result *= radix;
                    result += i;
                    pos++;
                }
                else
                {
                    // Invalid character encountered
                    return false;
                }
            }
            // Return true if any characters processed
            return (pos > 0);
        }

        /// <summary>
        /// Returns the week number of a specific date
        /// </summary>
        /// <param name="argList">serial_number,start_day of week (optional)</param>
        /// 1 or omitted - Sunday 
        /// 2 Monday 
        /// 11 Monday 
        /// 12 Tuesday 
        /// 13 Wednesday 
        /// 14 Thursday 
        /// 15 Friday  
        /// 16 Saturday 
        /// 17 Sunday 
        /// 21 Monday 
        /// <returns>returns the week number</returns>
        public string ComputeWeeknum(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount > 2)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string weekDate = this.GetValueFromArg(args[0]).Replace(this.TIC, "");
            if (weekDate.Equals("invalid expression"))
            {
                return this.ErrorStrings[1].ToString();
            }
            DateTime weekDateTime, firstDate = this.dateTime1900; ;
            if (!(DateTime.TryParse(weekDate, out weekDateTime)))
            {
                try
                {
                    int weeknumber = int.Parse(weekDate);
                    return ((weeknumber / 7) + 1).ToString();
                }
                catch (Exception)
                {
                    return this.ErrorStrings[4].ToString();
                }
            }
            ArrayList weekStart = new ArrayList();
            weekStart.AddRange(new string[] 
            {
            "","0","1","","","","","","","","","1","2","3","4","5","6","0","","","","1"
        });
            int weektype = 0;
            if (!(argCount == 2 && int.TryParse(GetValueFromArg(args[1]), out weektype)))
            {
                weektype = 1;
            }
            int weehStartValue = int.Parse(weekStart[weektype].ToString());
            firstDate = new DateTime(weekDateTime.Year, 1, 1);
            int firstDay = firstDate.Day;
            int offset = (firstDay < weehStartValue) ? weehStartValue - firstDay + 1 : firstDay - weehStartValue;
            TimeSpan ts = new TimeSpan(offset, 0, 0, 0);
            DateTime dt = firstDate.Subtract(ts);
            double noofDays = double.Parse(this.ComputeDatevalue(weekDate)) - double.Parse(this.ComputeDatevalue(dt.ToString()));
            double dval = Math.Floor(noofDays / 7) + 1 + weehStartValue;

            return dval.ToString();
        }
