        /// <summary>
        /// Returns the number of days between two dates.
        /// </summary>
        /// <param name="argList">startDate, endDate</param>
        /// <returns>Returns the number of days</returns>
        public string ComputeDays(string argList)
        {
            string argument = argList;
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string startDate = this.GetValueFromArg(args[0]).Replace(this.TIC, "");
            string endDate = this.GetValueFromArg(args[1]).Replace(this.TIC, "");
            DateTime startDateTime;
            DateTime endDateTime;
            if (!(DateTime.TryParse(startDate, out startDateTime) && DateTime.TryParse(endDate, out endDateTime)))
            {
                try
                {
                    double ed = double.Parse(startDate);
                    double st = double.Parse(endDate);
                    double x = ed - st;
                    return Math.Round((x - .4999999999d * Math.Sign(x))).ToString();
                }
                catch (Exception)
                {
                     return this.ErrorStrings[1].ToString();
                }
            }
            int noofDays = int.Parse(this.ComputeDatevalue(startDate)) - int.Parse(this.ComputeDatevalue(endDate));
            return noofDays.ToString();
        }

