        /// <summary>
        /// Returns the serial number of the given date before or after a specified number of workdays
        /// </summary>
        /// <param name="argList">startDate, days, weekend (optional) , holidays (optional)</param>
        /// <returns>return the serial number of specific date.</returns>
        public string ComputeWorkDayintl(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            string adjustRange, s1;
            DateTime date;
            List<DateTime> holidays = new List<DateTime>();
            if (argCount != 2 && argCount > 4)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string startDate = this.GetValueFromArg(args[0]).Replace(this.TIC, "");
            DateTime startDateTime;
            double temp = 0;
            if (!(DateTime.TryParse(startDate, out startDateTime) && double.TryParse(this.GetValueFromArg(args[1]).Replace(this.TIC, ""), out temp)))
            {
                try
                {
                    double first = double.Parse(startDate);
                    return ((int)(first + temp)).ToString();
                }
                catch (Exception)
                {
                    return this.ErrorStrings[1].ToString();
                }
            }
            int totalDays = (int)temp;
            if (argCount == 4)
            {
                adjustRange = args[3];
                ////is a cellrange
                if (adjustRange.IndexOf(':') > -1 || adjustRange.IndexOf(',') > -1)
                {
                    foreach (string s in this.GetCellsFromArgs(adjustRange))
                    {
                        try
                        {
                            s1 = this.GetValueFromArg(s).Replace(this.TIC, string.Empty);
                        }
                        catch (Exception ex)
                        {
                            return ex.Message;
                        }

                        if (s1 != string.Empty)
                        {
                            if (DateTime.TryParse(s1, out date) && !holidays.Contains(date) && date.CompareTo(startDateTime) != -1)
                            {
                                holidays.Add(date);
                            }
                        }
                    }
                }
                else
                {
                    try
                    {
                        s1 = this.GetValueFromArg(adjustRange).Replace(this.TIC, string.Empty);
                    }
                    catch (Exception ex)
                    {
                        return ex.Message;
                    }

                    if (s1.Length > 0)
                    {
                        if (DateTime.TryParse(s1, out date) && !holidays.Contains(date) && date.CompareTo(startDateTime) != -1)
                        {
                            holidays.Add(date);
                        }
                    }
                }
            }
            int weekend = -1;
            if (!(argCount > 2 && int.TryParse(args[2], out weekend)))
            {
                weekend = 1;
            }
            if (weekend == 0)
            {
                return this.ErrorStrings[4].ToString();
            }
            ArrayList weekendDays = new ArrayList();
            weekendDays.AddRange(SplitArguments(WeekEndType[weekend].ToString(), ','));
            int j = 0;
            DateTime tempStartDate = startDateTime;
            while (j < totalDays)
            {
                tempStartDate = tempStartDate.AddDays(1);
                int dayofweek = (int)tempStartDate.DayOfWeek;
                if (weekendDays.IndexOf(dayofweek.ToString()) < 0 && holidays.IndexOf(tempStartDate) < 0)
                {
                    j++;
                }
            }
          return ComputeDatevalue(tempStartDate.ToShortDateString());
        }

