        /// <summary>
        /// Finds the first occurrence of one string in another string.
        /// </summary>
        /// <param name="arg">Conatins two or three arguments. The first argument is the string
        /// to find. The second string is the string that is being searched. The third argument
        /// is the start location in the second string for the search.</param>
        /// <returns>The location of the found string.</returns>
        public string ComputeFindB(string arg)
        {
            string[] args = arg.Split(new char[] { ParseArgumentSeparator });
            if (args.Length != 2 && args.Length != 3)
            {
                return this.FormulaErrorStrings[invalid_arguments];
            }
            ////strip off outside tics (if any) on the evaluated arguments
            string lookFor = this.StripTics0(GetValueFromArg(args[0]));
            string lookIn = this.StripTics0(GetValueFromArg(args[1]));
            int start = 1;
            if (args.Length == 3)
            {
                string s3 = this.GetValueFromArg(args[2]);
                if (!int.TryParse(s3, out start))
                {
                    start = 1;
                }
            }
            if (start <= 0 || start > lookIn.Length)
            {
                return this.ErrorStrings[1].ToString();
            }

            int loc = lookIn.IndexOf(lookFor, start - 1);
            if (loc < 0)
            {
                return this.ErrorStrings[1].ToString();
            }

            return (loc + 1).ToString();
        }

