            char[] dbcChr = firstStr.ToCharArray();
            for (int i = 0; i < dbcChr.Length; i++)
            {
                if (dbcChr[i] == 32)
                {
                    dbcChr[i] = (char)12288;
                    continue;
                }
                if (dbcChr[i] < 127)
                    dbcChr[i] = (char)(dbcChr[i] + 65248);
            }
            strReturn = new string(dbcChr);
            return strReturn;
        }

        /// <summary>
        /// replaces part of a text string, based on the number of characters, with a different text string
        /// </summary>
        /// <param name="argList">Text in which is want to replace, The position of the character in old_text., The number of characters in old_text </param>
        /// <returns>returns replaced text</returns>
        public string ComputeReplaceB(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            int startIndex = 0, noOfChar = 0;
            if (argCount != 4)
            {
                return this.FormulaErrorStrings[invalid_arguments];
            }
            string firstText = this.StripTics0(GetValueFromArg(args[0]));
            string newText = this.StripTics0(GetValueFromArg(args[3]));
            string resultText = string.Empty;
            if (int.TryParse(GetValueFromArg(args[1]), out startIndex) && int.TryParse(GetValueFromArg(args[2]), out noOfChar))
            {
                try
                {
                    string replaceText = firstText.Substring(startIndex, noOfChar);
                    resultText = firstText.Replace(resultText, newText);
                }
                catch (Exception)
                {
                    return this.ErrorStrings[1].ToString();
                }
            }
            return resultText;
        }

        private bool Daysfeb29(DateTime sDate, DateTime eDate)
        {
            DateTime sDateFeb = new DateTime(sDate.Year, 2, 1);
            DateTime eDateFeb = new DateTime(eDate.Year, 2, 1);
            int sDateDiff_1 = int.Parse(this.ComputeDatevalue(sDate.ToShortDateString())) - int.Parse(this.ComputeDatevalue(sDateFeb.ToShortDateString()));
            int eDateDiff_1 = int.Parse(this.ComputeDatevalue(eDate.ToShortDateString())) - int.Parse(this.ComputeDatevalue(sDateFeb.ToShortDateString()));

            int sDateDiff_2 = int.Parse(this.ComputeDatevalue(sDate.ToShortDateString())) - int.Parse(this.ComputeDatevalue(eDateFeb.ToShortDateString()));
            int eDateDiff_2 = int.Parse(this.ComputeDatevalue(eDate.ToShortDateString())) - int.Parse(this.ComputeDatevalue(eDateFeb.ToShortDateString()));

            if (DateTime.IsLeapYear(sDate.Year) && sDateDiff_1 < 0 && eDateDiff_1 >= 0)
                return true;
            if (DateTime.IsLeapYear(eDate.Year) && sDateDiff_2 < 0 && eDateDiff_2 >= 0)
                return true;
            return false;
        }

