        /// <summary>
        /// Returns the current operation environment information
        /// </summary>
        /// <param name="argList">Type</param>
        /// <returns>environment information</returns>
        public string ComputeInfo(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 1)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string firstStr = this.StripTics0(GetValueFromArg(args[0])).ToLower();
            string result = string.Empty;
            switch (firstStr)
            {
                case "directory":
                    result = System.Environment.CurrentDirectory;
                    break;
                case "numfile":
                        result = "1";
                    break;
                case "origin":
                    string cell = this.RowIndex(this.cell).ToString() + ParseArgumentSeparator + this.ColIndex(this.cell).ToString();
                    result = "$A: " + ComputeAddress(cell);
                    break;
                case "osversion":
                    result = System.Environment.OSVersion.ToString();
                    break;
                case "recalc":
                    if (SuspendRefresh)
                        result = "Automatic";
                    else
                        result = "Manual";
                    break;
                case "release":
                    result = System.Reflection.Assembly.GetExecutingAssembly().GetName().Version.ToString();
                    break;
                case "system":
                    switch (Environment.OSVersion.Platform)
                    {
                        case PlatformID.Unix:
                            result = "unix";
                            break;
                        case PlatformID.MacOSX:
                            result = "mac";
                            break;
                        default:
                            result = "pcdos";
                            break;
                    }
                    break;
                default:
                    return this.ErrorStrings[1].ToString();
            }
            return result;
        }

        /// <summary>
        /// Returns the row index of the passed in cell reference.
        /// </summary>
        /// <param name="arg">Contains zero or one argument. If no argument is passed, returns the row index of the
        /// location of this Row function cell, otherwise returns the row index of the passed in cell reference.</param>
        /// <returns>The row index.</returns>
        /// <remarks>
        /// This method doesn't return an array of row numbers as the array formula entry is not supported in engine. It is another usecase of this library function.
        /// </remarks>
        public string ComputeRow(string arg)
        {
            string[] args = arg.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 1)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            if (string.IsNullOrEmpty(args[0]))
            {
                return this.RowIndex(this.cell).ToString();
            }

            if (!this.IsCellReference(args[0]) && !this.NamedRanges.ContainsKey(args[0]))
            {
                return this.FormulaErrorStrings[invalid_arguments];
            }
            if (arg.IndexOf(':') > -1)
