        /// <summary>
        /// Returns the number of rows of the passed in cell reference.
        /// </summary>
        /// <param name="arg">Contains one argument.</param>
        /// <returns>number of rows.</returns>
        public string ComputeRows(string arg)
        {
            if (!this.IsCellReference(arg) && !this.NamedRanges.ContainsKey(arg) && !arg.Contains(";"))
            {
                return this.FormulaErrorStrings[invalid_arguments];
            }
            string[] args = arg.Split(new char[] { ParseArgumentSeparator });
            if (args.Length != 1)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            int firstRow, LastRow, totalRows = 1;
            if (arg.IndexOf(':') > -1)
            {
                string[] cells = this.GetCellsFromArgs(arg);
                firstRow = this.RowIndex(cells[0].ToString());
                LastRow = this.RowIndex(cells[cells.Length - 1].ToString());
                totalRows = LastRow - firstRow + 1;
                totalRows = (totalRows > 0) ? totalRows : 1;
            }
            else if (arg.IndexOf(';') > -1)
            {
                string[] arrayArg = SplitArguments(arg.Replace(this.TIC, ""), ';');
                for (int i = 1; i < arrayArg.Length; i++)
                {
                    if (arrayArg[i - 1].Split(new char[] { ParseArgumentSeparator }).Length != arrayArg[1].Split(new char[] { ParseArgumentSeparator }).Length)
                    {
                        return this.FormulaErrorStrings[wrong_number_arguments];
                    }
                    totalRows = arrayArg.Length;
                }
            }
            return totalRows.ToString();
        }

