                firstCol = this.ColIndex(cells[0].ToString());
                LastCol = this.ColIndex(cells[cells.Length - 1].ToString());
                totalCols = LastCol - firstCol + 1;
                totalCols = (totalCols > 0) ? totalCols : 1;
