        /// <summary>
        /// Returns the area of the passed in cell reference range
        /// </summary>
        /// <param name="arg">Contains one argument - reference</param>
        /// <returns>area of the passed in cell reference.</returns>
        public string ComputeAreas(string arg)
        {
            if (arg.Contains(" "))
            {
                arg = arg.Substring(0, arg.IndexOf(" "));
            }
            if (!this.IsCellReference(arg) && !this.NamedRanges.ContainsKey(arg) && !arg.Contains(")"))
            {
                return this.FormulaErrorStrings[invalid_arguments];
            }

            string[] args1 = SplitArguments(arg, ')');
            if (args1.Length > 2)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string argument = args1[0].Replace("(", string.Empty);
            argument = argument.Replace(")", string.Empty);
            string[] args = argument.Split(new char[] { ParseArgumentSeparator });
            for (int i = 0; i < args.Length; i++)
            {
                if (!this.IsCellReference(args[i]) && !this.NamedRanges.ContainsKey(args[i]))
                {
                    return this.FormulaErrorStrings[invalid_arguments];
                }
            }
            return args.Length.ToString();
        }

        public string ComputeCell(string arg)
        {
            string[] args = arg.Split(new char[] { ParseArgumentSeparator });
            if (args.Length >= 2)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string reference = "";
            if (args.Length == 2)
            {
                if (!this.IsCellReference(arg) && !this.NamedRanges.ContainsKey(arg))
                {
                    return this.FormulaErrorStrings[invalid_arguments];
                }
                reference = args[1];
            }
            else
            {
                reference = this.cell;
            }
            string type = args[0].Replace(this.TIC, string.Empty).ToLower(), result = "";
            switch (type)
            {
                case "address":
                    result = this.RowIndex(reference).ToString() + ParseArgumentSeparator + this.ColIndex(reference).ToString();
                    result = ComputeAddress(result);
                    break;
                case "col":
                    result = ComputeColumns(reference);
                    break;
                case "color":
                    break;
                case "contents":
                    result = GetValueFromArg(reference);
                    break;
                case "filename":
                    result = System.Diagnostics.Process.GetCurrentProcess().MainModule.FileName;
                    break;
                case "format":
                    break;
                case "parentheses":
                    break;
                case "prefix":
                    break;
                case "protect":
                    break;
                case "row":
                    result = ComputeRow(reference);
                    break;
                case "type":
                    if (ComputeIsBlank(reference) == TRUEVALUESTR)
                        result = "b";
                    else if (ComputeIsText(reference) == TRUEVALUESTR)
                        result = "l";
                    else
                        result = "v";
                    break;
                case "width":
                    break;
                default:
                    break;
            }
            return result.ToString();
        }


