        /// <summary>
        /// Returns the secant of an angle.
        /// </summary>
        /// <param name="argList"> A cell reference, or number.</param>
        /// <returns>A string conaining the secant of an angle</returns>
        public string ComputeSecant(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            argList = this.GetValueFromArg(argList);
            int argCount = args.GetLength(0);
            if (argCount != 1)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
