        public string ComputeConfidenceT(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double alpha;
            double s;
            double sz;
            double val = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out alpha)
                && double.TryParse(args[1], NumberStyles.Any, null, out s)
                && double.TryParse(args[2], NumberStyles.Any, null, out sz))
            {

                val = this.normalinv(1 - alpha + alpha / 2, 0, 1);
                val = val * s / Math.Sqrt(sz);
            }
            return val.ToString();
        }

        /// <summary>
        /// Returns the skewness of a distribution based on a population a characterization of the degree of asymmetry of a distribution around its mean.
        /// </summary>
        /// <param name="range"> numbers or names, arrays, or reference that contain numbers</param>
        /// <returns>Skewness of a distribution.</returns>
        public string ComputeSkewP(string range)
        {
            double[] x = this.GetDoubleArray(range);
            int n = x.GetLength(0);

            if (n < 3)
            {
                return this.FormulaErrorStrings[this.invalid_arguments];
            }

            double xbar = 0;
            double sdev = this.sd(x, out xbar);
            double skew = 0;
            for (int i = 0; i < n; ++i)
            {
                skew += Math.Pow((x[i] - xbar) / sdev, 3);
            }
            return (n * skew / (n - 1) / (n - 2)).ToString();
        }

        /// <summary>
        /// Returns population covariance, the average of the products of deviations for each data point pair in two data sets. 
        /// </summary>
        /// <param name="range">range1, range2.</param>
        /// <returns>The covarianceP</returns>
        public string ComputeCovarianceP(string range)
        {
            string[] args = range.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            double[] y = this.GetDoubleArray(args[0]);
            double[] x = this.GetDoubleArray(args[1]);
            if (y.GetLength(0) == 1 && x.GetLength(0) == 1)
            {
                return this.ErrorStrings[3].ToString();//#Div/0!
            }
            int n = x.GetLength(0);
            if (n <= 0 || n != y.GetLength(0))
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            double mean1 = Mean(y);
            double mean2 = Mean(x);
            double result = 0;
            int ns = y.Length;
            for (int i = 0; i < n; i++)
            {
                result += (y[i] - mean1) * (x[i] - mean2);
            }
            return (result / ns).ToString();
        }
        /// <summary>
        /// Returns the sample covariance, the average of the products of deviations for each data point pair in two data sets.
        /// </summary>
        /// <param name="range">range1, range2.</param>
        /// <returns>The covariances</returns>
        public string ComputeCovarianceS(string range)
        {
            string[] args = range.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double[] y = this.GetDoubleArray(args[0]);
            double[] x = this.GetDoubleArray(args[1]);
            int n = x.GetLength(0);

            if (n <= 0 || n != y.GetLength(0))
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double sumx = 0;
            double sumy = 0;
            for (int i = 0; i < n; ++i)
            {
                sumx += x[i];
                sumy += y[i];
            }

            sumx = sumx / n;
            sumy = sumy / n;

            double sumxy = 0;

            for (int i = 0; i < n; ++i)
            {
                sumxy += (x[i] - sumx) * (y[i] - sumy);
            }
            return Covariance(y, x).ToString();//(sumxy / n).ToString();
        }

        /// <summary>
        /// Returns the sample covariance between two arrays.
        /// Arrays should be of equal length, and contain more than one element.
        /// </summary>
        /// <param name="array1"></param>
        /// <param name="array2"></param>
        private double Covariance(double[] array1, double[] array2)
        {
            if (array1.Length != array2.Length)
                throw new ArgumentException("Arrays must be the same length");

            int n = array1.Length;
            if (n == 1) return double.NaN;
            double m1 = Mean(array1);
            double m2 = Mean(array2);


            double covar = 0.0;
            for (int i = 0; i < n; i++)
                covar += (array1[i] - m1) * (array2[i] - m2);
            covar /= (n - 1);
            return covar;
        }

        /// <summary>
        /// Returns the sample covariance between two arrays.
        /// Arrays should be of equal length, and contain more than one element.
        /// </summary>
        /// <param name="array1"></param>
        /// <param name="array2"></param>
        /// <param name="decayFactor">In most applications, the decay factor is between 0 and 1.  Weigth on the last element in arrays is 1.0, the 2nd to last element d, 3rd to last d^2, ...</param>
        public double Covariance(double[] array1, double[] array2, double decayFactor)
        {
            if (array1.Length != array2.Length)
                throw new ArgumentException("Arrays must be the same length");

            int n = array1.Length;
            if (n == 1) return double.NaN;
            double covar = 0.0;
            double d = 1.0;
            for (int i = 0; i < n; i++)
            {
                covar += d * array1[n - 1 - i] * array2[n - 1 - i];
                d *= decayFactor;
            }

            double m1 = Mean(array1, decayFactor);
            double m2 = Mean(array2, decayFactor);
            double S1 = SumOfGeometricSeries(decayFactor, n);
            double S2 = SumOfGeometricSeries(decayFactor * decayFactor, n);
            double A = S1 / (S1 * S1 - S2);
            double B = S1 * A;
            covar = A * covar - B * m1 * m2;
            return covar;
        }

        #region Mean

        /// <summary>
        /// Returns the sum of a geometric series of length n, who's first element is 1.
        /// For decay factor d, S = 1 + d + d^2 + ... + d^(n-1)
        /// </summary>
        /// <param name="decayFactor">Decay factor Typically between -1 adn +1.</param>
        /// <param name="length">Number of elements in the geometric series, must be positive.</param>
        /// <returns></returns>
        public static double SumOfGeometricSeries(double decayFactor, int length)
        {
            if (length < 1) return double.NaN;
            if (decayFactor == 1.0) return length;
            return (1.0 - Math.Pow(decayFactor, length)) / (1.0 - decayFactor);
        }

        /// <summary>
        /// Returns the inverse of the sum of a geometric series of length n, who's first element is 1.
        /// For decay factor d, S = 1 + d + d^2 + ... + d^(n-1). Return 1/S.
        /// </summary>
        /// <param name="decayFactor">Decay factor Typically between -1 adn +1.</param>
        /// <param name="length">Number of elements in the geometric series, must be positive.</param>
        /// <returns></returns>
        public static double InverseSumOfGeometricSeries(double decayFactor, int length)
        {
            if (length < 1) return double.NaN;
            if (decayFactor == 1.0) return 1.0 / length;
            return (1.0 - decayFactor) / (1.0 - Math.Pow(decayFactor, length));
        }

        /// <summary>
        /// Returns the sum of an infinite geometric series who's first element is 1.
        /// For decay factor d, S = 1 + d + d^2 + ...
        /// </summary>
        /// <param name="decayFactor">Decay factor. Typically between -1 adn +1.</param>
        /// <returns></returns>
        public static double SumOfInfiniteGeometricSeries(double decayFactor)
        {
            if (decayFactor >= 1) return double.PositiveInfinity;
            if (decayFactor <= 1) return double.NaN;
            return 1.0 / (1.0 - decayFactor);
        }

        /// <summary>
        /// Returns the half-life of a geometric series of length n, who's first element is 1.
        /// For decay factor d,  1 + d + d^2 + ... + d^(h-1) = 0.5 * [1 + d + d^2 + ... + d^(n-1)]
        /// </summary>
        /// <param name="decayFactor">Decay factor Typically between -1 adn +1.</param>
        /// <param name="length">Number of elements in the geometric series, must be positive.</param>
        /// <returns></returns>
        public static double HalfLifeOfGeometricSeries(double decayFactor, int length)
        {
            if (length < 1) return double.NaN;
            return Math.Log(0.5 + 0.5 * Math.Pow(decayFactor, length)) / Math.Log(decayFactor);
        }

        /// <summary>
        /// Returns the mean of an array.
        /// </summary>
        /// <param name="array">Array of data for which we are calculating the mean.</param>
        public double Mean(double[] array)
        {
            return Mean(array, 1.0);
        }

        /// <summary>
        /// Returns the most recent points from an array (the points with the highest index values).
        /// For functions with a decay factor, the weight on the last element in the array is the highest.
        /// In many applications this corresponds with the assumption that the last element in the array represents the most recent data point.
        /// </summary>
        /// <param name="inArray">Array from which the data points will be selected.</param>
        /// <param name="length">The number of data points to be returned.</param>
        /// <returns></returns>
        public static double[] MostRecentValues(double[] inArray, int length)
        {
            if (inArray.Length == length) return inArray;

            if (inArray.Length < length)
                throw new ArgumentException("length of inArray must be greater than or equal to length");

            double[] outArray = new double[length];
            Array.Copy(inArray, outArray, length);
            return outArray;
        }


        /// <summary>
        /// Returns the mean of an array.
        /// </summary>
        /// <param name="array">Array of data for which we are calculating the mean.  For time series, the last element (index = n-1), is the most recent.</param>
        /// <param name="decayFactor">In most applications, the decay factor is between 0 and 1.  Weigth on the last element in array is 1.0, the 2nd to last element d, 3rd to last d^2, ...</param>
        public static double Mean(double[] array, double decayFactor)
        {
            int n = array.Length;
            double m = 0.0;
            double d = 1.0;
            for (int i = 0; i < n; i++)
            {
                m += d * array[n - 1 - i];
                d *= decayFactor;
            }

            m *= InverseSumOfGeometricSeries(decayFactor, n);
            return m;
        }

        /// <summary>
        /// Returns the mean of an array.
        /// </summary>
        /// <param name="array">Array of data for which we are calculating the mean.  For time series, the last element (index = n-1), is the most recent.</param>
        /// <param name="decayFactor">In most applications, the decay factor is between 0 and 1.  Weigth on the last element in array is 1.0, the 2nd to last element d, 3rd to last d^2, ...</param>
        /// <param name="length">Window length. Method uses the most recent n points, n = length.</param>
        public double Mean(double[] array, double decayFactor, int length)
        {
            double[] subArray = MostRecentValues(array, length);
            return Mean(subArray, decayFactor);
        }

        /// <summary>
        /// Returns the weighted averages of the values in valueArray using the corresponding weights in weightArray.
        /// </summary>
        /// <param name="valueArray">array of values for which we are computing the weighted average</param>
        /// <param name="weightArray">array of weights used in computing the weighted average</param>
        public double WeightedMean(double[] valueArray, double[] weightArray)
        {
            if (valueArray.Length != weightArray.Length)
                throw new ArgumentException("valueArray and weightArray must have the same number of elements");
            double m = 0, s = 0;
            for (int i = 0; i < valueArray.Length; i++)
            {
                m += valueArray[i] * weightArray[i];
                s += weightArray[i];
            }
            m /= s;

            return m;
        }
