        private double sdP(double[] x, out double xbar)
        {
            int n = x.GetLength(0);
            xbar = 0;
            for (int i = 0; i < n; ++i)
            {
                xbar += x[i];
            }

            xbar = xbar / n;
            double sumx2 = 0;
            double d = 0;

            for (int i = 0; i < n; ++i)
            {
                d = x[i] - xbar;
                sumx2 += d * d;
            }

            return Math.Sqrt(sumx2 / n);
        }
        /// <summary>
        /// Returns the sample standard deviation.
        /// </summary>
        /// <param name="range">A string holding a list (separated by commas) of
        /// cell references,
        /// formulas, or numbers.
        /// </param>
        /// <returns>The sample standard deviation.</returns>
        /// <remarks>Treats True as 1; False as 0.
        /// </remarks>
        public string ComputeStdevaP(string range)
        {
            double[] dd = this.GetDoubleArrayA(range);
            int n = dd.GetLength(0);

            if (n < 2)
            {
                return this.FormulaErrorStrings[this.invalid_arguments];
            }
            return this.StdevdotP(dd).ToString();
        }

        private double StdevdotP(double[] range)
        {
            int n = range.GetLength(0);
            double mean = 0;
            double sigma = 0;
            int count = 0;

            for (int i = 0; i < n; ++i)
                mean += range[i];
            mean = mean / n;
            for (int i = 0; i < n; i++)
            {
                sigma += Math.Pow(range[i] - mean, 2);
                count++;
            }

            return Math.Sqrt(sigma / count);
        }
        /// <summary>
        /// Returns the sample standard deviation.
