        /// <summary>
        /// Returns the normal distribution for the specified mean and standard deviation. 
        /// </summary>
        /// <param name="argList">x, mean, standarddev, cumulative.</param>
        /// <returns>The normal distribution.</returns>
        /// <remarks>
        /// Cumulative should be either
        /// True if you want to return the value of the distribution function or False
        /// if you want to return the value of the density function. 
        /// </remarks>
        public string ComputeNormOdist(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 4)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double u;
            double s;
            double cum = 0;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out x)
                && double.TryParse(args[1], NumberStyles.Any, null, out u)
                && double.TryParse(args[2], NumberStyles.Any, null, out s))
            {
                if (argCount != 3)
                {
                    cum = (args[3] == this.TRUEVALUESTR) ? 1 : 0;
                    double check = 0;
                    if (double.TryParse(args[3], NumberStyles.Any, null, out check))
                        cum = 1;
                }

                if (cum == 0)
                {
                    dist = this.NormalProbabilityDensity(x, u, s);
                }
                else
                {
                    dist = this.normaldist(x, u, s);
                }
            }
            return dist.ToString();
        }

        #region Normal Distribution
        /// <summary>
        /// Returns the Probabilitydistribution of the normal distribution.
        /// </summary>
        /// <param name="x">Value at which the distribution is evaluated.</param>
        /// <param name="mean">Mean of the distribution.</param>
        /// <param name="standardDeviation">Standard deviation of the distribution.</param>
        private double NormalProbabilityDensity(double x, double mean, double standardDeviation)
        {
            const double sqrtTwoPiInv = 0.398942280401433;
            double z = (x - mean) / standardDeviation;
            return sqrtTwoPiInv * Math.Exp(-0.5 * z * z) / standardDeviation;
        }

        /// <summary>
        /// Returns the CDF of the normal distribution.
        /// </summary>
        /// <param name="x">Value at which the distribution is evaluated.</param>
        /// <param name="mean">Mean of the distribution.</param>
        /// <param name="standardDeviation">Standard deviation of the distribution.</param>
        private double NormalCumulativeDistribution(double x, double mean, double standardDeviation)
        {
            double z = (x - mean) / standardDeviation;
            return StandardNormalCumulativeDistribution(z);
        }

        /// <summary>
        /// Returns the inverse of the CDF of the normal distribution.
        /// </summary>
        /// <param name="p">Cumulative probability of the distribution. 0 &lt;= p &gt;= 1.</param>
        ///<param name="mean">Mean of the distribution.</param>
        /// <param name="standardDeviation">Standard deviation of the distribution.</param>
        private double NormalCumulativeDistributionFunctionInverse(double p, double mean, double standardDeviation)
        {
            double x = StandardNormalCumulativeDistributionInverse(p);
            return standardDeviation * x + mean;
        }

        /// <summary>
        /// Returns the PDF of the standard normal distribution.
        /// </summary>
        /// <param name="x">Value at which the distribution is evaluated.</param>
        private double StandardNormalProbabilityDensityFunction(double x)
        {
            const double SqrtTwoPiInv = 0.398942280401433;
            return SqrtTwoPiInv * Math.Exp(-0.5 * x * x);
        }

        /// <summary>
        /// Returns the CDF of the standard normal distribution.
        /// </summary>
        /// <param name="x">Value at which the distribution is evaluated.</param>
        public double StandardNormalCumulativeDistribution(double x)
        {
            //Approimation based on Abramowitz & Stegun (1964)

            if (x < 0)
                return 1.0 - StandardNormalCumulativeDistribution(-x);
            const double b0 = 0.2316419;
            const double b1 = 0.319381530;
            const double b2 = -0.356563782;
            const double b3 = 1.781477937;
            const double b4 = -1.821255978;
            const double b5 = 1.330274429;
            double pdf = StandardNormalProbabilityDensityFunction(x);
            double a = 1.0 / (1.0 + b0 * x);
            return 1.0 - pdf * (b1 * a + b2 * Math.Pow(a, 2) + b3 * Math.Pow(a, 3) + b4 * Math.Pow(a, 4) + b5 * Math.Pow(a, 5));
        }

        #endregion

        /// <summary>
        /// Returns the inverse of the normal cumulative distribution for the specified mean and standard deviation.
        /// </summary>
        /// <param name="argList">P, mean, standard deviation.</param>
        /// <returns>Returns x such that normal distribution at x is p.</returns>
        /// <remarks>
        /// P should be between 0 and 1.
        /// </remarks>
        public string ComputeNormOinv(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double p;
            double u;
            double s;
            double invdist = 0;

            for (int i = 0; i < argCount; ++i)
                args[i] = this.GetValueFromArg(args[i]).Replace(this.TIC, string.Empty);

            if (double.TryParse(args[0], NumberStyles.Any, null, out p)
                && double.TryParse(args[1], NumberStyles.Any, null, out u)
                && double.TryParse(args[2], NumberStyles.Any, null, out s))
            {
                if (p >= 0 && p <= 0 || s <= 0)
                {
                    return this.ErrorStrings[4].ToString();
                }
                invdist = this.NormalCumulativeDistributionFunctionInverse(p, u, s);//this.normalinv(p, u, s);
            }

            if (invdist <= 0)
            {
                return this.FormulaErrorStrings[iterations_dont_converge];
            }
            return invdist.ToString();
        }


