        /// Returns the standard normal cumulative distribution function. The distribution has a mean of 0 (zero) and a standard deviation of one.
        /// <para>Syntax: NORMSDIST(z)</para>
        /// </summary>
        /// <param name="argList">Z is the value for which you want the distribution.</param>
        /// <returns>Standard normal cumulative distribution.</returns>
        public string ComputeNormOsODist(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 1 && argCount != 2)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double cum = 0;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]).Replace(this.TIC, string.Empty);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out x))
            {
                if (argCount == 2)
                {
                    cum = (args[1] == this.TRUEVALUESTR) ? 1 : 0;
                    double check = 0;
                    if (double.TryParse(args[1], NumberStyles.Any, null, out check))
                        cum = 1;
                }

                if (cum == 0)
                {
                    dist = this.StandardNormalProbabilityDensity(x);
                }
                else
                {
                    dist = this.StandardNormalCumulativeDistributionFunction(x);
                }
            }
            else
            {
                return this.ErrorStrings[1].ToString();
            }
            return dist.ToString();
        }

        /// <summary>
        /// Returns the PDF of the standard normal distribution.
        /// </summary>
        /// <param name="x">Value at which the distribution is evaluated.</param>
        public double StandardNormalProbabilityDensity(double x)
        {
            const double SqrtTwoPiInv = 0.398942280401433;
            return SqrtTwoPiInv * Math.Exp(-0.5 * x * x);
        }

        /// <summary>
        /// Returns the CDF of the standard normal distribution.
        /// </summary>
        /// <param name="x">Value at which the distribution is evaluated.</param>
        public double StandardNormalCumulativeDistributionFunction(double x)
        {
            if (x < 0)
                return 1.0 - StandardNormalCumulativeDistributionFunction(-x);
            const double b0 = 0.2316419;
            const double b1 = 0.319381530;
            const double b2 = -0.356563782;
            const double b3 = 1.781477937;
            const double b4 = -1.821255978;
            const double b5 = 1.330274429;
            double pdf = StandardNormalProbabilityDensityFunction(x);
            double a = 1.0 / (1.0 + b0 * x);
            return 1.0 - pdf * (b1 * a + b2 * Math.Pow(a, 2) + b3 * Math.Pow(a, 3) + b4 * Math.Pow(a, 4) + b5 * Math.Pow(a, 5));
        }


        /// <summary>
        /// Returns the inverse of the standard normal cumulative distribution. The distribution has a mean of zero and a standard deviation of one.
        /// <para>Syntax: NORMSINV(p)</para>
        /// </summary>
        /// <param name="argList">p is a probability corresponding to the normal distribution.</param>
        /// <returns>Inverse of standard normal cumulative distribution.</returns>
        /// <remarks>
        /// p should be between 0 and 1.
        /// </remarks>
        public string ComputeNormOsOInv(string argList)
        {

            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 1)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]).Replace(this.TIC, string.Empty);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out x))
            {
                if (x <= 0 || x >= 1)
                {
                    return this.ErrorStrings[4].ToString();
                }
                dist = StandardNormalCumulativeDistributionFunctionInverse(x);
            }
            else
            {
                return this.ErrorStrings[1].ToString();
            }
            return dist.ToString();
        }

        /// <summary>
        /// Returns the inverse of the CDF of the standard normal distribution.
        /// </summary>
        /// <param name="p">Cumulative probability of the distribution. p is between 0 and 1.</param>
        public double StandardNormalCumulativeDistributionFunctionInverse(double p)
        {

            if (p < 0 || p > 1.0) throw new System.ArgumentException("Probability must be between 0 and 1");
            if (p == 0) return double.NegativeInfinity;
            if (p == 1) return double.PositiveInfinity;
            if (p == 0.5) return 0.0;

            const double a1 = -3.969683028665376e+01;
            const double a2 = 2.209460984245205e+02;
            const double a3 = -2.759285104469687e+02;
            const double a4 = 1.383577518672690e+02;
            const double a5 = -3.066479806614716e+01;
            const double a6 = 2.506628277459239e+00;

            const double b1 = -5.447609879822406e+01;
            const double b2 = 1.615858368580409e+02;
            const double b3 = -1.556989798598866e+02;
            const double b4 = 6.680131188771972e+01;
            const double b5 = -1.328068155288572e+01;

            const double c1 = -7.784894002430293e-03;
            const double c2 = -3.223964580411365e-01;
            const double c3 = -2.400758277161838e+00;
            const double c4 = -2.549732539343734e+00;
            const double c5 = 4.374664141464968e+00;
            const double c6 = 2.938163982698783e+00;

            const double d1 = 7.784695709041462e-03;
            const double d2 = 3.224671290700398e-01;
            const double d3 = 2.445134137142996e+00;
            const double d4 = 3.754408661907416e+00;

            const double pLow = 0.02425;
            const double pHigh = 1 - pLow;

            double q, x;
            if (0 < p && p < pLow)
            {
                q = Math.Sqrt(-2 * Math.Log(p));
                x = (((((c1 * q + c2) * q + c3) * q + c4) * q + c5) * q + c6) / ((((d1 * q + d2) * q + d3) * q + d4) * q + 1);
                return x;
            }

            if (pLow <= p && p <= pHigh)
            {
                q = p - 0.5;
                double r = q * q;
                x = (((((a1 * r + a2) * r + a3) * r + a4) * r + a5) * r + a6) * q / (((((b1 * r + b2) * r + b3) * r + b4) * r + b5) * r + 1);
                return x;
            }

            //if(p_high < p && p < 1)
            q = Math.Sqrt(-2 * Math.Log(1 - p));
            x = -(((((c1 * q + c2) * q + c3) * q + c4) * q + c5) * q + c6) / ((((d1 * q + d2) * q + d3) * q + d4) * q + 1);
            return x;
        }

        /// <summary>
        /// Calculates the Weibull Probability Density Function or the Weibull Cumulative Distribution Function for a supplied set of parameters.
        /// </summary>
        /// <param name="argList">x, alpha, beta, cumulative.</param>
        /// <returns>Returns the calculated weibull distribution.</returns>
        /// <remarks>
        /// cumulative =  A logical argument which denotes the type of distribution to be used
        /// TRUE	   =  Weibull Cumulative Distribution Function
        /// FALSE	   =  Weibull Probability Density Function
        /// </remarks>
        public string ComputeWeiBullODist(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);

            if (argCount != 4)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double alpha;
            double beta;
            double cumulative = 0;
            bool cumBool = true;

            for (int i = 0; i < argCount; ++i)
                args[i] = this.GetValueFromArg(args[i]).Replace(this.TIC, string.Empty);

            if (double.TryParse(args[0], NumberStyles.Any, null, out x)
                && double.TryParse(args[1], NumberStyles.Any, null, out alpha)
                && double.TryParse(args[2], NumberStyles.Any, null, out beta))
            {
                if (x < 0 || alpha <= 0 || beta <= 0)
                {
                    return this.errorStrings[4].ToString();
                }
                if (alpha.ToString().Length >= 5 && beta.ToString().Length >= 3)
                {
                    return this.errorStrings[4].ToString();
                }
                if (argCount != 3)
                {
                    cumulative = (args[3] == this.TRUEVALUESTR) ? 1 : 0;
                    double check = 0;
                    if (double.TryParse(args[3], NumberStyles.Any, null, out check))
                        cumulative = 1;
                }

                cumBool = (cumulative == 1) ? true : false;
                cumulative = ((cumBool) ? 1 - Math.Exp(-Math.Pow(x / beta, alpha)) : Math.Pow(x, alpha - 1) * Math.Exp(-Math.Pow(x / beta, alpha)) * alpha / Math.Pow(beta, alpha));
            }
            else
            {
                return this.errorStrings[1].ToString();
            }
            return cumulative.ToString();
        }

        /// <summary>
        /// Returns the exponential distribution.
        /// </summary>
        /// <param name="argList">x, lambda, cumulative.</param>
        /// <returns>The exponential distribution.</returns>
        /// <remarks>
        /// Cumulative should be either
        /// True if you want to return the value of the distribution function or False
        /// if you want to return the value of the density function.
        /// </remarks>
        public string ComputeExponODist(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);

            if (argCount != 3)
            {
                return this.errorStrings[4].ToString();
            }

            double x;
            double lambda;
            double cum = 0;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
                args[i] = this.GetValueFromArg(args[i]).Replace(this.TIC, string.Empty);

            if (double.TryParse(args[0], NumberStyles.Any, null, out x) && double.TryParse(args[1], NumberStyles.Any, null, out lambda))
            {
                if (x < 0 || lambda <= 0)
                {
                    return this.errorStrings[4].ToString();
                }
                cum = (args[2] == this.TRUEVALUESTR) ? 1 : 0;
                double check = 0;
                if (double.TryParse(args[2], NumberStyles.Any, null, out check))
                    cum = 0;
                if (cum == 0)
                    dist = lambda * Math.Exp(-lambda * x);
                else
                    dist = 1 - Math.Exp(-lambda * x);
            }
            else
            {
                return this.errorStrings[1].ToString();
            }
            return dist.ToString();
        }

        /// <summary>
        /// Returns the gamma distribution.
        /// </summary>
        /// <param name="argList">X, alpha, beta, cumulative.</param>
        /// <returns>The gamma distribution.</returns>
        /// <remarks>
        /// X, alpha, and beta should be positive real numbers. Cumulative should be either
        /// True if you want to return the value of the distribution function or False
        /// if you want to return the value of the density function. The distribution value
        /// is computed interactively using Trapezoidal Rule to six to seven significant digits
        /// or 20 iteration maximum.
        /// </remarks>
        public string ComputeGammaOdist(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 4 && argCount != 3)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double a;
            double b;
            double cum = 0;
            double dist = 0;
            if (args[4].StartsWith(this.TIC) && args[4].EndsWith(this.TIC))
            {
                return this.errorStrings[1].ToString();
            }
            for (int i = 0; i < argCount; ++i)
                args[i] = this.GetValueFromArg(args[i]).Replace(this.TIC, string.Empty);

            if (double.TryParse(args[0], NumberStyles.Any, null, out x)
                && double.TryParse(args[1], NumberStyles.Any, null, out a)
                && double.TryParse(args[2], NumberStyles.Any, null, out b))
            {
                if (x < 0 || a <= 0 || b <= 0)
                {
                    return this.errorStrings[4].ToString();
                }
                if (a.ToString().Length >= 5 && b.ToString().Length >= 3)
                {
                    return this.errorStrings[4].ToString();
                }
                if (argCount != 3)
                {
                    cum = (args[3] == this.TRUEVALUESTR) ? 1 : 0;
                    double check = 0;
                    if (double.TryParse(args[3], NumberStyles.Any, null, out check))
                        cum = 0;
                }
                if (cum == 0)
                    dist = this.gammadensity(a, b, x);
                else
                    dist = this.gammadist(a, b, x);
            }
            else
            {
                return this.errorStrings[1].ToString();
            }
            return dist.ToString();
        }

        /// <summary>
        /// Returns the inverse of gamma distribution.
        /// </summary>
        /// <param name="argList">p, alpha, beta</param>
        /// <returns>Returns x such that gamma distribution at x is p.</returns>
        /// <remarks>
        /// P, alpha, and beta should be positive real numbers, with p between 0 and 1.
        /// </remarks>
        public string ComputeGammaOinv(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double p = 0;
            double a = 0;
            double b = 0;
            double invdist = 0;
            if (args[2].StartsWith(this.TIC) && args[2].EndsWith(this.TIC))
            {
                return this.errorStrings[1].ToString();
            }
            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]).Replace(this.TIC, string.Empty);
            }


            if (double.TryParse(args[0], NumberStyles.Any, null, out p)
                && (p > 0 && p < 1)
                && double.TryParse(args[1], NumberStyles.Any, null, out a)
                && double.TryParse(args[2], NumberStyles.Any, null, out b))
            {
                if (a <= 0 || b <= 0)
                {
                    return this.errorStrings[4].ToString();
                }
                invdist = this.gammainv(p, a, b);
            }
            if (p < 0 || p > 1 || (p == 0 || a == 0 || b == 0))
            {
                return this.errorStrings[4].ToString();
            }

            if (invdist <= 0)
            {
                return "#N/A";
            }

            return invdist.ToString();
        }

        /// <summary>
        /// Returns the natural logarithm of the gamma function.
        /// </summary>
        /// <param name="argList">The value to be evaluated.</param>
        /// <returns>The natural logarithm of the gamma function.</returns>
        public string ComputeGammaln0Precise(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (args[0] == this.TIC + this.TIC)
            {
                return this.errorStrings[1].ToString();
            }

            if (argCount != 1)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x = 0;
            if (double.TryParse(this.GetValueFromArg(argList), NumberStyles.Any, null, out x) && x > 0)
                x = this.gammaln(x);
            else
            {
                if (x <= 0)
                {
                    return this.errorStrings[4].ToString();
                }
                return this.errorStrings[1].ToString();
            }
            return x.ToString();
        }

