        /// <summary>
        /// Returns the lognormal distribution.
        /// </summary>
        /// <param name="argList">x, mean, standarddev.</param>
        /// <returns>The lognormal distribution.</returns>
        public string ComputeLognormOdist(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 4)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double u;
            double s;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]).Replace(this.TRUEVALUESTR, string.Empty);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out x)
                && double.TryParse(args[1], NumberStyles.Any, null, out u)
                && double.TryParse(args[2], NumberStyles.Any, null, out s))
            {
                if (x <= 0 || s <= 0)
                {
                    return this.ErrorStrings[4].ToString();
                }
                if (args[3] == this.FALSEVALUESTR)
                {
                    // mean = Math.Exp(u+Math.Pow(u,2))
                    dist = (Math.Exp(-(Math.Pow((Math.Log(x) - u), 2) / (2 * Math.Pow(s, 2)))));   //this.normaldist(Math.Log(x), u, s);
                    dist = dist / x * u * Math.Sqrt(2 * 3.14);
                }
                else
                {
                    dist = this.StandardNormalCumulativeDistribution((Math.Log(x) - u) / s);
                }
            }
            else
            {
                return this.ErrorStrings[1].ToString();
            }
            return dist.ToString();
        }

        /// <summary>
        /// Returns a confidence interval radius.
        /// </summary>
        /// <param name="argList">Alpha, standard deviation, size.</param>
        /// <returns>Returns x such that normal distribution at x is p.</returns>
        /// <remarks>
        /// P should be between 0 and 1.
        /// </remarks>
        public string ComputeConfidenceOnorm(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            double alpha;
            double s;
            double sz;
            double val = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]).Replace(this.TIC, string.Empty);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out alpha)
                && double.TryParse(args[1], NumberStyles.Any, null, out s)
                && double.TryParse(args[2], NumberStyles.Any, null, out sz))
            {
                if (alpha <= 0 || alpha >= 1 || s <= 0 || sz < 1)
                {
                    return this.ErrorStrings[4].ToString();
                }
                //// 1 - alpha  would be from -inf to 1-alpha. adding alpha + 2
                //// takes away the left tail making the integral from alpha-1 to 1-alpha.
                //if (!ExcelLikeComputations)
                    val = this.normalinv(1 - alpha + alpha / 2, 0, 1);
                //else
                //    val = this.newnormalinv(1 - alpha + alpha / 2);
                val = val * s / Math.Sqrt(sz);
            }
            return val.ToString();
        }

        /// <summary>
        /// Returns the chi-squared distribution.
        /// </summary>
        /// <param name="argList">x, degrees of freedom.</param>
        /// <returns>The chi-squared distribution.</returns>
        public string ComputeChisqOdist(string argList)
