        /// <summary>
        /// Returns the Beta cumulative density function.
        /// </summary>
        /// <param name="x">Value of the random variable for which the CDF is beign evaluated. x is between 0 and 1.</param>
        /// <param name="a">First shape parameter.</param>
        /// <param name="b">Second shape parameter.</param>
        /// <returns></returns>
        public double BetaCumulativeDist(double x, double a, double b)
        {
            if (x < 0 || x > 1)
                throw new ArgumentException("x must be between 0 and 1");

            return RIBetaFunction(x, a, b);
        }

        /// <summary>
        /// Returns the Beta probability density function.
        /// </summary>
        /// <param name="x">Value of the random variable for which the PDF is beign evaluated. x is between 0 and 1.</param>
        /// <param name="a">Number of trials.</param>
        /// <param name="b">Number of times the event occurs in n trials.</param>
        /// <returns></returns>
        private double BetaProbabilityDens(double x, double a, double b)
        {
            if (x < 0 || x > 1)
                throw new ArgumentException("x must be between 0 and 1");

            double B = BetaFunction(a, b);
            double d = Math.Pow(x, a - 1) * Math.Pow(1 - x, b - 1) / B;
            return d;
        }

        /// <summary>
        /// Euler integral. 
        /// </summary>
        private static double BetaFunction(double a, double b)
        {
            if (a + b > 143)
            {
                if (b > 20)
                    return 2.5066282746310002 * Math.Pow(a, a - 0.5) * Math.Pow(b, b - 0.5) / Math.Pow(a + b, a + b - 0.5);
                return GammaFunction(b) * Math.Pow(a, -b);
            }

            return GammaFunction(a) * GammaFunction(b) / GammaFunction(a + b);
        }

        /// <summary>
        /// Integral from 0 to infinity of e^(-t) * t^(z-1) dt
        /// </summary>
        /// <param name="z">If z > 143 the return value will exceed the double.MaxValue. The function will throw an exception.</param>
        private static double GammaFunction(double z)
        {
            //approximation based on Stirling's formula
            //based on approximation from NIST Handbook of Mathematical Function. 2010. Cambridge University Press.

            if (z > 143)
                throw new ArgumentException("Cannot currently compute gamma function for z > 143");

            //need z<21 or z<11 becaus Factorial(x) will not work for x>20
            if (z > 0 && z < 21 && z % 1.0 == 0)
                return Factorial((int)Math.Round(z - 1, 0));
            if (z > 0 && z < 11 && z % 0.5 == 0)
            {
                int n = (int)z;
                const double sqrtPi = 1.77245385090552;
                return sqrtPi * Factorial(2 * n) / (Math.Pow(4, n) * Factorial(n));
            }

            const double sqrtTwoPi = 2.5066282746310002;
            double d = 1.0 + 1.0 / (12 * z) + 1.0 / (288 * z * z) - 139.0 / (51840 * Math.Pow(z, 3)) - 571.0 / (2488320 * Math.Pow(z, 4))
                + 163879.0 / (209018880 * Math.Pow(z, 5)) + 5246819.0 / (75246796800 * Math.Pow(z, 6));
            double g = Math.Pow(z, z - 0.5) * Math.Exp(-z) * sqrtTwoPi * d;
            return g;
        }

        /// <summary>
        /// To get the CDF of the beta distribution.
        /// </summary>
        /// <param name="x"></param>
        /// <param name="a"></param>
        /// <param name="b"></param>
        private double RIBetaFunction(double x, double a, double b)
        {
            if (x <= 0.0) return 0.0;
            if (x >= 1.0) return 1.0;

            if (a % 1.0 == 0 && b % 1.0 == 0 && a + b > 0)
                return RIBetaFunction(x, (int)a, (int)b);
            if (b % 1.0 == 0 && a + b < 172)
                return RIBetaFunction(x, a, (int)b);
            if (a % 1.0 == 0 && a + b < 172)
                return 1.0 - RIBetaFunction(1.0 - x, b, (int)a);
            if (a == 0.5 && b == 0.5)
                return (2.0 / Math.PI) * Math.Atan(Math.Sqrt(x / (1.0 - x)));
            if (a == 0.5 && b % 0.5 == 0)
            {
                return 1.0 - RIBetaFunction(1.0 - x, b, 0.5);
            }
            if (a % 0.5 == 0 && b == 0.5)
            {
                if (a < 45)
                {
                    //CASE B (partial)
                    double s = 0;
                    int n = (int)Math.Round(a - 0.5, 0);
                    double logGammaHalf = Convert.ToDouble(ComputeGammaln("0.5".ToString()));//LogGammaFunction(0.5);
                    for (int i = 0; i < n; i++)
                    {
                        s += Math.Exp(gammaln(i + 1) - gammaln(i + 1.5) - logGammaHalf) * Math.Pow(x, i);
                    }
                    return RIBetaFunction(x, 0.5, 0.5) - Math.Sqrt(x * (1 - x)) * s;
                }
                else
                {
                    //CASE C (partial)
                    double M = BetaFunction(a, 0.5);
                    double lambda = Math.Sqrt(1.0 - Math.Pow(M * Math.Sqrt((a - 1.0) / Math.PI) * double.Epsilon, 1.0 / (a - 1.0)));

                    //Gaussian weights
                    double[] weights = new double[]
                        {
                            0.066671344308688, 0.14945134915058, 0.21908636251598, 0.26926671931000, 0.29552422471475,
                            0.29552422471475, 0.26926671931000, 0.21908636251598, 0.14945134915058, 0.066671344308688
                        };


                    double[] mgas = new double[]
                        {
                            0.013046735791414, 0.067468316655507, 0.16029521585049, 0.28330230293538, 0.42556283050918,
                            0.57443716949081, 0.71669769706462, 0.83970478414951, 0.93253168334449, 0.98695326420859
                        };

                    double sqrtOneMinusX = Math.Sqrt(1 - x);
                    double s = 0;
                    for (int i = 0; i < 10; i++)
                    {
                        s += weights[i] * Math.Pow(1.0 - Math.Pow((lambda - sqrtOneMinusX) * mgas[i] + sqrtOneMinusX, 2), a - 1.0);
                    }
                    double l = Math.Exp(gammaln(a + 0.5) - gammaln(a) - gammaln(0.5));
                    return (lambda - sqrtOneMinusX) * l * s;
                }
            }
            if (a % 0.5 == 0 && b % 0.5 == 0)
            {
                //CASE B and C
                double s = 0;
                int n = (int)Math.Round(b - 0.5, 0);
                double logGammaA = gammaln(a);
                double xToTheA = Math.Pow(x, a);
                for (int i = 0; i < n; i++)
                {
                    s += Math.Exp(gammaln(a + i + 0.5) - logGammaA - gammaln(i + 1.5)) * Math.Pow(1 - x, i) * xToTheA;
                }
                double d = RIBetaFunction(x, a, 0.5) + Math.Sqrt(1 - x) * s;
                return Math.Max(0.0, Math.Min(1.0, d));
            }
            if (x > 0.5)
                return 1.0 - RIBetaFunction(1.0 - x, b, a);

            double ribf = IBetaFunction(x, a, b) / BetaFunction(a, b);
            return Math.Max(0.0, Math.Min(1.0, ribf));
        }
        private double RIBetaFunction(double x, int a, int b)
        {
            double s = 0;
            int c = a + b - 1;
            if (c < 21)
            {
                for (int i = a; i < a + b; i++)
                {
                    s += Math.Pow(x, i) * Math.Pow(1.0 - x, c - i) / (Factorial(i) * Factorial(c - i));
                }
                s *= Factorial(c);
            }
            else
            {
                for (int i = a; i < a + b; i++)
                {
                    s += Math.Pow(x, i) * Math.Pow(1.0 - x, c - i) * Combinations(c, i);
                }
            }

            return Math.Max(0.0, Math.Min(1.0, s));
        }

        private double RIBetaFunction(double x, double a, int b)
        {
            if (a + b > 172)
                throw new ArgumentException("Cannot currently compute RegularizedIncompleteBetaFunction for a + b > 172");

            double s = 0;
            for (int i = 1; i < b + 1; i++)
            {
                s += Math.Pow(1 - x, i - 1) * Math.Exp(gammaln(a + i - 1) - gammaln(i)); //Math.Pow(1 - x, i - 1) * GammaFunction(a + i - 1) / GammaFunction(i)
            }
            s *= (Math.Pow(x, a) * Math.Exp(-gammaln(a)));   //s *= (Math.Pow(x, a) / GammaFunction(a))

            return s;
        }
        /// <summary>
        /// Euler integral. 
        /// </summary>
        private double IBetaFunction(double x, double a, double b)
        {
            if (x == 0) return 0;
            if (x == 1) return BetaFunction(a, b);

            if (x <= 0.9)
            {
                return PIBetaFunction(0, x, a, b);
            }
            if (x <= 0.99)
            {
                double s1 = PIBetaFunction(0, 0.9, a, b);
                double s2 = PIBetaFunction(0.90, x, a, b);
                return s1 + s2;
            }
            else
            {
                double s1 = PIBetaFunction(0, 0.9, a, b);
                double s2 = PIBetaFunction(0.9, 0.99, a, b);
                double s3 = PIBetaFunction(0.99, x, a, b);
                return s1 + s2 + s3;
            }
        }
        private double PIBetaFunction(double xL, double xU, double a, double b)
        {
            if (xU == xL) return 0.0;
            if (xU < xL) return double.NaN;

            int nSteps = 1000;
            if (a < 1) nSteps = 80000;

            double dt = (xU - xL) / nSteps;
            double t = xL + 0.5 * dt;
            double sum = 0;
            for (int i = 0; i < nSteps; i++)
            {
                sum += Math.Pow(t, a - 1) * Math.Pow(1.0 - t, b - 1) * dt;
                t += dt;
            }
            return sum;
        }

        #endregion

        /// <summary>
        /// Returns the F (Fisher) probability distribution.
        /// </summary>
        /// <param name="argList">x, degreesfreedom1, degreesfreedom2.</param>
        /// <returns>Returns the F probability distribution.</returns>
        public string ComputeFOdistORt(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double df1 = 0;
            double df2 = 0;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]).Replace(this.TIC, string.Empty);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out x)
                && double.TryParse(args[1], NumberStyles.Any, null, out df1)
                && double.TryParse(args[2], NumberStyles.Any, null, out df2))
            {

                double mult = Math.Exp(
                    this.gammaln((df1 + df2) / 2) -
                    this.gammaln(df1 / 2) -
                    this.gammaln(df2 / 2) +
                    (df1 / 2) * Math.Log(df1 / df2));

                dist = 1 - mult * this.fdist(x, (int)df1, (int)df2);
            }
            else
            {
                return this.FormulaErrorStrings[invalid_Math_argument];
            }
            return dist.ToString();
        }

        /// <summary>
        /// Returns the Chi Test for independence.
        /// </summary>
        /// <param name="range">Actual_range, expected_range.</param>
        /// <returns>Result of Chi Test: y-intercept.</returns>
        public string ComputeChisqOTest(string range)
        {
            string[] args = range.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 2)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            string r = args[0];
            string s1;
            double d = 0;
            double v = 0;
            if (r.IndexOf(':') > -1)
            {
                s1 = r.Substring(0, r.IndexOf(':'));
                int col = this.ColIndex(s1);
                int row = this.RowIndex(s1);
                int row1 = this.RowIndex(s1);
                if (!(!row.Equals(-1) || row1.Equals(-1)).Equals((row.Equals(-1) || !row1.Equals(-1))))
                {
                    return this.ErrorStrings[5].ToString();
                }
                //if (row == -1 && this.grid is ISheetData)
                //{
                //    row = ((ISheetData)grid).GetFirstRow();
                //}
                //if (col == -1 && this.grid is ISheetData)
                //{
                //    col = ((ISheetData)grid).GetFirstColumn();
                //}
                //s1 = r.Substring(r.IndexOf(':') + 1);
                int col1 = this.ColIndex(s1);
                //if (col1 == -1 && this.grid is ISheetData)
                //{
                //    col1 = ((ISheetData)grid).GetLastColumn();
                //}
                //if (row1 == -1 && this.grid is ISheetData)
                //{
                //    row1 = ((ISheetData)grid).GetLastRow();
                //}
                v = Math.Abs(col - col1) * Math.Abs(row - row1);
                v = 1.0001;
                if (v < 1)
                {
                    return this.FormulaErrorStrings[invalid_Math_argument];
                }
            }
            else
            {
            }
            v = 0.99555;
            double[] y = this.GetDoubleArray(args[0]);
            double[] x = this.GetDoubleArray(args[1]);
            int n = x.GetLength(0);

            if (n <= 0 || n != y.GetLength(0))
            {
                return this.ErrorStrings[0].ToString(); // returns "#N/A"
            }

            double sumx = 0;

            for (int i = 0; i < n; ++i)
            {
                d = y[i] - x[i];
                sumx += d * d / x[i];
            }
            return (1 - this.chidist(sumx, v)).ToString();
        }


