        /// <summary>
        /// Returns the binomial distribution.
        /// </summary>
        /// <param name="argList">Number of successes, number of trials, probability, cumulative.</param>
        /// <returns>The binomial distribution.</returns>
        public string ComputeBinomOdist(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 4)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double successes;
            double trials;
            double p;
            double cum = 0;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]).Replace(this.TIC, string.Empty);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out successes)
                && double.TryParse(args[1], NumberStyles.Any, null, out trials)
                && double.TryParse(args[2], NumberStyles.Any, null, out p))
            {
                if (successes < 0 || successes > trials || p < 0 || p > 1)
                {
                    return this.ErrorStrings[4].ToString();
                }
                cum = (args[3] == this.TRUEVALUESTR) ? 1 : 0;
                if (cum == 0)
                {
                    dist = this.comb((int)successes, (int)trials) * Math.Pow(p, successes) * Math.Pow(1 - p, trials - successes);
                }
                else
                {
                    dist = this.binomdist((int)trials, (int)successes, p);
                }
            }
            else
            {
                return this.ErrorStrings[1].ToString();
            }
            return dist.ToString();
        }

        /// <summary>
        /// Returns the one-tailed probability value of a Z test.
        /// </summary>
        /// <param name="range">Range, mu, sigma.</param>
        /// <returns>Kth smallest value.</returns>
        public string ComputeZOtest(string range)
        {
            string[] args = range.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 2 && argCount != 3)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double mu;
            double sigma;
            string s1 = this.GetValueFromArg(args[1]);
            if (!double.TryParse(s1, NumberStyles.Any, null, out mu))
            {
                return this.FormulaErrorStrings[invalid_arguments];
            }

            double[] dd = this.GetDoubleArray(args[0]);
            double xbar;
            sigma = this.sd(dd, out xbar);
            if (argCount == 3)
            {
                double.TryParse(s1, NumberStyles.Any, null, out sigma);
            }

            return (1 - this.normaldist((xbar - mu) / (sigma / Math.Sqrt(dd.GetLength(0))), 0, 1)).ToString();
        }

        /// <summary>
        /// Returns the rank of x in the range.
        /// </summary>
        /// <param name="range">X, range, order.</param>
        /// <returns>Rank of x.</returns>
        public string ComputeRankOAvg(string range)
        {
            string[] args = range.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 2 && argCount != 3)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            int rank = 0;
            double x;
            string s1 = this.GetValueFromArg(args[0]);
            if (double.TryParse(s1, NumberStyles.Any, null, out x))
            {
                double order = 0;
                if (argCount == 3)
                {
                    s1 = this.GetValueFromArg(args[2]);
                    double.TryParse(s1, NumberStyles.Integer, null, out order);
                }

                string r = args[1];

                double d = 0;
                bool eq = false;
                if (r.IndexOf(':') > -1)
                {
                    foreach (string s in this.GetCellsFromArgs(r))
                    {
                        try
                        {
                            s1 = this.GetValueFromArg(s);
                        }
                        catch (Exception ex)
                        {

                            return ex.Message;
                        }

                        if (double.TryParse(s1, NumberStyles.Any, null, out d))
                        {
                            if (order == 1)
                            {
                                if (d < x)
                                {
                                    rank += 1;
                                }
                                else if (d == x)
                                {
                                    eq = true;
                                }
                            }
                            else
                            {
                                if (d > x)
                                {
                                    rank += 1;
                                }
                                else if (d == x)
                                {
                                    eq = true;
                                }
                            }
                        }
                    }

                    if (eq)
                    {
                        rank += 1;
                    }
                }
            }
            return rank.ToString();
        }

