            int n = 0;
            string s1 = this.GetValueFromArg(args[0]);
            string s2 = this.GetValueFromArg(args[2]);
            if (double.TryParse(s1, NumberStyles.Any, null, out x) && int.TryParse(s2, NumberStyles.Any, null, out n))
            {
            }
            return (IHProbDens(x, n)).ToString();
