        /// <summary>
        /// Returns the most frequent value in the range.
        /// </summary>
        /// <param name="range">A string holding a list (separated by commas) of
        /// cell references,
        /// formulas, or numbers.
        /// </param>
        /// <returns>The most frequent value.</returns>
        public string ComputeModeOsngl(string range)
        {
            double[] dd = this.GetDoubleArray(range);
            double[] ddSave = dd.Clone() as Double[];
            int n = dd.GetLength(0);
            if (n <= 1)
            {
                return "#N/A";
            }

            Array.Sort(dd);
            ArrayList ties = new ArrayList();
            double mode = double.NaN;
            int count = 0;
            int maxCount = 0;

            for (int i = 1; i < n; ++i)
            {
                if (dd[i] == dd[i - 1])
                {
                    count++;
                }
                else
                {
                    if (count > maxCount)
                    {
                        maxCount = count;
                        mode = dd[i - 1];
                        ties.Clear();
                        ties.Add(mode);
                    }
                    else if (count == maxCount)
                    {
                        ties.Add(dd[i - 1]);
                    }

                    count = 0;
                }
            }

            if (count > maxCount)
            {
                maxCount = count;
                mode = dd[n - 1];
                ties.Clear();
                ties.Add(mode);
            }

            if (maxCount > 0)
            {
                if (count == maxCount)
                {
                    ties.Add(dd[n - 1]);
                }

                if (ties.Count > 1)
                {
                    foreach (double d in ddSave)
                    {
                        if (ties.IndexOf(d) > -1)
                        {
                            mode = d;
                            break;
                        }
                    }
                }
                return mode.ToString();
            }
            return "#N/A";
        }

