        /// <summary>
        /// Returns the Poisson distribution.
        /// </summary>
        /// <param name="argList">x, mean, cumulative</param>
        /// <returns>Returns the exponential distribution.</returns>
        /// <remarks>
        /// Cumulative should be either
        /// True if you want to return the value of the distribution function or False
        /// if you want to return the value of the density function.
        /// </remarks>
        public string ComputePoissonODist(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            double u;
            double cum = 0;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out x)
                && double.TryParse(args[1], NumberStyles.Any, null, out u))
            {
                cum = (args[2] == this.TRUEVALUESTR) ? 1 : 0;
                int n = (int)x;
                if (cum == 0)
                {
                    double prod = 1;
                    for (int i = 2; i <= n; ++i)
                    {
                        prod *= i;
                    }
                    dist = Math.Exp(-u) * Math.Pow(u, n) / prod;
                }
                else
                {
                    double prod = 1;
                    dist = 0;
                    double ui = 1;
                    for (int i = 0; i <= n; ++i)
                    {
                        dist += ui / prod;
                        prod *= i + 1;
                        ui *= u;
                    }

                    dist = Math.Exp(-u) * dist;
                }
            }
            return dist.ToString();
        }

        /// <summary>
        ///Returns the Student's t-distribution. 
        /// </summary>
        /// <param name="argList">x, degreesfreedom1.</param>
        /// <returns>Returns the Student's t-distribution.</returns>
        public string ComputeTOdist(string argList)
        {
            string[] args = argList.Split(new char[] { ParseArgumentSeparator });
            int argCount = args.GetLength(0);
            if (argCount != 3)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }

            double x;
            int df1 = 0;
            double dist = 0;

            for (int i = 0; i < argCount; ++i)
            {
                args[i] = this.GetValueFromArg(args[i]).Replace(this.TIC, string.Empty);
            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out x)
                && int.TryParse(args[1], NumberStyles.Any, null, out df1))
            {
                if (df1 < 1 || (x.ToString().StartsWith("-")))
                {
                    return this.errorStrings[4].ToString();
                }

                if (args[2] == this.TRUEVALUESTR)
                {
                    dist = TCumulativeDensity(x, (int)df1);
                    //dist = StudentsTCumulativeDistributionFunctionInverse(x, (int)u);
                }
                else if (args[2] == this.FALSEVALUESTR)
                {
                    dist = TProbabilityDensity(x, (int)df1);
                }
            }
            else
            {
                return this.errorStrings[1].ToString();
            }
            return dist.ToString();
        }

        /// <summary>
