            }

            if (double.TryParse(args[0], NumberStyles.Any, null, out x)
                && int.TryParse(args[1], NumberStyles.Any, null, out df1))
            {
                if (df1 < 1 || x < 0 || (x.ToString().StartsWith("-")))
                {
                    return this.errorStrings[4].ToString();
                }
                dist = TCumulativeDistributionInverse(x, (int)df1);
            }
            else
            {
                return this.errorStrings[1].ToString();
            }
            return dist.ToString();
        }

        #region Student's t Distribution
        /// <summary>
        /// Returns the PDF of Student's t distribution.
        /// </summary>
        /// <param name="x">Value at which the distribution is evaluated.</param>
        /// <param name="k">Degrees of freedom.</param>
        private double TProbabilityDensity(double x, int k)
        {
            double a = GammaFunction(0.5 * k + 0.5);
            double b = Math.Pow(1.0 + (x * x) / k, -0.5 * k - 0.5);
            double c = Math.Sqrt(k * Math.PI) * GammaFunction(0.5 * k);

            return a * b / c;
        }

        /// <summary>
        /// Returns the CDF of Student's t distribution.
        /// </summary>
        /// <param name="x">Value at which the distribution is evaluated.</param>
        /// <param name="k">Degrees of freedom.</param>
        private double TCumulativeDensity(double x, int k)
        {
            if (double.IsNaN(x))
                return double.NaN;
            if (x == 0)
                return 0.5;
            if (x > 0)
            {
                double x2 = k / (x * x + k);
                return 1.0 - 0.5 * RIBetaFunction(x2, 0.5 * k, 0.5);
            }
            return 1.0 - TCumulativeDensity(-x, k);
        }

        /// <summary>
        /// Returns the inverse of the CDF of the Student's t distribution.
        /// For k = 3, and 5+ the solution is an approximation. 
        /// </summary>
        /// <param name="p">Cumulative probability of the distribution. p is between 0 and 1.</param>
        /// <param name="k">Degrees of freedom.</param>
        private double TCumulativeDistributionInverse(double p, int k)
        {

            const int maxIterations = 10;
            const double minAccuracy = 0.0001;

            if (p < 0 || p > 1.0) throw new System.ArgumentException("Probability must be between 0 and 1");
            if (p == 0) return double.NegativeInfinity;
            if (p == 1) return double.PositiveInfinity;
            if (p == 0.5) return 0.0;

            switch (k)
            {
                case 1:
                    return Math.Tan(Math.PI * (p - 0.5));
                case 2:
                    double alpha = 4 * p * (1 - p);
                    return 2 * (p - 0.5) * Math.Sqrt(2.0 / alpha);
                case 4:
                    alpha = 4 * p * (1 - p);
                    double sqrtAlpha = Math.Sqrt(alpha);
                    double q = Math.Cos((1.0 / 3.0) * Math.Acos(sqrtAlpha)) / sqrtAlpha;
                    return Math.Sign(p - 0.5) * 2 * Math.Sqrt(q - 1);
                default:
                    double x;
                    if (k > 6)
                        x = StandardNormalCumulativeDistributionFunctionInverse(p);
                    else
                        x = TCumulativeDistributionInverse(p, 4);

                    for (int i = 0; i < maxIterations; i++)
                    {
                        double p0 = TCumulativeDensity(x, k);
                        double absAccuracy = Math.Abs(p - p0);
                        if (absAccuracy < minAccuracy) return x;
                        double slope = TProbabilityDensity(x, k);
                        x = x + (p - p0) / slope;
                    }
                    throw new Exception("Solution did not converge");
            }
        }
