        /// <summary>
        /// Computes the Decimal Number for the given binary NUmber.
        /// </summary>
        /// <param name="argList">Input BinaryNumber</param>
        /// <returns>The resultant Decimal Number</returns>
        public string ComputeBin2Dec(string argList)
        {
#if _ENABLETIMERS
               string ML = "ComputeBinToDec"; MarkTimeStart(ML);
#endif
            string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
            if (ranges.Length > 1)
            {
                return this.FormulaErrorStrings[wrong_number_arguments];
            }
            string value = this.GetValueFromArg(ranges[0]).Replace(this.TIC, string.Empty);
            try
            {
                if (value == "")
                    value = "0";
                // Convert binary number to decimal
                string result = Convert.ToInt32(value, 2).ToString();
                // Handle negative numbers
                if (value.Length == 10 && value.Substring(0, 1) == "1")
                {
                    return (Convert.ToInt32(value.Substring(1), 2) - 512).ToString();
                }
                else
                {
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                    return result;
                }
            }
            catch (Exception)
            {
                return ErrorStrings[4].ToString();
            }
        }
        /// <summary>
        /// Computes the Octal Number for the given binary NUmber.
        /// </summary>
        /// <param name="argList">Input BinaryNumber</param>
        /// <returns>The resultant Octal Number</returns>
        public string ComputeBin2Oct(string argList)
        {
            int charCount = 0;
            string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
            string value = this.GetValueFromArg(ranges[0]).Replace(this.TIC, string.Empty);
            string result = string.Empty;

            if (ranges.Length > 1)
            {
                charCount = int.Parse(ranges[1]);
            }

            // Ignore places and return a 10-character octal number if number is negative
            if (value.Length == 10 && value.Substring(0, 1) == "1")
            {
                return (1073741312 + int.Parse(Convert.ToString(Convert.ToInt32(value, 2), 8))).ToString();
            }

            try
            {
                if (value.Length > 10)
                {
                    result = ErrorStrings[4].ToString();
                }

                else
                {
                    result = BaseToBase(value, 2, 8);
                    if (ranges.Length > 1)
                    {
                        if (charCount >= result.Length && charCount <= 10)
                            result = result.PadLeft(charCount, '0');
                        else
                        {
                            result = ErrorStrings[4].ToString();
                        }
                    }
                }
            }

            catch (Exception)
            {

#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                    return this.ErrorStrings[4].ToString();
            }
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
            return result;
        }

