        /// <summary>
        /// Computes the Binary value for the given Octal Number.
        /// </summary>
        /// <param name="argList">Data to be converted.</param>
        /// <returns>Returns the calculated Binary value.</returns>
        public string ComputeOct2Bin(string argList)
        {
            int charCount = 0;
            string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
            string value = this.GetValueFromArg(ranges[0]).Replace(this.TIC, string.Empty);
            string result = string.Empty;

            if (ranges.Length > 2)
            {
                    return FormulaErrorStrings[25];
            }
            else
                if (ranges.Length > 1)
                {
                    charCount = int.Parse(ranges[1]);
                }

            try
            {
                result = BaseToBase(value, 8, 2);
                if (ranges.Length > 1)
                {
                    if (charCount >= result.Length && charCount <= 10)
                        result = result.PadLeft(charCount, '0');
                    else
                    {
                            result = ErrorStrings[4].ToString();
                    }
                }
                else
                    if (result.Length > 10)
                        result = result.Substring(result.Length - 10, 10);

            }
            catch (Exception)
            {
                    if (ComputeIsText(value) == TRUEVALUESTR)
                        return ErrorStrings[5].ToString();
                    else if (value == "")
                        return "0";
                    else
                        return this.ErrorStrings[4].ToString();
            }
            return result;
        }

