        /// <summary>
        /// Gets the Imaginary part of the given Complex number.
        /// </summary>
        /// <param name="argList">Given complex number.</param>
        /// <returns>Imaginary part of the given complex Number.</returns>
        public string ComputeImaginary(string argList)
        {
            string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
            if (ranges.Length > 1)
            {
                    return FormulaErrorStrings[10].ToString();
            }
            string value = ranges[0];
            if (value.Contains(this.TIC))
                value = ranges[0].Replace(this.TIC, string.Empty);
            if (value == "")
            {
                    return ErrorStrings[4].ToString();
            }

            // Normalize imaginary coefficient
            value = value.Replace("+i", "+1i").Replace("-i", "-1i").Replace("+j", "+1j").Replace("-j", "-1j");

            // Lookup sign
            int plus = value.IndexOf('+');
            int minus = value.IndexOf('-');
            if (plus == 0) plus = value.IndexOf('+', 1);
            if (minus == 0) minus = value.IndexOf('-', 1);

            // Lookup imaginary unit
            string last = value.Substring(value.Length - 1, 1);
            bool unit = (last == "i" || last == "j");

            if (plus >= 0 || minus >= 0)
            {
                // Return error if imaginary unit is neither i nor j
                if (!unit)
                    return ErrorStrings[4].ToString();

                // Return imaginary coefficient of complex number
                if (plus >= 0)
                {
                        return (this.ComputeIsText(value.Substring(0, plus)) == TRUEVALUESTR) ?
                        ErrorStrings[4].ToString() : value.Substring(plus + 1, (value.Length - plus) - 2);
                }
                else
                {
                        return ((this.ComputeIsText(value.Substring(0, minus - 1)) == TRUEVALUESTR) || (this.ComputeIsText(value.Substring(minus + 1, (value.Length - minus) - 2))) == TRUEVALUESTR) ?
                         ErrorStrings[4].ToString() : "-" + value.Substring(minus + 1, (value.Length - minus) - 2);
                }
            }
            else
            {
                if (unit)
                {
                    return ((this.ComputeIsText(value.Substring(0, value.Length - 1))) == TRUEVALUESTR) ? ErrorStrings[4].ToString() : value.Substring(0, value.Length - 1);
                }
                else
                {
                    return ((this.ComputeIsText(value)) == TRUEVALUESTR) ? ErrorStrings[4].ToString() : "0";
                }
            }
        }
        /// <summary>
        /// Gets the Real part of the given Complex number.
        /// </summary>
        /// <param name="argList">Given complex number.</param>
        /// <returns>Real part of the given complex Number.</returns>
        public string ComputeReal(string argList)
        {
            string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });

            if (ranges.Length > 1)
            {
                    return FormulaErrorStrings[10].ToString();
            }
            string value = ranges[0];

            if (value.Contains(this.TIC))
                value = ranges[0].Replace(this.TIC, string.Empty);

            //value = this.GetValueFromArg(ranges[0]);
            // Lookup sign
            if (value.Contains(this.TIC) || value == "")
            {
                    return ErrorStrings[4].ToString();
            }
            value = value.Replace(this.TIC, string.Empty);
            value = value.TrimEnd();
            int plus = value.IndexOf('+');
            int minus = value.IndexOf('-');
            if (plus == 0) plus = value.IndexOf('+', 1);
            if (minus == 0) minus = value.IndexOf('-', 1);

            // Lookup imaginary unit
            string last = value.Substring(value.Length - 1, 1);
            bool unit = (last == "i" || last == "j");

            if (plus >= 0 || minus >= 0)
            {
                // Return error if imaginary unit is neither i nor j
                if (!unit) return ErrorStrings[4].ToString();

                // Return real coefficient of complex number
                if (plus >= 0)
                {
                        return ((ComputeIsText(value.Substring(0, plus)) == TRUEVALUESTR)) ?
                      ErrorStrings[4].ToString() : value.Substring(0, plus);
                }
                else
                {
                        return (ComputeIsText(value.Substring(0, minus - 1)) == TRUEVALUESTR || ComputeIsText(value.Substring(minus + 1, (value.Length - minus) - 2)) == TRUEVALUESTR) ? ErrorStrings[4].ToString() : value.Substring(0, minus);

                }
            }
            else
            {
                if (unit)
                {
                   
                        return (ComputeIsText(value.Substring(0, value.Length - 1)) == TRUEVALUESTR) ? ErrorStrings[4].ToString() : "0";
                }
                else
                {
                        return (ComputeIsText(value) == TRUEVALUESTR) ? ErrorStrings[5].ToString() : value;
                }
            }
        }
        /// <summary>
        /// Obtains the complex number for the given real and imaginary part.
        /// </summary>
        /// <param name="argList">Given real and Imaginary part.</param>
        /// <returns>The complex number derived from the real and imaginary part.</returns>
        public string ComputeComplex(string argList)
        {
            string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
            if (ranges.Length < 2 || ranges.Length > 3)
            {
                    return FormulaErrorStrings[13].ToString();
            }
            string real = ranges[0];
            real = real.Replace(this.TIC, "");
            string imaginary = ranges[1];
            imaginary = imaginary.Replace(this.TIC, "");

            if (double.IsInfinity(double.Parse(real)) || double.IsInfinity(double.Parse(imaginary)) || double.IsNaN(double.Parse(real)) || double.IsNaN(double.Parse(imaginary)))
            {
                    return ErrorStrings[4].ToString();
            }

            string suffix;
            try
            {
                if ((ranges.Length <= 3))
                {
                    // Return error if either number is a non-numeric value
                    if (this.ComputeIsText(real) == TRUEVALUESTR || this.ComputeIsText(imaginary) == TRUEVALUESTR)
                    {
                            return "#VALUE!";
                    }
                    // Set suffix
                    if (ranges.Length == 3)
                        suffix = ranges[2];
                    else
                        suffix = "";
                    suffix = (suffix == "") ? "i" : suffix = ranges[2];
                    suffix = suffix.Replace(TIC, string.Empty);

                    // Return error if suffix is neither "i" nor "j"
                    if (suffix != "i" && suffix != "j")

                    {
                            return ErrorStrings[1].ToString();
                    }
                    // Return complex number
                    if (double.Parse(real) == 0 && double.Parse(imaginary) == 0)
                        return "0";
                    else if (double.Parse(real) == 0)
                    {
                        return
                            (double.Parse(imaginary) == 1) ? suffix : imaginary.ToString() + suffix;
                    }
                    else
                        if (double.Parse(imaginary) == 0)
                            return real;
                        else
                        {
                            string sign = (double.Parse(imaginary) > 0) ? "+" : "";
                            return real + sign + ((double.Parse(imaginary) == 1) ? suffix : imaginary + suffix);
                        }
                }

                else
                {

                        return FormulaErrorStrings[21].ToString();
                }

            }

            catch
            {

                    if (ComputeIsText(real) == TRUEVALUESTR || ComputeIsText(imaginary) == TRUEVALUESTR)
                        return ErrorStrings[5].ToString();
                    else if (real == "" || imaginary == "")
                        return ErrorStrings[1].ToString();
                    else if (double.Parse(real) < 0 || double.Parse(imaginary) < 0)
                        return ErrorStrings[4].ToString();
                    else
                        return this.ErrorStrings[1].ToString();
            }

        }
        /// <summary>
        /// Computes the sum of two complex number.
        /// </summary>
        /// <param name="argList">Parameter that is used for performing sum</param>
        /// <returns>The calculated sum of the numbers</returns>
        public string ComputeImSum(string argList)
        {
            string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
            string result = this.GetValueFromArg(ranges[0]);
            string c = null, d = null;
            result = result.Replace(this.TIC, "");

            if (result == "")
            {
                return ErrorStrings[4].ToString();
            }

            for (int i = 1; i < ranges.Length; i++)
            {
                // Lookup coefficients of two complex numbers
                string a = ComputeReal(result);
                string b = ComputeImaginary(result);
                if (ranges.Length > 1)
                {
                    c = ComputeReal(ranges[i]);
                    d = ComputeImaginary(ranges[i]);
                }
                else
                {
                    c = "0"; d = "0";
                }
                // Return error if either coefficient is not a number
                if (a == ErrorStrings[4].ToString() || b == ErrorStrings[4].ToString() || c == ErrorStrings[4].ToString() || d == ErrorStrings[4].ToString())
                {

                        return ErrorStrings[4].ToString();
                }

                // Complute product of two complex numbers
                try
                {
                    string num = (int.Parse(a) + int.Parse(c)).ToString() + ParseArgumentSeparator + (int.Parse(b) + int.Parse(d)).ToString();
                    result = ComputeComplex(num);
                }

                catch (Exception)
                {

                    {
                        if (ComputeIsText(result) == TRUEVALUESTR)
                            return ErrorStrings[5].ToString();
                        else if (result == "")
                            return ErrorStrings[4].ToString();
                        else
                            return this.ErrorStrings[1].ToString();
                    }
                }
            }
            return result;
        }
        /// <summary>
        /// Computes the Difference of two complex number.
        /// </summary>
        /// <param name="argList">Parameter that is used for performing Subtraction</param>
        /// <returns>The calculated difference of the numbers</returns>
        public string ComputeImSub(string argList)
        {
            string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
            string result = this.GetValueFromArg(ranges[0]);
            result = result.Replace(TIC, string.Empty);
            for (int i = 1; i < ranges.Length; i++)
            {
                ranges[i] = ranges[i].Replace(TIC, string.Empty);
                // Lookup coefficients of two complex numbers
                string a = ComputeReal(result);
                string b = ComputeImaginary(result);
                string c = ComputeReal(ranges[i]);
                string d = ComputeImaginary(ranges[i]);


                if (a == ErrorStrings[4].ToString() || b == ErrorStrings[4].ToString() || c == ErrorStrings[4].ToString() || d == ErrorStrings[4].ToString())
                    return ErrorStrings[4].ToString();
                try
                {
                    string num = (int.Parse(a) - int.Parse(c)).ToString() + ParseArgumentSeparator + (int.Parse(b) - int.Parse(d)).ToString();
                    result = ComputeComplex(num);
                }
                catch (Exception)
                {

                    return this.FormulaErrorStrings[21].ToString();
                }
            }

            return result;
        }

        /// <summary>
        /// Returns the complex conjugate of a complex number in x + yi or x + yj text format.
        /// </summary>
        /// <param name="argList">Input Complex Number</param>
        /// <returns>The complex conjugate of a complex number in x + yi or x + yj text format.</returns>
        public string ComputeImConjugate(string argList)
        {
               string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
            if (ranges.Length != 1)
            {
                    return FormulaErrorStrings[10].ToString();
            }

            string value = this.GetValueFromArg(ranges[0]);
            string x = ComputeReal(value);
            string y = ComputeImaginary(value);

            // Lookup imaginary unit
            string unit = value.Substring(value.Length - 1);
            unit = (unit == "i" || unit == "j") ? unit : "i";

            // Return error if either coefficient is not a number
            if (x == ErrorStrings[4].ToString() || y == ErrorStrings[4].ToString())
            {
                    return ErrorStrings[4].ToString();
            }
            try
            {
                // Return conjugate of complex number
                string num = (int.Parse(x)).ToString() + ParseArgumentSeparator + "-" + (int.Parse(y)).ToString() + ParseArgumentSeparator + unit;
                return (y != "0") ? ComputeComplex(num) : value;
            }

            catch (Exception)
            {

                return this.FormulaErrorStrings[21].ToString();

            }
        }
        /// <summary>
        /// Computes the Product of the given Complex Numbers
        /// </summary>
        /// <param name="argList">Input Complex Numbers</param>
        /// <returns>The multiplied result of the two complex numbers.</returns>
        public string ComputeImProduct(string argList)
        {
            string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
            string result = this.GetValueFromArg(ranges[0]);
            result = result.Replace(this.TIC, "");
            string a = ComputeReal(result);
            string b = ComputeImaginary(result);

            if (result == "")
            {
                return ErrorStrings[4].ToString();
            }
            if (ranges.Length < 1)
                return ErrorStrings[5].ToString();
            // Loop on all numbers
            for (int i = 1; i < ranges.Length; i++)
            {
                // Lookup coefficients of two complex numbers

                string c = ComputeReal(ranges[i]);
                string d = ComputeImaginary(ranges[i]);

                // Return error if either coefficient is not a number
                if (a == ErrorStrings[4].ToString() || b == ErrorStrings[4].ToString() || c == ErrorStrings[4].ToString() || d == ErrorStrings[4].ToString())
                {

                        return ErrorStrings[4].ToString();
                }
                try
                {
                    // Complute product of two complex numbers
                    int x1 = int.Parse(a);
                    int x2 = int.Parse(b);
                    int x3 = int.Parse(c);
                    int x4 = int.Parse(d);

                    int res1 = (x1 * x3) - (x2 * x4);
                    int res2 = (x1 * x4) + (x2 * x3);

                    result = ComputeComplex(res1.ToString() + ParseArgumentSeparator + res2.ToString());
                }
                catch (Exception)
                {
                    return this.FormulaErrorStrings[21].ToString();
                }
            }
            return result;
        }

        /// <summary>
        /// Computes the Division of the given Complex Numbers
        /// </summary>
        /// <param name="argList">Input Complex Numbers</param>
        /// <returns>The Divided result of the two complex numbers.</returns>
        public string ComputeImDiv(string argList)
        {
            string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
            string result = this.GetValueFromArg(ranges[0]);
            string result1 = result.Replace(this.TIC, string.Empty);

            string a;
            string b;
            string c;
            string d;

            try
            {
                if (ranges.Length <= 1 || ranges.Length > 2)
                {

                        return FormulaErrorStrings[13].ToString();
                }
                else
                {
                    a = ComputeReal(ranges[0].Replace(this.TIC, ""));
                    b = ComputeImaginary(ranges[0].Replace(this.TIC, ""));//24.8313058489464-11.3566127112182i;  -11.3642347064011-24.8146514856342i


                    c = ComputeReal(ranges[1].Replace(this.TIC, ""));
                    d = ComputeImaginary(ranges[1].Replace(this.TIC, ""));
                }
                string unit1 = result.Substring(result1.Length - 1);
                string unit2 = result.Substring(result1.Length - 1);
                string unit = string.Empty;
                if (unit1 == "j")
                {
                    unit = "j";
                }
                else if (unit2 == "j")
                {
                    unit = "j";
                }

                // Return error if either coefficient is not a number
                if (a == ErrorStrings[4].ToString() || b == ErrorStrings[4].ToString() || c == ErrorStrings[4].ToString() || d == ErrorStrings[4].ToString())
                {

                        return ErrorStrings[4].ToString();
                }
                // Return error if inumber2 is null
                if (c == "0" && d == "0")
                {

                        return ErrorStrings[4].ToString();
                }
                double v1 = double.Parse(a);
                double v2 = double.Parse(b);
                double v3 = double.Parse(c);
                double v4 = double.Parse(d);

                double den = (double)((v3 * v3) + (v4 * v4));
                string args = (((v1 * v3) + (v2 * v4)) / den).ToString() + ParseArgumentSeparator + (((v2 * v3) - (v1 * v4)) / den).ToString();
                return ComputeComplex(args).ToString();
            }

            catch (Exception)
            {


                    if (ComputeIsText(result1) == TRUEVALUESTR)
                        return ErrorStrings[5].ToString();
                    else if (result1 == "")
                        return ErrorStrings[4].ToString();
                    else
                        return this.ErrorStrings[1].ToString();
            }
        }

        /// <summary>
        /// Returns the argument  (theta), an angle expressed in radians
        /// </summary>
        /// <param name="argList">Input Complex Number</param>
        /// <returns>The argument  (theta), an angle expressed in radians</returns>
        public string ComputeImArgument(string argList)
        {
            string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });

            if (ranges.Length > 1 || ranges.Length < 1)
            {

                    return FormulaErrorStrings[10].ToString();
            }

            string inumber = this.GetValueFromArg(ranges[0]);
            inumber = inumber.Replace(this.TIC, "");

            if (inumber == "")
            {

                    return ErrorStrings[4].ToString();
            }
            string x = ComputeReal(inumber);
            string y = ComputeImaginary(inumber);

            try
            {
                double a = double.Parse(x);
                double b = double.Parse(y);

                // Return error if either coefficient is not a number
                if (x == ErrorStrings[4].ToString() || y == ErrorStrings[4].ToString())

                        return ErrorStrings[4].ToString();

                // Return error if inumber is equal to zero
                if (a == 0 && b == 0)
                {

                        return ErrorStrings[3].ToString();
                }
                // Return PI/2 if x is equal to zero and y is positive
                if (a == 0 && b > 0) return (Math.PI / 2).ToString();

                // Return -PI/2 if x is equal to zero and y is negative
                if (a == 0 && b < 0) return (-Math.PI / 2).ToString();

                // Return zero if x is negative and y is equal to zero
                if (b == 0 && a > 0) return "0";

                // Return zero if x is negative and y is equal to zero
                if (b == 0 && a < 0) return (-Math.PI).ToString();

                // Return argument of complex number
                if (a > 0)
                {
                    return (Math.Atan(b / a).ToString());
                }
                else if (a < 0 && b >= 0)
                {
                    return (Math.Atan(b / a) + Math.PI).ToString();
                }
                else
                {
                    return (Math.Atan(b / a) - Math.PI).ToString();
                }
            }
            catch (Exception)
            {
                return this.ErrorStrings[4].ToString();
            }
        }

        /// <summary>
        /// Returns the absolute value (modulus) of a complex number in x + yi or x + yj text format.
        /// </summary>
        /// <param name="argList">Input Complex Number</param>
        /// <returns>The absolute value (modulus) of given complex number</returns>
        public string ComputeImABS(string argList)
        {
            string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
            string result = this.GetValueFromArg(ranges[0]);
            result = result.Replace(this.TIC, "");
            if (ranges.Length > 1)
            {
                    return FormulaErrorStrings[25].ToString();
            }

            string x = ComputeReal(result);
            string y = ComputeImaginary(result);
            // Return error if either coefficient is not a number
            if (x == ErrorStrings[4].ToString() || y == ErrorStrings[4].ToString())
            {

                    return ErrorStrings[4].ToString();
            }
            try
            {
                // Return absolute value of complex number
                return Math.Sqrt(Math.Pow(int.Parse(x), 2) + Math.Pow(int.Parse(y), 2)).ToString();
            }
            catch (Exception)
            {
                    if (ComputeIsText(result) == TRUEVALUESTR)
                        return ErrorStrings[5].ToString();
                    else if (result == "")
                        return ErrorStrings[1].ToString();
                    else
                        return this.ErrorStrings[1].ToString();
            }
        }

        /// <summary>
        /// Returns the Square Root of the given Complex Number.
        /// </summary>
        /// <param name="argList">Input Complex Number</param>
        /// <returns>The Square Root of the given Complex Number.</returns>
        public string ComputeImSqrt(string argList)
        {
            string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
            string result = this.GetValueFromArg(ranges[0]);
            result = result.Replace(this.TIC, string.Empty);
            string x = ComputeReal(result);
            string y = ComputeImaginary(result);

            // Lookup imaginary unit
            string unit = result.Substring(result.Length - 1);
            unit = (unit == "i" || unit == "j") ? unit : "i";

            // Return error if either coefficient is not a number
            if (x == ErrorStrings[4].ToString() || y == ErrorStrings[4].ToString())
            {
                    return ErrorStrings[4].ToString();
            }
            try
            {
                string r = (Math.Sqrt((double.Parse(x) * double.Parse(x)) + (double.Parse(y) * double.Parse(y)))).ToString();
                string b = (Math.Sqrt((double.Parse(r) - double.Parse(x)) / 2)).ToString();
                string a = (double.Parse(y) / (2 * double.Parse(b))).ToString();

                string args = a + ParseArgumentSeparator + b;
                return ComputeComplex(args);
            }

            catch (Exception)
            {
                    if (ComputeIsText(result) == TRUEVALUESTR)
                        return ErrorStrings[5].ToString();
                    else if (result == "")
                        return ErrorStrings[1].ToString();

                    else
                        return this.ErrorStrings[1].ToString();
            }
        }

        /// <summary>
        /// Returns the Hyperbolic Sine value of the given Complex Number.
        /// </summary>
        /// <param name="argList">Input Complex Number</param>
        /// <returns>The Hyperbolic Sine Value of the given Complex Number.</returns>
        public string ComputeImSinH(string argList)
        {
            string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
            string result = this.GetValueFromArg(ranges[0]);
            result = result.Replace(this.TIC, "");

            // Return error if inumber is a logical value
            //if (result == true || result == false) return "#VALUE!";


            string x = ComputeReal(result);
            string y = ComputeImaginary(result);
            try
            {
                // Return error if either coefficient is not a number
                if (x == ErrorStrings[4].ToString() || y == ErrorStrings[4].ToString())
                {
                        return ErrorStrings[1].ToString();
                }


                // Lookup imaginary unit
                string unit = result.Substring(result.Length - 1);
                unit = (unit == "i" || unit == "j") ? unit : "i";


                int a = int.Parse(x);
                int b = int.Parse(y);

                double r1 = Math.Cos(b) * ((Math.Exp(a) - Math.Exp(-a)) / 2);
                double r2 = Math.Sin(b) * (Math.Exp(a) + Math.Exp(-a)) / 2;

                string args = r1.ToString() + ParseArgumentSeparator + r2.ToString();

                return ComputeComplex(args);
            }
            catch (Exception)
            {
                    if (ComputeIsText(result) == TRUEVALUESTR)
                        return ErrorStrings[1].ToString();
                    else if (result == "")
                        return ErrorStrings[4].ToString();
                    else if (double.Parse(result) < 0)
                        return ErrorStrings[5].ToString();
                    else
                        return this.ErrorStrings[1].ToString();
            }

        }

