        /// <summary>
        /// Returns the Exponent of the given Complex Number.
        /// </summary>
        /// <param name="argList">Input Complex Number</param>
        /// <returns>The Exponent of the given Complex Number.</returns>
        public string ComputeImEXP(string argList)
        {
            string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
            string result = this.GetValueFromArg(ranges[0]);
            result = result.Replace(this.TIC, "");

            // Return error if inumber is a logical value
            if (result == "true" || result == "false") return "#VALUE!";

            string x = ComputeReal(result);
            string y = ComputeImaginary(result);

            // Lookup imaginary unit
            string unit = result.Substring(result.Length - 1);
            unit = (unit == "i" || unit == "j") ? unit : "i";

            try
            {
                // Return error if either coefficient is not a number
                if (x == ErrorStrings[4].ToString() || y == ErrorStrings[4].ToString())
                {
                    return ErrorStrings[4].ToString();
                }
                double a = double.Parse(x);
                double b = double.Parse(y);

                double e = Math.Exp(a);

                double r1 = e * Math.Cos(b);
                double r2 = e * Math.Sin(b);

                string args = r1.ToString() + ParseArgumentSeparator + r2.ToString() + ParseArgumentSeparator + unit;
                // Return sine of complex number
                return ComputeComplex(args);
            }

            catch
            {
                if (ComputeIsText(result) == TRUEVALUESTR)
                    return ErrorStrings[5].ToString();
                else if (result == "")
                    return ErrorStrings[1].ToString();
                else if (double.Parse(result) < 0)
                    return ErrorStrings[4].ToString();
                else
                    return this.ErrorStrings[1].ToString();
            }
        }

