        /// Returns the error function .
        /// </summary>
        /// <param name="argList">Input Number</param>
        /// <returns>The error function.</returns>
        public string ComputeErfPrecise(string argList)
        {
            string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
            string result = this.GetValueFromArg(ranges[0]);
            if (ranges.Length > 1)
            {               
                    return FormulaErrorStrings[10].ToString();
            }
            try
            {
                double a1 = 0.254829592;
                double a2 = -0.284496736;
                double a3 = 1.421413741;
                double a4 = -1.453152027;
                double a5 = 1.061405429;
                double p = 0.3275911;
                double x = double.Parse(result);
                // Save the sign of x
                int sign = 1;
                if (x < 0)
                    sign = -1;
                x = Math.Abs(x);

                // A&S formula 7.1.26
                double t = 1.0 / (1.0 + p * x);
                double y = 1.0 - ((((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * Math.Exp(-x * x));
                return (sign * y).ToString();
            }
            catch
            {                
                    if (ComputeIsText(result) == TRUEVALUESTR)
                        return ErrorStrings[5].ToString();
                    else if (result == "")
                        return ErrorStrings[1].ToString();
                    else
                        return this.ErrorStrings[1].ToString();
            }
        }

