        public string ComputeBesselI(string argList)
        {
            string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
            string x = null, n = null;
            if (ranges.Length > 2 || ranges.Length <= 1)
                return FormulaErrorStrings[13].ToString();
            else
            {
                x = GetValueFromArg(ranges[0]);
                x = x.Replace(this.TIC, "");
                n = GetValueFromArg(ranges[1]);
                n = n.Replace(this.TIC, "");
            }

            try
            {
                if (double.Parse(x) == 0.0)
                {
                    return "0.0";
                }
                else
                {
                    double tox = 2.0 / Math.Abs(double.Parse(x));
                    double ans = 0.0;
                    double bip = 0.0;
                    double bi = 1.0;
                    for (double j = 2 * (double.Parse(n) + Math.Sqrt(ACC * double.Parse(n))); j > 0; --j)
                    {
                        double bim = bip + j * tox * bi;
                        bip = bi;
                        bi = bim;
                        if (Math.Abs(bi) > BIGNO)
                        {
                            ans *= BIGNI;
                            bi *= BIGNI;
                            bip *= BIGNI;
                        }
                        string temp = ComputeRound(j.ToString());
                        string n1 = ComputeRound(n);
                        if (temp == n1)
                        {
                            ans = bip;
                        }
                    }
                    ans *= besseli0(double.Parse(x)) / bi;
                    if (double.IsInfinity(ans))
                        return ErrorStrings[4].ToString();
                    else
                        return (((double.Parse(x) < 0.0) && ((int.Parse(n) % 2) == 0)) ? -ans : ans).ToString();
                }
            }
            catch (Exception)
            {
                if (ComputeIsText(x) == TRUEVALUESTR || ComputeIsText(n) == TRUEVALUESTR)
                    return ErrorStrings[5].ToString();
                else if (x == "" || n == "")
                    return ErrorStrings[1].ToString();
                else if (double.Parse(x) < 0 || double.Parse(n) < 0)
                    return ErrorStrings[4].ToString();
                else
                    return this.ErrorStrings[1].ToString();
            }

        }

