        ///<summary>
        /// Returns the BesselJ function of order n of the specified number.
        /// </summary>
        /// <param name="argList">Input Number</param>
        /// <returns>The BesselJ of the Number.</returns>
        public string ComputeBesselJ(string argList)
        {
            string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
            string result, n;
            if (ranges.Length == 2)
            {
                result = this.GetValueFromArg(ranges[0]);
                result = result.Replace(this.TIC, "");
                n = this.GetValueFromArg(ranges[1]);
                n = n.Replace(this.TIC, "");
            }
            else
                if (ranges.Length == 1)
                {
                    result = this.GetValueFromArg(ranges[0]);
                    n = "0";
                }
                else
                    return FormulaErrorStrings[10].ToString();

            double j, m;
            double ax, bj, bjm, bjp, sum, tox, ans;
            bool jsum;

            double ACC = 40.0;
            double BIGNO = 1.0e+10;
            double BIGNI = 1.0e-10;
            try
            {
                if (double.Parse(n) == 0) return j0(result).ToString();
                if (double.Parse(n) == 1) return j1(result).ToString();

                ax = Math.Abs(double.Parse(result));
                if (ax == 0.0) return "0";
                else if (ax > double.Parse(n))
                {
                    tox = 2.0 / ax;
                    bjm = j0(ax.ToString());
                    bj = j1(ax.ToString());
                    for (j = 1; j < double.Parse(n); j++)
                    {
                        bjp = j * tox * bj - bjm;
                        bjm = bj;
                        bj = bjp;
                    }
                    ans = bj;
                }
                else
                {
                    tox = 2.0 / ax;

                    m = 2 * (double.Parse(n) + (int)Math.Sqrt(ACC * double.Parse(n)) / 2);
                    jsum = false;
                    bjp = ans = sum = 0.0;
                    bj = 1.0;
                    for (j = m; j > 0; j--)
                    {
                        bjm = j * tox * bj - bjp;
                        bjp = bj;
                        bj = bjm;
                        if (Math.Abs(bj) > BIGNO)
                        {
                            bj *= BIGNI;
                            bjp *= BIGNI;
                            ans *= BIGNI;
                            sum *= BIGNI;
                        }
                        if (jsum) sum += bj;
                        jsum = !jsum;
                        string temp = ComputeRound(j.ToString());
                        string n1 = ComputeRound(n);
                        if (temp == n1) ans = bjp;
                    }
                    sum = 2.0 * sum - bj;

                    ans /= sum;
                }
                return (double.Parse(result) < 0.0 && double.Parse(n) % 2 == 1 ? -ans : ans).ToString();
            }
            catch (Exception)
            {                
                    if (ComputeIsText(result) == TRUEVALUESTR || ComputeIsText(n) == TRUEVALUESTR)
                        return ErrorStrings[5].ToString();
                    else if (result == "" || n == "")
                        return ErrorStrings[1].ToString();
                    else if (double.Parse(result) < 0 || double.Parse(n) < 0)
                        return ErrorStrings[4].ToString();
                    else
                        return this.ErrorStrings[1].ToString();
            }

        }

        /// <summary>
        /// Returns the Bessel function of order 1 of the specified number.
        /// </summary>
        /// <param name="x"></param>
        /// <returns></returns>
        public static double j1(string x)
        {
            double ax;
            double y;
            double ans1, ans2;

            if ((ax = Math.Abs(double.Parse(x))) < 8.0)
            {
                y = double.Parse(x) * double.Parse(x);
                ans1 = double.Parse(x) * (72362614232.0 + y * (-7895059235.0 + y * (242396853.1
                    + y * (-2972611.439 + y * (15704.48260 + y * (-30.16036606))))));
                ans2 = 144725228442.0 + y * (2300535178.0 + y * (18583304.74
                    + y * (99447.43394 + y * (376.9991397 + y * 1.0))));
                return ans1 / ans2;
            }
            else
            {
                double z = 8.0 / ax;
                double xx = ax - 2.356194491;
                y = z * z;

                ans1 = 1.0 + y * (0.183105e-2 + y * (-0.3516396496e-4
                    + y * (0.2457520174e-5 + y * (-0.240337019e-6))));
                ans2 = 0.04687499995 + y * (-0.2002690873e-3
                    + y * (0.8449199096e-5 + y * (-0.88228987e-6
                    + y * 0.105787412e-6)));
                double ans = Math.Sqrt(0.636619772 / ax) *
                    (Math.Cos(xx) * ans1 - z * Math.Sin(xx) * ans2);
                if (double.Parse(x) < 0.0) ans = -ans;
                return ans;
            }
        }


        /// <summary>
        /// Returns the Bessel function of order 0 of the specified number.
        /// </summary>
        /// <param name="x"></param>
        /// <returns></returns>
        public static double j0(string x)
        {
            double ax;

            if ((ax = Math.Abs(double.Parse(x))) < 8.0)
            {
                double y = double.Parse(x) * double.Parse(x);
                double ans1 = 57568490574.0 + y * (-13362590354.0 + y * (651619640.7
                    + y * (-11214424.18 + y * (77392.33017 + y * (-184.9052456)))));
                double ans2 = 57568490411.0 + y * (1029532985.0 + y * (9494680.718
                    + y * (59272.64853 + y * (267.8532712 + y * 1.0))));

                return ans1 / ans2;

            }
            else
            {
                double z = 8.0 / ax;
                double y = z * z;
                double xx = ax - 0.785398164;
                double ans1 = 1.0 + y * (-0.1098628627e-2 + y * (0.2734510407e-4
                    + y * (-0.2073370639e-5 + y * 0.2093887211e-6)));
                double ans2 = -0.1562499995e-1 + y * (0.1430488765e-3
                    + y * (-0.6911147651e-5 + y * (0.7621095161e-6
                    - y * 0.934935152e-7)));

                return Math.Sqrt(0.636619772 / ax) *
                    (Math.Cos(xx) * ans1 - z * Math.Sin(xx) * ans2);

            }
        }


        ///<summary>
        /// Returns the BesselY function of order n of the specified number.
        /// </summary>
        /// <param name="argList">Input Number</param>
        /// <returns>The BesselY of the Number.</returns>
        public string ComputeBesselY(string argList)
        {
            string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
            string result, n;
            if (ranges.Length == 2)
            {
                result = this.GetValueFromArg(ranges[0]);
                result = result.Replace(this.TIC, "");
                n = this.GetValueFromArg(ranges[1]);
                n = n.Replace(this.TIC, "");
            }
            else
                if (ranges.Length == 1)
                {
                    result = this.GetValueFromArg(ranges[0]);
                    n = "0";
                }
                else
                    return FormulaErrorStrings[10].ToString();
            try
            {
                double by, bym, byp, tox;

                if (double.Parse(result) == 0) return y0(double.Parse(result)).ToString();
                if (double.Parse(n) == 1) return y1(double.Parse(result)).ToString();

                tox = 2.0 / double.Parse(result);
                by = y1(double.Parse(result));
                bym = y0(double.Parse(result));
                for (int j = 1; j < double.Parse(n); j++)
                {
                    byp = j * tox * by - bym;
                    bym = by;
                    by = byp;
                }
                return by.ToString();
            }

            catch (Exception)
            {               
                    if (ComputeIsText(result) == TRUEVALUESTR || ComputeIsText(n) == TRUEVALUESTR)
                        return ErrorStrings[5].ToString();
                    else if (result == "" || n == "")
                        return ErrorStrings[1].ToString();
                    else if (double.Parse(result) < 0 || double.Parse(n) < 0)
                        return ErrorStrings[4].ToString();
                    else
                        return this.ErrorStrings[1].ToString();
            }
        }
        /// <summary>
        /// Returns the Bessel function of the second kind, of order 0 of the specified number.
        /// </summary>
        /// <param name="x"></param>
        /// <returns></returns>
        public static double y0(double x)
        {
            if (x < 8.0)
            {
                double y = x * x;
                double ans1 = -2957821389.0 + y * (7062834065.0 + y * (-512359803.6
                    + y * (10879881.29 + y * (-86327.92757 + y * 228.4622733))));
                double ans2 = 40076544269.0 + y * (745249964.8 + y * (7189466.438
                    + y * (47447.26470 + y * (226.1030244 + y * 1.0))));

                return (ans1 / ans2) + 0.636619772 * j0(x.ToString()) * Math.Log(x);
            }
            else
            {
                double z = 8.0 / x;
                double y = z * z;
                double xx = x - 0.785398164;

                double ans1 = 1.0 + y * (-0.1098628627e-2 + y * (0.2734510407e-4
                    + y * (-0.2073370639e-5 + y * 0.2093887211e-6)));
                double ans2 = -0.1562499995e-1 + y * (0.1430488765e-3
                    + y * (-0.6911147651e-5 + y * (0.7621095161e-6
                    + y * (-0.934945152e-7))));
                return Math.Sqrt(0.636619772 / x) *
                    (Math.Sin(xx) * ans1 + z * Math.Cos(xx) * ans2);
            }
        }


        /// <summary>
        /// Returns the Bessel function of the second kind, of order 1 of the specified number.
        /// </summary>
        /// <param name="x"></param>
        /// <returns></returns>
        public static double y1(double x)
        {
            if (x < 8.0)
            {
                double y = x * x;
                double ans1 = x * (-0.4900604943e13 + y * (0.1275274390e13
                    + y * (-0.5153438139e11 + y * (0.7349264551e9
                    + y * (-0.4237922726e7 + y * 0.8511937935e4)))));
                double ans2 = 0.2499580570e14 + y * (0.4244419664e12
                    + y * (0.3733650367e10 + y * (0.2245904002e8
                    + y * (0.1020426050e6 + y * (0.3549632885e3 + y)))));
                return (ans1 / ans2) + 0.636619772 * (j1(x.ToString()) * Math.Log(x) - 1.0 / x);
            }
            else
            {
                double z = 8.0 / x;
                double y = z * z;
                double xx = x - 2.356194491;
                double ans1 = 1.0 + y * (0.183105e-2 + y * (-0.3516396496e-4
                    + y * (0.2457520174e-5 + y * (-0.240337019e-6))));
                double ans2 = 0.04687499995 + y * (-0.2002690873e-3
                    + y * (0.8449199096e-5 + y * (-0.88228987e-6
                    + y * 0.105787412e-6)));
                return Math.Sqrt(0.636619772 / x) *
                    (Math.Sin(xx) * ans1 + z * Math.Cos(xx) * ans2);
            }
        }


