        #region Processing Arguments

        private string ZapQuotedColons(string s)
        {
            int start = s.IndexOf(TIC);
            while (start > -1)
            {
                int end = s.Substring(start + 1).IndexOf(TIC);
                if (end > -1)
                {
                    int i = s.Substring(start + 1).IndexOf(':');
                    while (i > -1 && i < end)
                    {
                        s = s.Substring(i + start) + " " + s.Substring(i + start + 1);
                        i = s.Substring(start + 1).IndexOf(':');
                    }
                }

                start = end;
            }

            return s;
        }

        private char MarkerChar = '`';

        private void MarkColonsInQuotes(ref string args)
        {
            bool inQuotes = false;
            for (int i = 0; i < args.Length; ++i)
            {
                if (args[i] == TIC[0])
                {
                    inQuotes = !inQuotes;
                }
                else if (args[i] == ':' && inQuotes)
                {
                    args = args.Replace(':', MarkerChar);
                }
            }
        }

        /// <summary>
        /// Accepts an argument string and returns a string array of cells.
        /// </summary>
        /// <remarks>
        ///    Converts arguments in these forms to a string array of individual cells.<para/>
        ///        A1,A2,B4,C1,...,D8<para/>
        ///        A1:A5<para/>
        ///        A1:C5<para/>
        /// </remarks>
        /// <param name="args">String containing a cell range.</param>
        /// <returns>String array of cells.</returns>
        public string[] GetCellsFromArgs(string args)
        {
            RemoveQuotesOnSingleRange(ref args);
            MarkColonsInQuotes(ref args);

            int row1;
            int col1;

            int i = args.IndexOf(':');
            if (i == -1)
            {
                args = args.Replace(MarkerChar, ':');
                i = args.IndexOf(ParseArgumentSeparator);
                if (i == -1)
                {
                    int l, initial = 0;
                    for (l = 0; l < args.Length; l++)
                    {
                        if (args[l].Equals(TIC))
                        {
                            l++;
                            initial = 0;
                            while (l < args.Length && args[l] != TIC[0])
                            {
                                l++;
                            }
                        }
                        if (l < args.Length)
                        {
                            if (!Char.IsUpper(args, l))
                                continue;
                            else
                                initial = l;
                        }
                    }
                    string subarg = string.Empty;
                    for (int final = args.Length; final >= 0; final--)
                    {
                        subarg = args.Substring(initial, final - initial);
                        if (!this.IsCellReference(subarg))
                            continue;
                        break;
                    }
                    //row1 = RowIndex(args); ////maybe throw exception
                    //col1 = ColIndex(args); ////maybe throw exception
                    row1 = RowIndex(subarg);
                    col1 = ColIndex(subarg);
                    return new string[] { args };
                }
                else
                {
                    return SplitArguments(args, ParseArgumentSeparator);
                }
            }

            string sheet = string.Empty;
            int j = args.IndexOf(sheetToken);
            if (j > -1)
            {
                int j1 = args.IndexOf(sheetToken, j + 1);
                if (j1 > -1)
                {
                    sheet = args.Substring(j, j1 + 1);
                    args = args.Replace(sheet, string.Empty);
                    i = args.IndexOf(':');
                }
            }

            row1 = RowIndex(args.Substring(0, i));
            col1 = ColIndex(args.Substring(0, i));

            string subargs = args.Substring(i + 1, args.Length - i - 1);
            string sub = subargs;
            int first = 0;
            for (first = 0; first < subargs.Length; first++)
            {
                if (!Char.IsUpper(subargs, first))
                    continue;
                break;
            }
            for (int last = subargs.Length; last >= 0; last--)
            {
                sub = subargs.Substring(first, last - first);
                if (!this.IsCellReference(sub))
                    continue;
                break;
            }
            int row2 = RowIndex(sub);
            int col2 = ColIndex(sub);
            //int row2 = RowIndex(args.Substring(i + 1, args.Length - i - 1));
            //int col2 = ColIndex(args.Substring(i + 1, args.Length - i - 1));

            if (row1 > row2)
            {
                i = row2;
                row2 = row1;
                row1 = i;
            }

            if (col1 > col2)
            {
                i = col2;
                col2 = col1;
                col1 = i;
            }

            int numCells = (row2 - row1 + 1) * (col2 - col1 + 1);
            string[] cells = new String[numCells];
            int k = 0;
            for (i = row1; i <= row2; ++i)
            {
                for (j = col1; j <= col2; ++j)
                {
                    try
                    {
                        cells[k++] = sheet + GridRangeInfo.GetAlphaLabel(j) + i.ToString();
                    }
                    catch (Exception ex)
                    {
                        TraceUtil.TraceExceptionCatched(ex);
                        if (!ExceptionManager.RaiseExceptionCatched(this, ex))
                        {
                            throw ex;
                        }

                        continue;
                    }
                }
            }

            return cells;
        }

        public DataTable GetDataFromArgs(string args)
        {
