                    continue;
                break;
            }
            for (int last = subargs.Length; last >= 0; last--)
            {
                sub = subargs.Substring(first, last - first);
                if (!this.IsCellReference(sub))
                    continue;
                break;
            }
            int row2 = RowIndex(sub);
            int col2 = ColIndex(sub);           
            if (row1 > row2)
            {
                i = row2;
                row2 = row1;
                row1 = i;
            }

            if (col1 > col2)
            {
                i = col2;
                col2 = col1;
                col1 = i;
            }

            int numCells = (row2 - row1 + 1) * (col2 - col1 + 1);
            string[] cells = new String[numCells];
            int k = 0;
            for (i = row1; i <= row2; ++i)
            {
                for (j = col1; j <= col2; ++j)
                {
                    try
                    {
                        cells[k++] = sheet + GridRangeInfo.GetAlphaLabel(j) + i.ToString();
                    }
                    catch (Exception ex)
                    {
                        TraceUtil.TraceExceptionCatched(ex);
                        if (!ExceptionManager.RaiseExceptionCatched(this, ex))
                        {
                            throw ex;
                        }

                        continue;
                    }
                }
            }
            int lCount = col2;          
            for (i = 0; i < row2 - row1; ++i)
            {
                DataRow dr = dt.NewRow();
                dt.Rows.Add(dr);
                for (j = 0; j < col2; ++j)
                {
                    dt.Rows[i][j] = GetValueFromArg(cells[lCount]).Trim();
                    lCount++;
                }
            }
            return dt;
        }

