        /// <summary>
        /// Averages the values in a field (column) of records in a list or database that match conditions you specify.
        /// </summary>
        /// <param name="args">Number and the number of digits</param>
        /// <returns>Received amount</returns>
        public string ComputeDAverage(string args)
        {
            int DCount = 0;
            double avg = 0;
            try
            {

                string[] argsArray = args.Split(new char[] { ParseArgumentSeparator });
                if (argsArray.Length < 3)
                {                    
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }

                DataTable dt = GetDataFromArgs(argsArray[0]);
                string Field = argsArray[1];
                Field = GetColumnName(Field, dt);
                if (argsArray[0].Equals(argsArray[2]))
                {
                    string[] c = GetCellsFromArgs(argsArray[2]);
                    int endRow = this.RowIndex(c[0]);
                    int endCol = this.ColIndex(c[c.Length - 1]);
                    string endCols = GridRangeInfo.GetAlphaLabel(endCol);
                    string endRows = GridRangeInfo.GetAlphaLabel(1);
                    string reArgs = (string.Format("{0}{1}:{2}{3}", endRows, endRow - 2, endCols, endRow - 2));
                    argsArray[2] = reArgs;
                }
                StringBuilder sb = new StringBuilder();
                sb = GenerateCreteriaList(argsArray[2]);
                DataTable dtemp = new DataTable();
                dtemp = BindResultTable(sb, dt);
                DCount = dtemp.Rows.Count;
                double sum = 0;
                for (int i = 0; i < dtemp.Rows.Count; i++)
                {
                    double val = 0;
                    if (double.TryParse(dtemp.Rows[i][Field.Replace(TIC, string.Empty)].ToString(), NumberStyles.Any, CultureInfo.CurrentUICulture, out val))
                    {
                        sum = sum + val;
                    }
                }
                avg = sum / DCount;

            }
            catch (Exception ex)
            {
               
                return ex.Message;
            }
            return avg.ToString();

        }

