        #region Data Base Functions Common Method
        private string GetColumnName(string Field, DataTable dt)
        {
            int colIndex = 0;
            if (int.TryParse(Field, out colIndex))
                Field = dt.Columns[colIndex - 1].ColumnName;
            return Field;
        }

        private DataTable BindResultTable(StringBuilder sb, DataTable dt)
        {
            DataTable dtemp = new DataTable();
            dtemp = dt.Clone();
            DataRow[] dr = dt.Select(string.Format("{0}", sb));
            foreach (DataRow dresult in dr)
            {
                object[] row = dresult.ItemArray;
                dtemp.Rows.Add(row);
            }
            return dtemp;
        }

        private bool CheckOperands(string data)
        {
            string[] pattern = { "<", ">", "=" };
            int i = pattern.Length - 1;
            while (i >= 0)
            {
                if (data.Substring(0, 1).IndexOf(pattern[i]) != -1)
                    return true;
                i--;
            }
            return false;
        }

        //used to set the datatype of column
        private DataTable ClonedTable(DataTable dt)
        {
            //Dictionary<string, int> type = new Dictionary<string, int>();
            DataTable dtCloned = new DataTable();
            for (int Col = 0; Col < dt.Columns.Count; Col++)
            {
                bool hasString = false, hasInt = false, hasDouble = false, hasDecimal = false, hasDate = false, hasTime = false;
                for (int Rows = 0; Rows < dt.Rows.Count; Rows++)
                {
                    string str = dt.Rows[Rows][Col].ToString();
                    TimeSpan ts;
                    DateTime date;
                    int val;
                    decimal dec;
                    double dou;
                    if (int.TryParse(str, out val) && !hasDate && !hasTime && !hasDouble && !hasDecimal && !hasString)
                    {
                        hasInt = true;
                    }
                    else if (TimeSpan.TryParse(str, out ts) && !hasDate && !hasInt && !hasDouble && !hasDecimal && !hasString)
                    {
                        hasTime = true;
                    }
                    else if (DateTime.TryParse(str, out date) && !hasTime && !hasInt && !hasDouble && !hasDecimal && !hasString)
                    {
                        hasTime = false;
                        hasDate = true;
                    }
                    else if (double.TryParse(str, out dou) && !hasDate && !hasInt && !hasTime && !hasDecimal && !hasString)
                    {
                        hasInt = false;
                        hasDouble = true;
                    }
                    else if (decimal.TryParse(str, out dec) && !hasDate && !hasInt && !hasDouble && !hasTime && !hasString)
                    {
                        hasInt = false;
                        hasDecimal = true;
                    }
                    else
                    {
                        hasDate = false;
                        hasInt = false;
                        hasDouble = false;
                        hasTime = false;
                        hasDecimal = false;
                        hasString = true;
                    }
                }

                if (hasInt && !hasString)
                    dtCloned.Columns.Add(dt.Columns[Col].ColumnName, typeof(int));
                else if (hasTime && !hasString)
                    dtCloned.Columns.Add(dt.Columns[Col].ColumnName, typeof(TimeSpan));
                else if (hasDate && !hasString)
                    dtCloned.Columns.Add(dt.Columns[Col].ColumnName, typeof(DateTime));
                else if (hasDouble && !hasString)
                    dtCloned.Columns.Add(dt.Columns[Col].ColumnName, typeof(double));
                else if (hasDecimal && !hasString)
                    dtCloned.Columns.Add(dt.Columns[Col].ColumnName, typeof(decimal));
                else
                    dtCloned.Columns.Add(dt.Columns[Col].ColumnName, typeof(string));
            }

            foreach (DataRow row in dt.Rows)
            {
                dtCloned.ImportRow(row);
            }
            return dtCloned;
        }

        private StringBuilder GenerateCreteriaList(string args)
        {

#if _ENABLETIMERS
            string ML = "GenerateCreteria"; MarkTimeStart(ML);
#endif
            this.MarkColonsInQuotes(ref args);

            int row1;
            int col1;

            int i = args.IndexOf(':');

            string sheet = string.Empty;
            string argsRet = args;
            int j = args.IndexOf(sheetToken);
            if (j > -1)
            {
                int j1 = args.IndexOf(sheetToken, j + 1);
                if (j1 > -1)
                {
                    sheet = args.Substring(j, j1 - j + 1);
                    args = args.Replace(sheet, string.Empty);
                    i = args.IndexOf(':');
                }
            }
         

            // Check Whether rowindex can get from the arguments
            bool isDigit = CanGetRowIndex(args.Substring(0, i));
            row1 = this.RowIndex(args.Substring(0, i));
            int row2 = this.RowIndex(args.Substring(i + 1, args.Length - i - 1));
            string[] errorStr = new String[1];
            if (!(!row1.Equals(-1) || row2.Equals(-1)).Equals((row1.Equals(-1) || !row2.Equals(-1))))
            {

                throw new ArgumentException(this.ErrorStrings[5].ToString());
            }
            if (row1 == -1)
            {
                row1 = 1;
            }
            col1 = this.ColIndex(args.Substring(0, i));
            if (row2 == -1)
            {
                row2 = this.grid.Model.RowCount;
            }
            int col2 = this.ColIndex(args.Substring(i + 1, args.Length - i - 1));

            if (row1 > row2)
            {
                i = row2;
                row2 = row1;
                row1 = i;
            }

            if (col1 > col2)
            {
                i = col2;
                col2 = col1;
                col1 = i;
            }

            int numCells = (row2 - row1 + 1) * (col2 - col1 + 1);
            string[] cells = new String[numCells];

            return getCreteriaList_new(row1, row2, col1, col2, sheet);

        }

        internal StringBuilder getCreteriaList_new(int row1, int row2, int col1, int col2, string sheet)
        {
            StringBuilder sb = new StringBuilder();
            for (int j = row1 + 1; j <= row2; ++j)
            {
                if (sb.Length > 0)
                {
                    sb.Append(" OR ");
                }
                for (int i = col1; i <= col2; ++i)
                {

                    string colName = GetValueFromArg(sheet + GridRangeInfo.GetAlphaLabel(i) + row1.ToString());
                    string str = GetValueFromArg(sheet + GridRangeInfo.GetAlphaLabel(i) + j.ToString());
                    if (!string.IsNullOrEmpty(str))
                    {
                        if (i > col1)
                        {
                            sb.Append(" AND ");
                        }
                        if (!CheckOperands(str))
                        {
                            string s = str;
                            if (str.Contains("="))
                                s = s.Replace("=", string.Empty);
                            if (str.Contains(this.TIC))
                                s = s.Replace(this.TIC, string.Empty);
                            double d = 0;
                            if (double.TryParse(s, out d))
                            {
                                sb.Append(string.Format("{0}={1}", colName, str));
                            }
                            else
                            {
                                if (s.Contains("<") || s.Contains(">"))
                                {
                                    sb.Append(string.Format("{0} {1}", colName, str));
                                }
                                else
                                {
                                    sb.Append(string.Format("{0}='{1}'", colName, str));
                                }
                            }
                        }
                        else
                        {
                            sb.Append(string.Format("{0} {1}", colName, str));

                        }
                    }
                }
            }
            return sb;
        }

         /// <summary>
         /// To check whether the row index can be obtained from the arguments
         /// </summary>
         private bool CanGetRowIndex(string s)
         {
             int i = 0;
             if (i < s.Length && s[i] == sheetToken)
             {
                 i++;
                 while (i < s.Length && s[i] != sheetToken)
                 {
                     i++;
                 }
                 i++;
             }

             while (i < s.Length && char.IsLetter(s[i]))
             {
                 i++;
             }

             if (i < s.Length)
             {
                 if (char.IsDigit(s[i]))
                     return true;
                 else
                     return false;
             }
             return false;
         }
     
