        bool treatStringsAsZero = false;

        /// <summary>
        /// Gets of sets whether the FormulaEngine treats nonempty strings as zeros when they are
        /// encountered during calculations.
        /// </summary>
        /// <remarks>
        /// The default value is false meaning that if a nonempty string is encountered during an arithmetic operation, it will be treated as zero.
        /// </remarks>
        public bool TreatStringsAsZero
        {
            get { return treatStringsAsZero; }
            set { treatStringsAsZero = value; }
        }
        ////max calculation stack depth
        private int maxStackDepth = 100;

        /// <summary>
        /// Gets or sets depth of the engine's calculation stack.
        /// </summary>
        /// <remarks>
        /// It is unlikely that you will need to adjust this value, as
        /// its default value of 100 is quite large.
        /// Any time a formula is to be computed, a Stack object is created
        /// with this number of elements to hold temporary calculations
        /// as the formula is being computed. 
        /// For example, this formula: 1+1+1+...+1 requires a stack 
        /// depth of 2 as there are only 2 temporary values needed as the 
        /// formula is evaluated. However, this formula: 1+(1+(1+(1+1)))
        /// requires a depth of 5, as the five 1's are pushed onto the 
        /// stack before the first addition (the right-most one) is
        /// performed.
        /// </remarks>
        public int MaximumStackDepth
        {
            get { return maxStackDepth; }
            set { maxStackDepth = value; }
        }

        private int computedValueLevel = 0;

        [ThreadStaticAttribute]
        private static GridFormulaEngine functionEngineContext = null;

        /// <summary>
        /// Gets the formula engine that holds the proper state information for LibraryFunction call.
        /// </summary>
        /// <remarks>
        /// If you are adding your own custom library functions and need to access GridFormulaEngine members like
        /// GetCellsFromArgs or GetValueFromArg from your code, then you should use this static property to retrieve the proper
        /// GridFormulaEngine object. This only matters if you are using multiple grids that you have registered using
        /// RegisterGridAsSheet, and are adding your own custom formulas. Note that GridFormulaEngine.FunctionEngineContext
        /// is only defined within the scope of a library function call, and will be null at all other times.
        /// </remarks>
        /// <example> Use GridFormulaEngine.FunctionEngineContext to retrieve the engine 
        /// when writing custom functions.
        /// <code lang="C#">
        /// public string ComputeSumPosNums(string args)
        /// {
        ///     GridFormulaEngine engine = GridFormulaEngine.FunctionEngineContext;
        ///     string sum = string.Empty;
        ///     foreach(string r in args.Split(new char[]{','}))
        ///     {
        ///         if(r.IndexOf(':') > -1) //is a cellrange
        ///         {
        ///             foreach(string s in engine.GetCellsFromArgs(r))
        ///             {
        ///                 s1 = engine.GetValueFromArg(s).Replace("'",string.Empty);
        ///                 //... do some calculations to compute sum
        ///             }
        ///         }
        ///     }    
        ///     return sum.ToString();
        /// }
        /// </code>
        /// <code lang="VB">
        /// Public Function ComputeSumPosNums(args As String) As String
        ///    Dim engine As GridFormulaEngine = GridFormulaEngine.FunctionEngineContext
        ///    Dim sum As String = string.Empty
        ///    Dim r As String
        ///    For Each r In  args.Split(New Char() {","c})
        ///            If r.IndexOf(":"c) > - 1 Then 'is a cellrange
        ///                Dim s As String
        ///                For Each s In  engine.GetCellsFromArgs(r)
        ///                    s1 = engine.GetValueFromArg(s).Replace("'", string.Empty)
        ///                    '... do some calculations to compute sum
        ///                Next s 
        ///            End If
        ///    Next r
        ///    Return sum.ToString()
        /// End Function 'ComputeSumPosNums
        /// </code>
        /// </example>
        public static GridFormulaEngine FunctionEngineContext
        {
            get { return functionEngineContext; }
        }

        private string activeFunctionName;

        /// <summary>
        /// Gets the function name of the active function call. Empty if not in a call.
        /// </summary>
        public string ActiveFunctionName
        {
            get { return activeFunctionName; }
        }

        /// <summary>
        /// Computes the value of a parsed formula.
        /// </summary>
        /// <param name="formula">The formula to be computed.</param>
        /// <returns>A string holding the computed value.</returns>
        /// <remarks> 
        ///  The string passed into ComputedValue must have been parsed using the Parse
        ///  method. Before calling the method, you should set FormulaContextCell
        ///  to properly reflect which cell owns this formula.
        /// </remarks>
        public string ComputedValue(string formula)
        {
            return ComputedValue(formula, null);
        }

        internal void GetCellsInArgs(ArrayList circCheckList, string args)
        {
            foreach (string r in args.Split(new char[] { ParseArgumentSeparator }))
            {
                if (r.IndexOf(':') > -1)
                {
                    ////is a cellrange
                    foreach (string s in GetCellsFromArgs(r))
                    {
                        circCheckList.Add(s);
                    }
                }
                else
                {
                    if (r.Length > 2 && r[0] == BMARKER && r[r.Length - 1] == BMARKER)
                    {
                        this.ComputedValue(r, circCheckList);
                    }
                    else if (r.Length > 2 && char.IsUpper(r[0]) && char.IsDigit(r[r.Length - 1]))
                    {
                        circCheckList.Add(r);
                    }
                }
            }
        }

        internal string ComputedValue(string formula, ArrayList circCheckList)
        {
#if DEBUG
            if (Switches.FormulaCell.TraceVerbose)
            {
                TraceUtil.TraceCurrentMethodInfo(formula, computedValueLevel, this);
            }
#else
            ;
#endif
            if (GridUtil.IsEmpty(formula))
            {
                return formula;
            }

            try
            {
                computedValueLevel++;

                if (computedValueLevel > maximumRecursiveCalls)
                {
                    computedValueLevel = 0;
                    if (circCheckList != null)
                    {
                        circCheckList.Add(this.cell);
                        return "0";
                    }

                    throw new ArgumentException(FormulaErrorStrings[too_complex]);
                }

                Stack _stack = new Stack(maxStackDepth);

                int i = 0;
                _stack.Clear();
                string sheet = string.Empty;

                if (AllowShortCircuitIFs)
                {
                    ////code replaces all IF functions with just the proper alternative 
                    while (i < formula.Length && (i = formula.IndexOf(IFMarker, i)) > -1)
                    {
                        int loc = MatchingRightBracket(formula.Substring(i));
                        if (loc > -1)
                        {
                            ////Console.WriteLine("  " + formula);
                            formula = formula.Substring(0, i) + HandleEmbeddedIf(formula.Substring(i)) + formula.Substring(i + loc + 1);
                            //// Console.WriteLine("      " + formula);
                        }

                        i++;
                    }
                }

                i = 0;
                if (formula.Equals("#NAME?"))
                {
                    _stack.Push("#NAME?");
                    i = formula.Length;
                }

                while (i < formula.Length)
                {
                    if (formula[i] == BMARKER)
                    {
                        i = i + 1;
                        continue;
                    }

                    bool uFound = formula[i] == 'u';
                    if (uFound)
                    {
                        i++;
                        if (i >= formula.Length)
                        {
                            continue; ////error case....
                        }
                    }

                    if (formula[i] == '%' && _stack.Count > 0)
                    {
                        object o = _stack.Peek();
                        double d;
                        if (double.TryParse(o.ToString(), out d))
                        {
                            _stack.Pop(); ////remove it
                            _stack.Push(d / 100); ////push it back
                        }

                        i = i + 1;
                        continue;
                    }

                    if (formula[i] == sheetToken)
                    {
                        sheet = formula[i].ToString();
                        i++;
                        while (i < formula.Length && formula[i] != sheetToken)
                        {
                            sheet += formula[i];
                            i++;
                        }

                        if (i < formula.Length)
                        {
                            sheet += formula[i];
                            i++;
                        }
                        else
                        {
                            continue; ////skip out as something is wrong
                        }
                    }

                    if (formula.Substring(i).StartsWith(TRUEVALUESTR))
                    {
                        _stack.Push(TRUEVALUESTR);
                        i += TRUEVALUESTR.Length;
                    }
                    else if (formula.Substring(i).StartsWith(FALSEVALUESTR))
                    {
                        _stack.Push(FALSEVALUESTR);
                        i += FALSEVALUESTR.Length;
                    }
                    else if (formula[i] == TIC[0])
                    {
                        string s = formula[i].ToString();
                        i++;
                        while (i < formula.Length && formula[i] != TIC[0])
                        {
                            s = s + formula[i];
                            i = i + 1;
                        }

                        _stack.Push(s + TIC);
                        i += 1;
                    }
                    else if (char.IsUpper(formula[i]))
                    {
                        ////cell loc
                        string s = string.Empty;
                        while (i < formula.Length && char.IsUpper(formula[i]))
                        {
                            s = s + formula[i];
                            i = i + 1;
                        }

                        while (i < formula.Length && char.IsDigit(formula[i]))
                        {
                            s = s + formula[i];
                            i = i + 1;
                        }

                        s = sheet + s;
                        sheet = string.Empty;
                        if (s == cell)
                        {
                            computedValueLevel = 0;
                            Hashtable ht = (Hashtable)DependentCells[s];
                            if (ht != null && ht.ContainsKey(s))
                            {
                                ht.Remove(s);
                            }

                            ClearFormulaDependentCells(cell);

                            if (circCheckList != null)
                            {
                                circCheckList.Add(this.cell);
                                return "0";
                            }

                            _stack.Push("#REF!");
                            break;
                            //throw new ArgumentException(FormulaErrorStrings[circular_reference_] + s);
                        }

                        if (circCheckList != null)
                        {
                            circCheckList.Add(s);
                        }

                        UpdateDependencies(s);

                        stringOK = true;
                        string o = GetValueFromGrid(s);
                        stringOK = false;
                        double d;
                        if (o != null && o.EndsWith("%") && double.TryParse(o.Substring(0, o.Length - 1), out d))
                        {
                            o = (d / 100).ToString();
                        }

                        if (uFound && o != null && double.TryParse(o, out d))
                        {
                            o = (-d).ToString();
                        }

                        uFound = false;
                        _stack.Push(o);
                    }
                    else if (formula[i] == 'q')
                    {
                        ////library
                        formula = ComputeInteriorFunctions(formula, circCheckList);

                        int ii = formula.Substring(i + 1).IndexOf(LEFTBRACKET);
                        if (ii > 0)
                        {
                            int bracketCount = 0;
                            bool bracketFound = false;
                            int start = ii + i + 2;
                            int k = start;
                            while (k < formula.Length && (formula[k] != RIGHTBRACKET || bracketCount > 0))
                            {
                                if (formula[k] == LEFTBRACKET)
                                {
                                    bracketCount++;
                                    bracketFound = true;
                                }
                                else if (formula[k] == LEFTBRACKET)
                                {
                                    bracketCount--;
                                }

                                k++;
                            }

                            if (bracketFound)
                            {
                                string s = formula.Substring(start, k - start - 2);
                                string s1 = string.Empty;
                                foreach (string t in s.Split(new Char[] { ParseArgumentSeparator }))
                                {
                                    if (s1.Length > 0)
                                    {
                                        s1 += ",";
                                    }

                                    ////int j = t.LastIndexOf('q');
                                    int j = FindLastqNotInBrackets(t);
                                    if (j > 0)
                                    {
                                        s1 += t.Substring(0, j) + ComputedValue(t.Substring(j), circCheckList);
                                    }
                                    else
                                    {
                                        s1 += ComputedValue(t, circCheckList);
                                    }
                                }

                                formula = formula.Substring(0, start) + s1 + formula.Substring(k - 2);
                            }

                            string name = formula.Substring(i + 1, ii);
                            if (this.LibraryFunctions[name] != null)
                            {
                                int j = formula.Substring(i + ii + 1).IndexOf(RIGHTBRACKET);
                                string args = formula.Substring(i + ii + 2, j - 1);
                                if (circCheckList != null)
                                {
                                    GetCellsInArgs(circCheckList, args);
                                    _stack.Push("0");
                                }
                                else
                                {
                                    try
                                    {
                                        functionEngineContext = this;
                                        LibraryFunction func = (LibraryFunction)this.LibraryFunctions[name];
                                        this.activeFunctionName = name;
                                        String result = func(args);
                                        if (UseNoAmpersandQuotes && result.Length > 1 && result.StartsWith(TIC) && result.EndsWith(TIC))
                                        {
                                            result = result.Substring(1, result.Length - 2);
                                        }

                                        double d = 0;
                                        if (uFound && result != null && double.TryParse(result, out d))
                                        {
                                            result = (-d).ToString();
                                        }

                                        uFound = false;
                                        _stack.Push(result);
                                        this.activeFunctionName = string.Empty;
                                        functionEngineContext = null;
                                    }
                                    catch (Exception ex)
                                    {
                                        TraceUtil.TraceExceptionCatched(ex);
                                        if (circCheckList != null)
                                        {
                                            circCheckList.Add(this.cell);
                                            return "0";
                                        }

                                        if (!ExceptionManager.RaiseExceptionCatched(this, ex))
                                        {
                                            throw ex;
                                        }

                                        return ex.Message;
                                    }
                                }

                                i += j + ii + 2;
                            }
                            else
                            {
                                if (circCheckList != null)
                                {
                                    circCheckList.Add(this.cell);
                                    return "0";
                                }

                                return FormulaErrorStrings[missing_formula];
                            }
                        }
                        else if (formula[0] == BMARKER)
                        {
                            ////Restart the processing with the formula without library finctions.
                            i = 0;
                            continue;
                        }
                        else
                        {
                            if (circCheckList != null)
                            {
                                circCheckList.Add(this.cell);
                                return "0";
                            }

                            return FormulaErrorStrings[improper_formula];
                        }
                    }
                    else if (char.IsDigit(formula[i]) || formula[i] == 'u')
                    {
                        string s = string.Empty;
                        if (formula[i] == 'u')
                        {
                            s = "-";
                            i++;
                        }
                        else if (uFound)
                        {
                            s = "-";
                        }

                        uFound = false;
                        while (i < formula.Length && (char.IsDigit(formula[i]) || formula[i] == ParseDecimalSeparator))
                        {
                            s = s + formula[i];
                            i = i + 1;
                        }

                        _stack.Push(s);
                    }
                    else
                    {
                        switch (formula[i])
                        {
                            case '#':
                                {
                                    i = i + 4;
                                    _stack.Push("#N/A");

                                    break;
                                }

                            case 'n':
                                {
                                    i = i + 1;

                                    string s = string.Empty;
                                    if (formula.Substring(i).StartsWith("Infinity"))
                                    {
                                        s = "Infinity";
                                        i += s.Length;
                                    }
                                    else if (formula.Substring(i).StartsWith(TRUEVALUESTR))
                                    {
                                        s = TRUEVALUESTR;
                                        i += s.Length;
                                    }
                                    else if (formula.Substring(i).StartsWith(FALSEVALUESTR))
                                    {
                                        s = FALSEVALUESTR;
                                        i += s.Length;
                                    }
                                    else if (i < formula.Length - 3 && formula.Substring(i, 3) == "NaN")
                                    {
                                        i += 3;
                                        s = "0";
                                    }
                                    else
                                    {
                                        if (formula[i] == 'u' || uFound)
                                        {
                                            s = "-";
                                            if (!uFound)
                                            {
                                                i = i + 1;
                                            }
                                            else
                                            {
                                                uFound = false;
                                            }
                                        }

                                        while (i < formula.Length && (char.IsDigit(formula[i]) || formula[i] == ParseDecimalSeparator))
                                        {
                                            s = s + formula[i];
                                            i = i + 1;
                                        }

                                        ////Check for exp values.
                                        if (i < formula.Length - 3 && formula[i] == 'E' && (formula[i + 1] == '+' || formula[i + 1] == '-'))
                                        {
                                            s = s + formula[i]; ////E
                                            i = i + 1;
                                            s = s + formula[i]; ////sign
                                            i = i + 1;
                                            s = s + formula[i]; ////first digit
                                            i = i + 1;
                                            while (i < formula.Length && (char.IsDigit(formula[i]) || formula[i] == ParseDecimalSeparator))
                                            {
                                                s = s + formula[i];
                                                i = i + 1;
                                            }
                                        }

                                        if (i < formula.Length && formula[i] == '%')
                                        {
                                            i = i + 1;
                                            if (s.Length == 0)
                                            {
                                                if (_stack.Count > 0)
                                                {
                                                    object o = _stack.Peek();
                                                    double d;
                                                    if (double.TryParse(o.ToString(), out d))
                                                    {
                                                        _stack.Pop(); ////remove it
                                                        s = (d / 100).ToString(); ////push it back
                                                    }
                                                }
                                            }
                                            else
                                            {
                                                s = (double.Parse(s) / 100).ToString();
                                            }
                                        }
                                    }

                                    _stack.Push(s);
                                }

                                break;
                            case TOKEN_add:
                                {
                                    double d, d1;
                                    DateTime result, result1;
                                    bool isDateTime = false;
                                    if (this.cell != null && double.TryParse(_stack.ToArray()[1].ToString(), NumberStyles.Number | NumberStyles.Currency, this.grid.Model[this.RowIndex(this.cell), this.ColIndex(this.cell)].CultureInfo, out d1) && double.TryParse(_stack.Peek().ToString(), NumberStyles.Number | NumberStyles.Currency, this.grid.Model[this.RowIndex(this.cell), this.ColIndex(this.cell)].CultureInfo, out d))
                                    {
                                        _stack.Pop();
                                        _stack.Pop();
                                        _stack.Push((d1 + d).ToString());
                                    }
                                    else if (this.cell != null)
                                    {
                                        string s1 = _stack.Peek().ToString().Replace(this.TIC, string.Empty);
                                        if (DateTime.TryParse(s1, out result))
                                        {
                                            d = result.ToOADate();
                                            Pop(_stack);
                                            isDateTime = true;
                                        }
                                        else
                                        {
                                            d = Pop(_stack);
                                        }
                                        string s2 = _stack.ToArray()[0].ToString().Replace(this.TIC, string.Empty);
                                        if (DateTime.TryParse(s2, out result1))
                                        {
                                            d1 = result1.ToOADate();
                                            Pop(_stack);
                                            isDateTime = true;
                                        }
                                        else
                                        {
                                            d1 = Pop(_stack);
                                        }
                                        Double TotalDays = d + d1;
                                        if (this.grid.CurrentCellRenderer != null)
                                        {
                                            GridStyleInfo style = this.grid.CurrentCellRenderer.CurrentStyle;

                                            if (TotalDays > 0)
                                            {
                                                if (isDateTime)
                                                {
                                                    DateTime dt = DateTime.FromOADate(TotalDays);
                                                    string DateString = dt.ToString();
                                                    if (!style.Format.Equals(string.Empty))
                                                        DateString = string.Format("{0:" + style.Format + "}", dt);
                                                    else
                                                        DateString = dt.ToShortDateString();
                                                    _stack.Push(DateString);
                                                }
                                                else
                                                    _stack.Push(TotalDays.ToString());
                                            }
                                            else
                                            {
                                                _stack.Push("#N/A");
                                            }
                                        }
                                        else
                                        {
                                            _stack.Push(TotalDays.ToString());
                                        }
                                    }
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_subtract:
                                {
                                    double d, d1;
                                    DateTime result;
                                    if (this.cell != null && double.TryParse(_stack.ToArray()[1].ToString(), NumberStyles.Number | NumberStyles.Currency, this.grid.Model[this.RowIndex(this.cell), this.ColIndex(this.cell)].CultureInfo, out d1) && double.TryParse(_stack.Peek().ToString(), NumberStyles.Number | NumberStyles.Currency, this.grid.Model[this.RowIndex(this.cell), this.ColIndex(this.cell)].CultureInfo, out d))
                                    {
                                        _stack.Pop();
                                        _stack.Pop();
                                        _stack.Push((d1 - d).ToString());
                                    }
                                    else if (this.cell != null && DateTime.TryParse(_stack.Peek().ToString(), out result)
                                            && DateTime.TryParse(_stack.ToArray()[1].ToString(), out result))
                                    {
                                        DateTime date = DateTime.Parse(_stack.Pop().ToString());
                                        DateTime date1 = DateTime.Parse(_stack.Pop().ToString());
                                        Double TotalDays = (date1 - date).TotalDays;
                                        if (this.grid.CurrentCellRenderer != null)
                                        {
                                            GridStyleInfo style = this.grid.CurrentCellRenderer.CurrentStyle;
                                            if (!style.Format.Equals(string.Empty))
                                            {
                                                if (TotalDays > 0)
                                                {
                                                    DateTime dt = DateTime.FromOADate(TotalDays + 1);
                                                    string DateString = string.Format("{0:" + style.Format + "}", dt);
                                                    _stack.Push(DateString);
                                                }
                                                else
                                                {
                                                    _stack.Push("#N/A");
                                                }
                                            }
                                            else
                                            {
                                                _stack.Push(TotalDays.ToString());
                                            }
                                        }
                                        else
                                        {
                                            _stack.Push(TotalDays.ToString());
                                        }
                                    }
                                    else
                                    {
                                        d = Pop(_stack);
                                        d1 = Pop(_stack);
                                        _stack.Push((d1 - d).ToString());
                                    }
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_multiply:
                                {
                                    double d, d1;
                                    if (this.cell != null && double.TryParse(_stack.ToArray()[1].ToString(), NumberStyles.Number | NumberStyles.Currency, this.grid.Model[this.RowIndex(this.cell), this.ColIndex(this.cell)].CultureInfo, out d1) && double.TryParse(_stack.Peek().ToString(), NumberStyles.Number | NumberStyles.Currency, this.grid.Model[this.RowIndex(this.cell), this.ColIndex(this.cell)].CultureInfo, out d))
                                    {
                                        _stack.Pop();
                                        _stack.Pop();
                                    }
                                    else
                                    {
                                        d = Pop(_stack);
                                        d1 = Pop(_stack);
                                    }

                                    _stack.Push((d1 * d).ToString());
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_divide:
                                {
                                    double d, d1;
                                    if (this.cell != null && double.TryParse(_stack.ToArray()[1].ToString(), NumberStyles.Number | NumberStyles.Currency, this.grid.Model[this.RowIndex(this.cell), this.ColIndex(this.cell)].CultureInfo, out d1) && double.TryParse(_stack.Peek().ToString(), NumberStyles.Number | NumberStyles.Currency, this.grid.Model[this.RowIndex(this.cell), this.ColIndex(this.cell)].CultureInfo, out d))
                                    {
                                        _stack.Pop();
                                        _stack.Pop();
                                    }
                                    else
                                    {
                                        d = Pop(_stack);
                                        d1 = Pop(_stack);
                                    }

                                    _stack.Push((d1 / d).ToString());
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_EP:
                                {
                                    double d = Pop(_stack); ////double.Parse(g);
                                    double d1 = Pop(_stack); ////double.Parse(g1);

                                    _stack.Push((d1 * Math.Pow(10, d)).ToString());
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_EM:
                                {
                                    double d = Pop(_stack);
                                    double d1 = Pop(_stack);

                                    _stack.Push((d1 * Math.Pow(10, -d)).ToString());
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_less:
                                {
                                    string s1 = PopString(_stack);
                                    string s2 = PopString(_stack);
                                    double d, d1;
                                    string val;
                                    if (ParsePossibleEmptyStrings(s1, s2, out d, out d1))
                                    {
                                        val = (d1 < d) ? TRUEVALUESTR : FALSEVALUESTR;
                                    }
                                    else
                                    {
                                        val = (s2.ToUpper().Replace(TIC, string.Empty).CompareTo(s1.ToUpper().Replace(TIC, string.Empty)) < 0) ? TRUEVALUESTR : FALSEVALUESTR;
                                    }

                                    _stack.Push(val);
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_greater:
                                {
                                    string s1 = PopString(_stack);
                                    string s2 = PopString(_stack);
                                    double d, d1, d2;
                                    string val;
                                    if (ParsePossibleEmptyStrings(s1, s2, out d, out d1))
                                    {
                                            val = (d1 > d) ? TRUEVALUESTR : FALSEVALUESTR;
                                    }
                                    else
                                    {
                                        if (double.TryParse(s2, NumberStyles.Currency, this.grid.Model[this.RowIndex(this.cell), this.ColIndex(this.cell)].CultureInfo, out d2))
                                        {
                                            val = (d2.ToString().ToUpper().Replace(TIC, string.Empty).CompareTo(s1.ToUpper().Replace(TIC, string.Empty)) > 0) ? TRUEVALUESTR : FALSEVALUESTR;
                                        }
                                        else
                                        {
                                            val = (s2.ToUpper().Replace(TIC, string.Empty).CompareTo(s1.ToUpper().Replace(TIC, string.Empty)) > 0) ? TRUEVALUESTR : FALSEVALUESTR;
                                        }
                                    }
                                    if ((s2.Equals(string.Empty) || s2.Equals(" ")))
                                        val = TRUEVALUESTR;

                                    _stack.Push(val);
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_equal:
                                {
                                    string s1 = PopString(_stack);
                                    string s2 = PopString(_stack);
                                    double d, d1;
                                    string val;
                                    if (ParsePossibleEmptyStrings(s1, s2, out d, out d1))
                                    {
                                        val = (d1 == d) ? TRUEVALUESTR : FALSEVALUESTR;
                                    }
                                    else
                                    {
                                        if ((s1.Length > 0 && s1[0] == '#')
                                            || (s2.Length > 0 && s2[0] == '#'))
                                        {
                                            val = "#N/A";
                                        }
                                        else
                                        {
                                            val = (s1.ToUpper().Replace(TIC, string.Empty) == s2.ToUpper().Replace(TIC, string.Empty)) ? TRUEVALUESTR : FALSEVALUESTR;
                                        }
                                    }

                                    _stack.Push(val);
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_lesseq:
                                {
                                    string s1 = PopString(_stack);
                                    string s2 = PopString(_stack);
                                    double d, d1;
                                    DateTime date, date1;
                                    string val;
                                    if (ParsePossibleEmptyStrings(s1, s2, out d, out d1))
                                    {
                                        val = (d1 <= d) ? TRUEVALUESTR : FALSEVALUESTR;
                                    }
                                    else
                                    {
                                        if (DateTime.TryParse(s1.ToUpper().Replace(TIC, string.Empty), out date) && DateTime.TryParse(s2.ToUpper().Replace(TIC, string.Empty), out date1))
                                        {
                                            val = (DateTime.Compare(date1, date) <= 0) ? TRUEVALUESTR : FALSEVALUESTR;
                                        }
                                        else
                                        {
                                            val = (s2.ToUpper().Replace(TIC, string.Empty).CompareTo(s1.ToUpper().Replace(TIC, string.Empty)) <= 0) ? TRUEVALUESTR : FALSEVALUESTR;
                                        }
                                    }

                                    _stack.Push(val);
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_greatereq:
                                {
                                    string s1 = PopString(_stack);
                                    string s2 = PopString(_stack);
                                    double d, d1;
                                    DateTime date, date1;
                                    string val;
                                    if (ParsePossibleEmptyStrings(s1, s2, out d, out d1))
                                    {
                                        val = (d1 >= d) ? TRUEVALUESTR : FALSEVALUESTR;
                                    }
                                    else
                                    {
                                        if (DateTime.TryParse(s1.ToUpper().Replace(TIC, string.Empty), out date) && DateTime.TryParse(s2.ToUpper().Replace(TIC, string.Empty), out date1))
                                        {
                                            val = (DateTime.Compare(date1, date) >= 0) ? TRUEVALUESTR : FALSEVALUESTR;
                                        }
                                        else
                                        {
                                            val = (s2.ToUpper().Replace(TIC, string.Empty).CompareTo(s1.ToUpper().Replace(TIC, string.Empty)) >= 0) ? TRUEVALUESTR : FALSEVALUESTR;
                                        }
                                    }

                                    _stack.Push(val);
                                    i = i + 1;
                                }

                                break;
                            case TOKEN_noequal:
                                {
                                    string s1 = PopString(_stack);
                                    string s2 = PopString(_stack);
                                    double d, d1;
                                    string val;
                                    if (ParsePossibleEmptyStrings(s1, s2, out d, out d1))
                                    {
                                        val = (d1 != d) ? TRUEVALUESTR : FALSEVALUESTR;
                                    }
                                    else
                                    {
                                        val = (s1.ToUpper().Replace(TIC, string.Empty) != s2.ToUpper().Replace(TIC, string.Empty)) ? TRUEVALUESTR : FALSEVALUESTR;
                                    }

                                    _stack.Push(val);
                                    i = i + 1;
                                }
                                ////                                    {
