    /// Settings determine whether the formula or the calculated result is copied
    /// and whether formula references are updated when cells containing formulas are pasted or dropped.
    /// </remarks>
    [Flags]
    public enum GridFormulaCopyFlags
    {
        /// <summary>
        /// No copy flags set.
        /// </summary>
        None = 0x00,

        /// <summary>
        /// The computed value text is placed on the Clipboard.
        /// </summary>
        ClipBoardText = 0x01,

        /// <summary>
        /// The formula text is placed on the Clipboard.
        /// </summary>
        ClipBoardFormula = 0x02,

        /// <summary>
        /// Cell references in pasted formulas are adjusted for their new location.
        /// </summary>
        ClipBoardReferencesAdjusted = 0x04,

        ////        /// <summary>
        ////        /// The computed value text is placed in the DataObject.
        ////        /// </summary>
        ////        DnDText        = 0x08,
        ////        /// <summary>
        ////        /// The formula text is placed in the DataObject.
        ////        /// </summary>
        ////        DnDFormula    = 0x10,
        ////        /// <summary>
        ////        /// Allow extend existing selection when user holds Shift Key and clicks on a cell.
        ////        /// </summary>
        ////        DndReferencesAdjusted      = 0x20,
        ////        /// <summary>
        ////        /// Cell references are updated when rows or columns are moved.
        ////        /// </summary>
        ////        MovedRangeReferencesUpdated      = 0x40,

        /// <summary>
        /// Cell references are updated when rows or columns are removed or inserted.
        /// </summary>
        InsDelRangeReferencesUpdated = 0x80,

        /// <summary>
        /// Cell references are updated when rows or columns are removed or inserted.
        /// </summary>
        NamedRangeReferencesUpdated = 0x100,

        /// <summary>
        /// Cell references are updated if the cell is moved using an Ole Drag and Drop operation within the same GridControl.
        /// </summary>
        UpdateReferencesDuringDnD = 0x200
